import{b as E}from"./c-K5YPFHWY.js";import{a as V}from"./c-4TIYSYRS.js";import{c as G}from"./c-LV7NOCMP.js";var e=(s,n,o,l)=>({title:s,points:n,commentary:o,focus:l}),t=(s,n,o,l)=>({label:s,value:n,unit:o,spoken:l});var U={"ards-after-pneumonia":{presentation:e("Pneumonia progresses despite invasive support",["54 years","Second day of severe pneumonia","Bilateral opacities develop within 48 hours","Escalating oxygen requirement"],"We enter the case after intubation, when the presence of a ventilator can create a false sense that the respiratory problem has been solved. The rising oxygen requirement tells us the physiology is still evolving."),assessment:e("Define the respiratory syndrome in context",["Bilateral breath sounds","Sedated and mechanically ventilated","Assess cardiac and fluid contributions"],"The examination helps us check immediate alternatives and the broader cause of the opacities. A label of ARDS needs the clinical context; bilateral imaging findings alone are not the whole diagnosis."),vitals:e("Significant support, persistent hypoxemia",[],"Read the saturation alongside the amount of oxygen and pressure being delivered. A number has a different meaning when it takes substantial support to achieve it.",{label:"Support context",text:"SpO\u2082 89% on FiO\u2082 0.80 and PEEP 10 cmH\u2082O"}),labs:e("Relate arterial oxygen to inspired oxygen",[],"The oxygenation ratio helps express how impaired gas exchange is on the current support. It describes severity; it does not choose a safe tidal volume or replace a pressure assessment.",{label:"Current oxygenation",text:"PaO\u2082/FiO\u2082 \u2248 73 mmHg"}),diagnostics:e("A severe ARDS phenotype",["Acute timing and bilateral opacities","Severe oxygenation impairment","Assess a primarily hydrostatic explanation"],"The pattern supports a severe lung injury syndrome after the competing explanation is assessed. We now have to support gas exchange without adding avoidable injury through the way we ventilate."),decision:e("Should tidal volume be the first answer?",["Predicted body weight","Plateau pressure and synchrony","PEEP tolerance","Severe-ARDS strategies"],"Imagine the saturation rises after a larger breath. What else would you need to know before calling that a good treatment response? Think about pressure, injury and circulation."),reasoning:e("Oxygenation and lung protection belong together",["Verify height and predicted-body-weight strategy","Assess pressures and PEEP response","Coordinate proning or specialist referral when indicated"],"The ventilator plan is a balance of physiological goals. The team needs to know not only the settings but the height, pressure measurements, response and operational limits behind them."),reassessment:e("Measure the response to the revised plan",["Repeat blood gas","Reassess pressures","Follow perfusion and support requirements"],"A better saturation is useful evidence, but it does not tell us the injured lung has recovered. Continued pressure and perfusion assessment helps us judge the overall response."),synopsis:e("Severe ARDS: support exchange while limiting injury",["Interpret oxygenation with its support","Use predicted body weight and pressure assessment","Reassess lungs and circulation"],"The case begins with an oxygen problem and expands into a ventilation strategy. Carry that balance into the physiology lesson rather than treating saturation as the sole endpoint.")},"ards-peep-hypotension":{presentation:e("One adjustment, two opposing responses",["62 years \xB7 ARDS","PEEP increased from 10 to 16 cmH\u2082O","Saturation rises","Pressure falls immediately; no new medication"],"The sequence is unusually informative. One intervention is followed immediately by a better oxygen number and a worse circulation. That is a reason to reassess the net effect."),assessment:e("The patient is less well perfused",["Cooler extremities","Weaker pulses","Bilateral breath sounds","Check tube, circuit, lungs and circulation"],"The examination confirms that the pressure change matters to the patient. We also keep immediate alternatives in view instead of assigning every new finding to the ventilator change."),vitals:e("Put the before and after values side by side",[],"The paired trends are the center of the case. The saturation gain is real, and so is the pressure loss. The decision has to account for both.",{label:"Before \u2192 after",text:"SpO\u2082 89 \u2192 95%; BP 112/68 \u2192 76/44 mmHg"}),labs:e("Gas exchange does not describe perfusion by itself",[],"The oxygen result describes one side of the response. The lactate and bedside perfusion findings help us assess the other side, with timing and alternative causes kept in mind.",{label:"Ask about overall benefit",text:"Better arterial oxygen can coexist with worse circulation"}),diagnostics:e("Reassess the mechanism of hypotension",["Reduced venous return or RV effects","Overdistension","Pneumothorax or another acute cause","Verify measurements"],"A close temporal relationship suggests a mechanism, but it is not a reason to stop checking. We need a rapid assessment that can detect both treatment intolerance and a separate emergency."),decision:e("Is 95% a successful endpoint here?",["Pressure has fallen","Peripheral perfusion is worse","The intervention needs reassessment"],"If you were given only the new saturation, you might keep the change. Add the pressure and examination back in, then decide how the next adjustment should be judged."),reasoning:e("Find a tolerated ventilation strategy",["Reassess the recent PEEP change","Evaluate other immediate hypotension causes","Trend pressure, perfusion and gas exchange"],"The goal is an individualized strategy with a tolerable overall effect. Coordinate the respiratory and circulatory plan instead of letting separate numbers produce conflicting orders."),reassessment:e("Handoff the opposing responses",["Support plan revised","Repeat perfusion and gas-exchange checks","Document the PEEP change and timing"],"The most useful handoff is the experiment the patient has already undergone: what was changed, what improved and what worsened. That prevents the next team from unknowingly repeating it."),synopsis:e("PEEP response: assess the whole physiological effect",["Recruitment can carry a circulatory cost","Temporal change guides investigation","Use multiple endpoints"],"The turning point was recognizing that improvement in one measurement did not describe improvement in the patient as a whole.")},"mi-inferior-rv":{presentation:e("An inferior injury pattern with low pressure",["58 years","Crushing chest pain and nausea","Inferior ECG pattern","Hypotension precedes any nitrate"],"The timing of the hypotension matters. It is already present before a vasodilator is given, so the team needs to understand the circulation before adding a treatment that may lower pressure further."),assessment:e("Clear lungs do not clear the circulation",["Pallor and diaphoresis","Elevated neck veins","Clear lung fields","Assess conduction and RV involvement"],"The combination of neck veins, clear lungs and low pressure suggests a useful physiological question about the right ventricle. It also reminds us to keep the rhythm in the assessment."),vitals:e("Bradycardia and hypotension in context",[],"A slow heart rate has a different significance in a patient who is pale, diaphoretic and hypotensive with an ischemic story. Follow the rhythm and perfusion together.",{label:"Clinical context",text:"Heart rate 52/min with BP 84/56 mmHg"}),labs:e("An early negative troponin is not a veto",[],"The sample was taken early. The clinical presentation and the time-critical ECG pattern must still drive the urgent pathway; a biomarker timeline should not delay that response.",{label:"Sequence matters",text:"Early sampling can precede a diagnostic troponin rise"}),diagnostics:e("Inferior injury with a right-sided clue",["ST elevation: II, III and aVF","Reciprocal change: I and aVL","ST elevation in V4R","Synthetic ECG report"],"For an audio listener, the key is the distribution and the added right-sided finding. Those observations support concern for right-ventricular involvement in the patient\u2019s clinical context."),decision:e("What should overrule the early negative sample?",["Ischemic symptoms","Time-critical ECG pattern","Hypotension and perfusion findings"],"Consider two potential delays: waiting for another troponin and giving a routine medication before assessing its hemodynamic effect. Decide which information should organize the next minutes."),reasoning:e("Reperfusion with a circulation-aware plan",["Activate the reperfusion pathway","Avoid worsening existing hypotension","Assess volume response individually","Prepare for conduction complications"],"Urgent coronary care and bedside stabilization proceed together. The receiving team needs to know why pressure, preload and rhythm are part of this particular infarction handoff."),reassessment:e("Keep the ECG and perfusion timeline visible",["Catheterization team notified","Right-sided findings communicated","Serial ECG and perfusion checks continue"],"The handoff should say what was present before treatment as well as after it. That distinction helps the next team interpret any new pressure or rhythm change."),synopsis:e("Inferior MI: the early biomarker does not settle the emergency",["Use the clinical ECG pattern","Assess RV involvement and rhythm","Plan medication effects around existing hypotension"],"The case links electrical territory to circulation. Remember the clear lungs and low pressure alongside the inferior and right-sided ECG findings.")},"mi-anterior-shock":{presentation:e("Chest pain becomes a breathing and perfusion emergency",["67 years","90 minutes of chest pain","Anterior injury pattern","Breathlessness, confusion and falling pressure"],"The problem has evolved beyond a chest pain complaint. The change in breathing and mental status asks us to organize urgent coronary care and shock support at the same time."),assessment:e("Wet lungs, poor forward flow",["Bilateral crackles","Cool, clammy skin","Weak pulses","Assess for a new murmur or mechanical complication"],"Congestion and systemic hypoperfusion can coexist. The examination needs to look for both, while remaining alert to a complication that could alter the immediate intervention."),vitals:e("Oxygenation and circulation are both failing",[],"The low pressure and hypoxemia are simultaneous problems. The next respiratory intervention should be planned with its possible hemodynamic effect already in mind.",{label:"Combined emergency",text:"BP 78/50 mmHg; SpO\u2082 86% on room air"}),labs:e("Evidence of systemic stress",[],"The laboratory findings add to the evidence of myocardial injury and impaired perfusion. They support urgency while the reperfusion and complication assessment proceeds.",{label:"Integrate the evidence",text:"ECG + examination + perfusion + laboratory findings"}),diagnostics:e("Anterior infarction with severe LV dysfunction",["Anterior ST elevation reported","Severe LV systolic dysfunction","Evaluate mechanical complications"],"The bedside echo helps define ventricular function. The assessment also needs to look for a mechanical problem, because identifying one could change both the support and definitive treatment plan."),decision:e("Can congestion coexist with shock?",["Pulmonary edema","Weak pulses and confusion","Low pressure","Need for urgent reperfusion"],"Think about the risk of treating either the lungs or the blood pressure in isolation. Which plan would address the shared cardiac problem while definitive coronary care is arranged?"),reasoning:e("Reperfuse and support the failing circulation",["Urgent coronary and shock-team activation","Coordinated respiratory and circulatory support","Evaluate complications and advanced support needs"],"The destination must match the severity. Early communication allows the receiving team to prepare definitive intervention and the level of support the patient may need on arrival."),reassessment:e("Prepare the receiving intervention",["Communicate ECG and symptom timeline","Track pressure and respiratory support","Report complication assessment"],"A useful transfer summary explains how the patient changed, not only where the ECG elevation was. It should show whether each support intervention was tolerated."),synopsis:e("Anterior MI with shock: address congestion and low output",["Recognize simultaneous lung and perfusion findings","Pursue urgent reperfusion","Assess complications and support tolerance"],"The clinical task was keeping definitive coronary treatment and active shock resuscitation connected throughout the transfer plan.")},"sepsis-older-hypothermic":{presentation:e("The handoff says weakness",["79 years","Dysuria followed by new confusion","Reduced intake and urine output","Cold rather than febrile"],"The word weakness compresses a complex story into a low-urgency label. Reconstruct the change from baseline, especially the new confusion and reduced urine output."),assessment:e("The examination suggests systemic illness",["Altered attention","Mottling and delayed refill","Evaluate infection and other shock causes"],"These are findings about perfusion and organ function. They deserve an urgent explanation even when the temperature does not follow the familiar fever pattern."),vitals:e("Hypothermia does not remove infection from consideration",[],"The low temperature sits beside tachycardia, tachypnea and hypotension. Read that cluster before deciding that an afebrile patient is unlikely to have a serious infection.",{label:"Whole pattern",text:"35.3\xB0C with BP 82/46 mmHg and altered attention"}),labs:e("Organ dysfunction and a possible source",[],"The creatinine change adds a comparison with baseline. The urine findings fit part of the history, but they do not prove that every feature comes from a urinary source.",{label:"Baseline \u2192 now",text:"Creatinine 0.9 \u2192 2.2 mg/dL"}),diagnostics:e("Treat suspected sepsis; continue the source assessment",["Suspected infection with organ dysfunction","Poor perfusion","Urinary source remains a working explanation"],"A working diagnosis can support timely treatment without becoming a fixed conclusion. The team still needs to evaluate source control needs and alternatives to septic shock."),decision:e("Would the absence of fever delay you?",["New confusion","Hypotension and mottling","Reduced urine output","Hypothermia"],"Imagine the temperature were the only normal-looking part of the story. Which remaining observations already require resuscitation and urgent investigation?"),reasoning:e("Act on illness severity while clarifying the source",["Timely antimicrobials and cultures","Assess fluid response and tolerance","Indicated vasoactive support","Evaluate source control and alternatives"],"The first interventions should produce information as well as support. Reassess the circulation and the suspected source instead of letting the initial label replace the next examination."),reassessment:e("Revisit pressure, perfusion and urine output",["Repeat clinical perfusion assessment","Follow pressure and urine trends","Continue source evaluation"],"A better monitor number can occur before the patient\u2019s organ function has recovered. The handoff should make clear which parts of the response are established and which remain unresolved."),synopsis:e("Sepsis in an older adult: the presentation may be cold and confused",["Reconstruct the change from baseline","Use perfusion and organ findings","Keep the source as a testable working diagnosis"],"The useful correction was moving from a vague symptom label to a physiological assessment of a patient whose usual function had changed.")},"sepsis-persistent-shock":{presentation:e("The pressure improves before the patient does",["46 years \xB7 abdominal infection","Antibiotics and resuscitation started","Vasopressor restores measured pressure","Mottling and abdominal findings worsen"],"We arrive after one treatment target has improved. The question is whether that target describes enough of the circulation and whether the underlying infection has been controlled."),assessment:e("Persistent hypoperfusion remains visible",["Distended, tender abdomen","Mottled extremities","Low urine output","Reassess the source and circulation"],"The bedside findings prevent a premature finish line. They tell us the improved pressure has not resolved the whole problem and that the source remains clinically important."),vitals:e("A MAP value is one piece of the response",[],"The displayed mean pressure is achieved on support. Its meaning depends on what is happening to the rest of the perfusion assessment and the support requirement.",{label:"Current support context",text:"MAP 68 mmHg on vasopressor; poor perfusion persists"}),labs:e("The trajectory is still concerning",[],"The lactate has risen, with acidemia and renal dysfunction adding context. No single result explains every mechanism, but the direction agrees with the concern from the bedside.",{label:"Earlier \u2192 now",text:"Lactate 5.9 \u2192 6.8 mmol/L"}),diagnostics:e("A source that needs definitive control",["CT report: free air and fluid","Suspected bowel perforation","Urgent surgical evaluation"],"Support can improve pressure without removing the infectious source. The imaging report changes the definitive plan and the urgency of surgical coordination."),decision:e("Has resuscitation finished at MAP 68?",["Mottling persists","Urine output remains low","Lactate rises","The source is unresolved"],"Choose the next action as though you had to explain it to the receiving surgeon and intensivist together. The plan needs to address both the current physiology and its continuing cause."),reasoning:e("Continue support while pursuing source control",["Urgent surgical coordination","Reassess perfusion, cardiac function and fluid tolerance","Verify antimicrobial and vasoactive delivery"],"Treatment delivery also deserves a check. An escalating patient needs confirmation that the intended support is reaching them, alongside assessment of what the support cannot fix on its own."),reassessment:e("Handoff the unresolved perfusion problem",["Definitive surgical care prepared","Support maintained during transfer","Pressure response distinguished from clinical response"],"Say explicitly that pressure improved while mottling and oliguria persisted. That statement gives the next team the reason to continue reassessment despite the apparently acceptable number."),synopsis:e("Septic shock: a better pressure is an incomplete endpoint",["Follow clinical and laboratory trajectory","Identify unresolved source-control needs","Check response and treatment delivery"],"The case turns on the gap between the monitor and the patient. The next decision followed the unresolved findings rather than the most reassuring value.")},"pe-preserved-pressure":{presentation:e("Sudden breathlessness after surgery",["61 years","Day 8 after hip surgery","Sudden dyspnea and pleuritic discomfort","Tachycardic and hypoxemic"],"The postoperative history raises both thrombotic concern and treatment complexity. Keep the timing of surgery in view as we assess the severity and the options."),assessment:e("Clear lungs with a swollen calf",["Clear breath sounds","Unilateral calf swelling","Evaluate PE and postoperative alternatives"],"The lung examination does not explain the degree of breathlessness. The leg finding adds a clue, while the broader postoperative differential still deserves attention."),vitals:e("Maintained pressure does not establish low risk",[],"The pressure is preserved at this moment. The respiratory rate, hypoxemia and tachycardia show why the transfer still needs a careful risk assessment and deterioration plan.",{label:"Current state and trajectory",text:"BP 118/74 mmHg with SpO\u2082 88% on room air"}),labs:e("Biomarkers contribute to risk assessment",[],"An elevated troponin contributes information about the cardiac response in this setting. It does not select reperfusion treatment on its own, especially with recent surgery in the history.",{label:"Integrate, then decide",text:"Clinical status + imaging + biomarkers + bleeding risk"}),diagnostics:e("Confirmed PE with right-heart strain",["Bilateral emboli on synthetic CT report","Enlarged right ventricle","Recent surgery affects bleeding assessment"],"The CT establishes emboli in this case. The right-heart finding adds concern, but the treatment discussion still has to use the whole clinical risk profile rather than the appearance of the clot alone."),decision:e("Would you call this a routine transfer?",["Preserved pressure","Right-heart strain","Hypoxemia","Recent surgery"],"Think about what would change your monitoring and destination even without hypotension. Then consider how the recent operation affects the next treatment discussion."),reasoning:e("Coordinate treatment and a deterioration plan",["Oxygenation and anticoagulation planning","Critical care or PE-team risk discussion","Explicit postoperative bleeding assessment","Prepare for hemodynamic change"],"A stable reading is a moment, not a guarantee about the journey. The plan should describe what the team will do if the circulation changes and which center can provide the next level of care."),reassessment:e("Stable pressure still needs surveillance",["Pressure remains maintained","Monitoring continues","Treatment individualized to risk and trajectory"],"The absence of deterioration during observation is useful. It supports continued assessment rather than a claim that the right-heart findings or postoperative treatment risks have disappeared."),synopsis:e("PE: preserved pressure can coexist with important RV risk",["Use the full risk profile","Include bleeding considerations","Plan for a changing trajectory"],"The case asks us to interpret stability precisely: what is maintained now, what remains abnormal and what could change during transfer.")},"pe-circulatory-collapse":{presentation:e("Syncope followed by persistent shock",["57 years","Sudden dyspnea and brief collapse","Confusion and hypotension persist","No reported major trauma or external loss"],"Recovery of consciousness after a brief collapse does not mean the event is over. The persistent shock tells us that the underlying physiological problem remains active."),assessment:e("A possible obstructive circulation problem",["Weak pulses and cool extremities","Elevated neck veins","Relatively clear lungs","Consider cardiac and other shock causes"],"The pattern points us toward a circulation-focused assessment. It is suggestive, but it is not specific enough to replace a careful evaluation of competing causes of shock."),vitals:e("Profound instability changes diagnostic logistics",[],"These observations affect where testing can safely occur. Moving the patient for confirmation is itself a clinical decision with risks, not a neutral step on a checklist.",{label:"Immediate context",text:"BP 70/42 mmHg; SpO\u2082 84% on oxygen"}),labs:e("Severe perfusion stress adds urgency",[],"The laboratory pattern agrees with the bedside assessment. It helps describe severity while we organize support and an urgent diagnostic strategy that the patient can tolerate.",{label:"Assessment continues during support",text:"Lactate 7.2 mmol/L with acidemia"}),diagnostics:e("RV dysfunction supports concern, not certainty",["Dilated, poorly functioning RV","Not specific for acute PE","CT transport may be unsafe before stabilization"],"The echo is a piece of evidence in an unstable patient. Communicate both what it shows and what it cannot prove, because definitive treatment decisions depend on that distinction."),decision:e("What is the cost of confirmation away from resuscitation?",["Transport risk","Bedside diagnostic options","Alternative causes","Urgent specialist treatment strategy"],"Imagine the patient deteriorating in the scanner corridor. What support, evidence and shared decision would you want in place before committing to that movement?"),reasoning:e("Support the circulation and define a definitive pathway",["Critical care and PE-team activation","Anticipate airway and positive-pressure risk","Bedside assessment and reperfusion planning","Assess contraindications and alternatives"],"Airway induction is a major physiological event in a failing right ventricle. The respiratory and circulatory plans should be coordinated before an intervention that could abruptly change preload and pressure."),reassessment:e("Separate observations from the working diagnosis",["Receiving team selects a definitive pathway","Track support and response","Handoff diagnostic certainty explicitly"],"A clear handoff can be urgent without being overconfident. State the confirmed shock and RV findings, the suspected cause and the decisions made from the available evidence."),synopsis:e("Suspected high-risk PE: stabilize while defining the pathway",["Shock changes the order and location of testing","RV findings require context","Coordinate diagnostic, airway and reperfusion decisions"],"The most important step was matching the diagnostic plan to the patient\u2019s ability to tolerate it while support and expert coordination continued.")}};var _={"duct-systemic-shock":{presentation:e("A newborn becomes gray at home",["Term newborn \xB7 day 6 \xB7 3.2 kg","Feeding and urine output decline","Rapid breathing and poor responsiveness","No cardiac diagnosis before discharge"],"Discharge without a cardiac diagnosis can make the heart seem less likely to explain this presentation. The age and the changing circulation after birth keep it in the urgent differential."),assessment:e("Compare the upper and lower body",["Weak femoral pulses","Cool legs and delayed refill","Upper pulses easier to feel","Sepsis remains a competing concern"],"The pulse difference is a clue, not an anatomical diagnosis. Check the quality of the examination while treating the infant\u2019s poor perfusion as the immediate problem."),vitals:e("A saturation in the nineties can coexist with shock",[],"The right-hand saturation describes oxygenation in that location. It does not tell us that enough systemic flow is reaching the lower body or the kidneys.",{label:"Check the measurements and the infant",text:"Right arm 68/42; leg 44/26 mmHg"}),labs:e("The metabolic picture fits poor perfusion",[],"The acidemia and lactate support the urgency already visible at the bedside. Keep glucose and temperature in the stabilization plan while the cause is being defined.",{label:"Whole-infant support",text:"Perfusion \xB7 ventilation \xB7 glucose \xB7 temperature"}),diagnostics:e("Suspect duct-dependent flow; define anatomy urgently",["Age and perfusion raise cardiac concern","Expert echocardiography needed","Evaluate neonatal sepsis in parallel"],"We do not have to choose between acknowledging cardiac risk and evaluating infection. The infant needs urgent specialist input while those possibilities are addressed together."),decision:e("What does 94% fail to tell us?",["Systemic blood flow","Lower-body perfusion","The underlying cardiac anatomy"],"Imagine reporting only the saturation in a telephone handoff. Which crucial parts of this examination would the receiving team be missing?"),reasoning:e("Plan for circulation and transport capability",["Urgent neonatal and cardiac consultation","Specialist-directed discussion of prostaglandin","Prepare for apnea and airway support","Support perfusion, glucose and temperature"],"A medication plan also creates an operational plan. If prostaglandin is used, the team must be prepared for its potential effects and able to sustain the infusion and airway support during the journey."),reassessment:e("Describe observations without inventing anatomy",["Track limb pressures and pulse findings","Follow response and perfusion","Definitive anatomy remains a specialist assessment"],"A precise handoff separates what we measured, what we suspect and what has been confirmed. That distinction prevents an early working diagnosis from becoming an unsupported anatomical label."),synopsis:e("Duct-dependent systemic flow: shock may dominate",["Consider cardiac disease in the deteriorating newborn","Saturation alone cannot clear perfusion","Stabilize while obtaining definitive anatomy"],"The clue was the relationship between age, lower-body perfusion and the rest of the examination. The disease lesson will explain why postnatal circulatory change can produce that pattern.")},"duct-cyanotic-newborn":{presentation:e("Oxygen produces little change",["Term newborn \xB7 day 3 \xB7 3.5 kg","Central cyanosis","Poor feeding","Limited response to supplemental oxygen"],"When the expected response to oxygen is small, revisit the mechanism of the hypoxemia. The lungs are part of the question, but the route blood takes through the circulation matters too."),assessment:e("Cyanosis with modest visible effort",["Equal breath sounds","Modest respiratory effort","Consider cardiac, pulmonary and infectious causes"],"The degree of visible respiratory distress does not fully explain the cyanosis. That mismatch is a reason to broaden the evaluation rather than simply turn up the same support."),vitals:e("Compare preductal and postductal readings",[],"Both readings are very low. A small difference between the hand and foot does not establish normal cardiac anatomy; the pattern still needs expert interpretation.",{label:"On oxygen",text:"Right hand 76%; foot 74%"}),labs:e("The gas confirms severe hypoxemia",[],"The result describes the physiological problem on the current support. It does not tell us which lesion, if any, is present or what circulation balance that anatomy will require.",{label:"Next diagnostic task",text:"Define the cause, not only the oxygen number"}),diagnostics:e("Urgent echocardiography changes the plan",["Structural disease or pulmonary hypertension?","Assess lung disease and infection","Anatomy determines further goals"],"The purpose of echocardiography is practical: different circulations may need different support goals. We should avoid applying one generic target to every cyanotic newborn."),decision:e("What would you do while defining the circulation?",["Support breathing and oxygenation","Call neonatal cardiac expertise","Prepare transport and infusion capability"],"Think about the balance between immediate supportive care and time to a definitive explanation. Repeatedly increasing oxygen is not a substitute for that explanation."),reasoning:e("Link support to a specialist circulation plan",["Neonatal cardiac consultation","Specialist-directed prostaglandin discussion","Apnea readiness if therapy is used","Individualized oxygen and ventilation goals"],"The transport plan needs to match the anticipated physiology. Make sure the team understands the goals and can provide the required infusion, airway support and supplies without interruption."),reassessment:e("Anatomy refines stabilization goals",["Expert echocardiography establishes the lesion","Verify infusion and airway plans","Confirm supplies for the journey"],"Once the anatomy is known, the handoff should explain what changed in the support goals and why. That protects the plan when a new team sees an unfamiliar saturation target."),synopsis:e("Cyanotic newborn: connect oxygenation and circulation",["Limited oxygen response broadens the question","Hand\u2013foot comparison is only part of the assessment","Definitive anatomy guides the next phase"],"The key move was asking why oxygen was not producing the expected response. That question leads from a monitor value to a circulation-focused assessment.")},"rds-grunting-newborn":{presentation:e("A preterm infant keeps working to breathe",["30 weeks gestation \xB7 1.4 kg","Persistent grunting after birth","Increasing oxygen need","Spontaneous breathing continues"],"The infant is making respiratory effort, which gives us options, but that effort has to be assessed for effectiveness and sustainability. The transport preparation should not distract from the evolving bedside picture."),assessment:e("Breathing and heat loss are linked priorities",["Retractions and reduced air entry","Equal chest movement","Active temperature protection"],"For a very small infant, the environment is part of the resuscitation. We have to support respiratory function while preventing avoidable thermal and metabolic stress."),vitals:e("Interpret saturation in postnatal context",[],"The observation is at twenty-five minutes of age on respiratory support. Preserve that context in the handoff; a newborn saturation without its age and support setting is incomplete information.",{label:"Context",text:"25 minutes after birth; temperature 36.1\xB0C"}),labs:e("Assess ventilation and metabolic needs",[],"The gas helps us judge ventilation on the current support. Keep glucose and temperature alongside it, because successful neonatal stabilization has to address more than the lungs.",{label:"Reassess together",text:"Effort \xB7 oxygen need \xB7 gas exchange \xB7 warmth \xB7 glucose"}),diagnostics:e("A surfactant-deficiency pattern",["Low volumes and granular opacities reported","Air bronchograms","Continue evaluation for other causes"],"The synthetic report fits the gestation and presentation. The image pattern is supportive evidence in context, while infection and other causes remain part of the assessment."),decision:e("When would noninvasive support be insufficient?",["Increasing oxygen need","Apnea or exhaustion","Inadequate ventilation","Poor response despite effective delivery"],"Think about the observations that would change the airway plan. Check that the interface and pressure are delivering what the team intends before judging the response."),reasoning:e("Support now and prepare the next step",["Thermal and respiratory support","Neonatal guidance on surfactant and escalation","Check interface, pressure and transport supplies"],"A transfer checklist is most useful when it verifies effective care, rather than only the presence of equipment. The infant\u2019s response tells us whether the support is doing its job."),reassessment:e("Effort improves and temperature rises",["Temperature: 36.1 \u2192 36.7\xB0C","Continue to follow oxygen need","Repeat gas assessment as indicated"],"The early improvement gives us direction, but the infant still needs repeated assessment. A small patient can change quickly as support, position and environment change during transport."),synopsis:e("Preterm RDS: respiratory care includes the environment",["Judge the effectiveness of spontaneous breathing","Support thermal and metabolic needs","Escalate according to response"],"The lesson is a coordinated neonatal plan. Ventilation, oxygenation, warmth and glucose are connected parts of keeping this infant stable.")},"rds-sudden-desaturation":{presentation:e("The deterioration begins during movement",["29 weeks \xB7 1.2 kg","Intubated for RDS","Previously stable settings","Desaturation and alarm during incubator transfer"],"The timing is the first clue. A sudden event during movement asks a different question from a gradual increase in oxygen requirement over several hours."),assessment:e("Is ventilation reaching the infant?",["Reduced chest movement","Capnography waveform disappears","Heart rate falls","Check infant, tube and circuit together"],"Start at the patient and work through the support system. A ventilator can display familiar settings while little useful ventilation is reaching the lungs."),vitals:e("Bradycardia with loss of effective ventilation",[],"The oxygen saturation and heart rate are falling together. The absent carbon dioxide waveform is important, with the limitations of small tidal volumes and poor circulation kept in mind.",{label:"Immediate task",text:"Establish effective ventilation while checking the cause"}),labs:e("A new sample is not the next useful action",[],"We already know enough to act on the ventilation problem. The earlier glucose does not explain away a change that began during movement, and sampling must not interrupt resuscitation.",{label:"Sequence matters",text:"Ventilation first; repeat blood gas when appropriate"}),diagnostics:e("A structured patient-to-device assessment",["Tube displacement or obstruction","Circuit or oxygen delivery failure","Pneumothorax when indicated","Consider circulation and waveform limitations"],"These possibilities are checked in a coordinated rescue sequence. The purpose is to restore useful ventilation promptly, not to complete a long differential before taking action."),decision:e("Would higher settings fix a disconnected pathway?",["Confirm chest movement","Check tube and circuit","Verify oxygen delivery","Reassess after every change"],"Picture the same ventilator settings connected to a tube that has moved. Before changing the numbers, establish whether those breaths can reach the infant."),reasoning:e("Restore ventilation and confirm the response",["Neonatal rescue ventilation","Tube position, patency and connection checks","Expert airway escalation","Reconfirm after movement"],"The confirmation has to be physiological. Equipment checks matter, and the infant\u2019s chest movement, heart rate and carbon dioxide trace tell us whether the repair is effective."),reassessment:e("A displaced tube is identified",["Effective ventilation restored","Heart rate rises","Consistent CO\u2082 waveform returns","Recheck position and securement before departure"],"The response helps connect the identified problem with the deterioration. Before transport resumes, the team needs a new confirmation of ventilation and securement after the rescue."),synopsis:e("Sudden deterioration: revisit the pathway to the patient",["Timing after movement is a clue","Assess infant and equipment together","Verify useful ventilation after every transfer"],"The underlying RDS did not explain every new event. The abrupt change called for a fresh patient-to-device assessment.")}};var K={"preeclampsia-visual-symptoms":{presentation:e("Headache and flashing lights",["28 years \xB7 33 weeks + 2 days","Persistent headache and visual symptoms","Right upper quadrant discomfort","No prior chronic hypertension"],"The symptom story already asks us to consider more than an isolated blood pressure problem. Keep the headache, vision change and abdominal discomfort connected as the observations arrive."),assessment:e("Repeat the pressure; keep examining",["Alert with brisk reflexes","Clear lungs","Appropriate cuff used","Severe readings persist"],"Confirming a reading matters, but confirmation should lead to action. The repeat severe pressure and the neurological symptoms belong together in the escalation call."),vitals:e("Two patients, one immediate stabilization plan",[],"The fetal rate is one observation at one moment. It cannot clear the mother\u2019s severe hypertension or symptoms. Stabilizing maternal physiology is central to the care of both patients.",{label:"Maternal urgency",text:"Persistent 174/114 mmHg with neurological symptoms"}),labs:e("Look for organ involvement",[],"The laboratories add to a syndrome we already suspected from the bedside. Avoid waiting for one particular urine result before recognizing the severe clinical features already present.",{label:"Connect symptoms and results",text:"Platelets \xB7 liver injury \xB7 renal function"}),diagnostics:e("Preeclampsia with severe features",["Persistent severe hypertension","Neurological symptoms","Organ assessment informs the plan","Proteinuria is not the only route to recognition"],"Naming the syndrome helps organize parallel tasks. One treatment addresses seizure risk, another addresses dangerous pressure, and obstetric assessment determines the next definitive steps."),decision:e("What problem does each medication treat?",["Seizure prophylaxis","Severe blood pressure","Ongoing maternal and fetal assessment"],"Imagine someone reports that magnesium is running and asks whether the blood pressure problem is now covered. Separate the purpose of the therapies before continuing."),reasoning:e("Control pressure and prevent seizures",["Urgent obstetric escalation","Protocol-directed antihypertensive treatment","Indicated magnesium with monitoring","Specialist delivery planning"],"A good handoff names the goal of each intervention. It also carries the exact administration times and the monitoring findings, so a new team can continue treatment without guessing what has already happened."),reassessment:e("Improved pressure is a response, not discharge criteria",["Pressure improves","Headache lessens","Specialist obstetric management continues","Trend symptoms and laboratories"],"The early improvement is useful, but it does not erase the underlying pregnancy emergency. We still need a coordinated destination, monitoring plan and specialist decision about delivery."),synopsis:e("Severe preeclampsia: match therapy to its purpose",["Recognize symptoms with persistent severe pressure","Treat hypertension and seizure risk","Continue maternal and fetal reassessment"],"Remember the distinction between two urgent tasks that happen at the same time. The disease lesson can now build the physiology around a clinical decision you have already worked through.")},"eclampsia-postpartum":{presentation:e("The pregnancy history is still active",["32 years \xB7 postpartum day 5","Headache and visual disturbance","Generalized seizure","Apparently uncomplicated delivery"],"Start with the detail that can be missed in a generic seizure handoff: delivery was five days ago. The pregnancy history is part of the present emergency even though the patient is home."),assessment:e("Stabilize and keep the differential open",["Confused after seizure","Spontaneous breathing","No obvious trauma","Evaluate other neurological causes"],"A plausible obstetric explanation should accelerate the right treatment without stopping our assessment. Follow recovery and look for features that would push us toward another intracranial emergency."),vitals:e("A seizure with severe postpartum hypertension",[],"The pressure supports an urgent obstetric concern in this setting. At the same time, the respiratory assessment after the seizure remains an immediate bedside task.",{label:"Context changes interpretation",text:"Postpartum day 5 + seizure + 182/116 mmHg"}),labs:e("Normal-looking results do not close the case",[],"A glucose check addresses one immediate alternative. A platelet count that is not markedly low does not remove eclampsia from the differential. The symptom sequence still carries major weight.",{label:"Use the whole pattern",text:"Headache \u2192 visual symptoms \u2192 seizure"}),diagnostics:e("Postpartum eclampsia remains possible",["Treat the clinical emergency","Assess neurological recovery","Investigate atypical or persistent findings"],"The diagnosis is approached through timing and clinical features, while other causes are evaluated. Persistent altered consciousness or focal findings should change how urgently we pursue additional neurological assessment."),decision:e("Does delivery remove eclampsia from consideration?",["Recent delivery matters","No prior diagnosis is required to raise concern","Alternative seizure causes still need assessment"],"Think about what you would say in the first sentence to the receiving team. The postpartum day should appear early enough to change their preparation."),reasoning:e("Support breathing, treat seizure risk and pressure",["Airway, ventilation and injury prevention","Protocol-directed magnesium","Treat persistent severe hypertension","Immediate obstetric consultation"],"Parallel care is the key. We can protect breathing, treat the suspected obstetric syndrome and plan further diagnostics without forcing those tasks into an unnecessarily slow sequence."),reassessment:e("Seizure cessation is the start of reassessment",["Continue respiratory monitoring","Follow neurological recovery","Handoff includes postpartum day and treatment times"],"When the visible seizure ends, the examination becomes especially valuable. Document how alertness changes and whether the patient returns toward baseline, rather than reporting only that the seizure stopped."),synopsis:e("Postpartum seizure: the timeline changes the differential",["Pregnancy risk continues after delivery","Act on suspected eclampsia","Continue evaluation of neurological alternatives"],"The detail that unlocked the case was a recent delivery. Make it part of the emergency history every time you assess a patient whose pregnancy has recently ended.")},"hellp-epigastric-pain":{presentation:e("An indigestion story at 35 weeks",["30 years \xB7 35 weeks + 1 day","Worsening upper abdominal pain","Nausea and malaise","No external bleeding"],"The patient\u2019s explanation is understandable: upper abdominal discomfort often sounds gastrointestinal. Our task is to test that explanation against the pregnancy context and the rest of the examination."),assessment:e("The abdominal complaint needs a systemic assessment",["Right upper quadrant tenderness","Malaise","Currently alert","Consider a pregnancy complication"],"The pain is the opening complaint, but it may be a sign of organ involvement. Ask what else would have to be true for reflux to explain the whole presentation."),vitals:e("Pressure adds concern to the pain story",[],"The systolic pressure is in a severe range at this assessment. It adds urgency to the symptom pattern and needs prompt repeat assessment and management under the obstetric pathway.",{label:"Connect the bedside findings",text:"Upper abdominal pain with significant hypertension"}),labs:e("Three abnormalities form a pattern",[],"The low platelets, liver enzyme elevation and evidence of hemolysis turn an apparently isolated complaint into a multisystem problem. Interpret the pattern together rather than treating each result as a separate issue.",{label:"HELLP pattern",text:"Hemolysis \xB7 elevated liver enzymes \xB7 low platelets"}),diagnostics:e("HELLP changes the urgency",["Clinical context supports HELLP","Escalating pain raises hepatic concerns","Immediate specialist assessment"],"Naming HELLP explains why the pain cannot simply be observed as indigestion. The intensity and course of pain remain important because complications may change the next definitive action."),decision:e("Which finding changes your working explanation?",["Platelets 62 \xD710\u2079/L","AST 280 U/L","LDH 920 U/L and schistocytes"],"Return to the first impression of reflux. Which combination now makes that explanation insufficient, and what would you communicate before the patient leaves the referring unit?"),reasoning:e("Escalate for systemic obstetric disease",["Obstetric and critical care coordination","Trend pain, bleeding and neurological findings","Treat associated severe hypertension","Indicated seizure prophylaxis"],"The clinical plan needs to anticipate more than the presenting symptom. Laboratory trajectory, bleeding risk and the potential for rapid change all influence the destination and the resources required."),reassessment:e("The trend belongs in the handoff",["Urgent obstetric management arranged","Serial symptoms and laboratories","Prepare hemorrhage support when needed"],"A single panel establishes the concern; serial values help describe its pace. The receiving team needs both the most recent results and how quickly the symptoms and abnormalities have developed."),synopsis:e("HELLP: let the laboratory pattern reframe the complaint",["Abdominal pain can reflect systemic disease","Connect hemolysis, liver injury and platelets","Escalate with the clinical trajectory"],"The useful move was revisiting the original explanation when the evidence stopped fitting. Carry that habit into other apparently ordinary complaints in pregnancy.")},"hellp-without-severe-bp":{presentation:e("Pain persists after delivery",["26 years \xB7 18 hours postpartum","Upper abdominal pain and nausea","Profound malaise","Pressure has not reached severe range"],"The delivery is complete and the pressure does not look dramatic. Those two facts can make continued pain sound less urgent than it is. Let the examination and laboratory pattern have their own voice."),assessment:e("The examination adds a bleeding clue",["Pallor and right upper quadrant tenderness","Petechiae near venipuncture sites","Breathing and mental status currently normal"],"The petechiae are a small visible finding that connects to a much larger laboratory problem. Do not let the patient\u2019s current ability to talk comfortably substitute for a systemic assessment."),vitals:e("Nonsevere pressure cannot clear organ injury",[],"The pressure is information, but it is not an exclusion test for HELLP. We need to see whether the symptoms and other evidence point to significant disease despite that reading.",{label:"Potential distraction",text:"142/90 mmHg does not explain away the laboratory pattern"}),labs:e("The laboratory pattern carries the urgency",[],"These results are markedly abnormal in a way that fits the ongoing symptoms. The hemolysis evidence, liver injury and platelet count deserve urgent interpretation even without a severe pressure reading.",{label:"Look at the combination",text:"Platelets 48 \xB7 AST 340 \xB7 LDH 1080 \xB7 low haptoglobin"}),diagnostics:e("Postpartum HELLP and its mimics",["HELLP remains possible","Consider other microangiopathies and liver disorders","Specialist evaluation is urgent"],"There is still diagnostic work to do. The appropriate response to that uncertainty is expert evaluation and close monitoring, rather than waiting for the blood pressure to become more convincing."),decision:e("Would you wait for severe hypertension?",["Major platelet abnormality","Evidence of hemolysis and liver injury","Persistent postpartum symptoms"],"Choose the evidence that should determine escalation now. If you removed the blood pressure from the handoff, the remaining findings would still demand an urgent explanation."),reasoning:e("Escalate on the evidence already present",["Urgent obstetric and critical care review","Assess bleeding and organ complications","Trend laboratory abnormalities","Monitored transfer"],"The clinical risk comes from the syndrome and its trajectory. The handoff should make clear why a relatively modest pressure reading has not reduced the required level of care."),reassessment:e("Follow what happens after the first panel",["Repeat platelet count","Track pain and clinical course","Handoff postpartum timing and laboratory trend"],"Delivery does not promise an immediate end to the illness. Reassessment must be able to detect persistence or progression instead of treating postpartum status as a conclusion."),synopsis:e("HELLP: severe disease can outpace the pressure",["Use symptoms and organ findings together","Postpartum timing remains relevant","Evaluate HELLP and competing diagnoses urgently"],"The opening reassurance came from a number. The correction came from reconnecting that number with the patient\u2019s symptoms and the evidence of systemic injury.")},"pph-boggy-uterus":{presentation:e("The measured loss is still rising",["29 years \xB7 20 minutes postpartum","Vaginal birth at term","About 1,200 mL measured loss","Faintness and nausea"],"The measured volume and the patient\u2019s symptoms tell us this is active resuscitation. Waiting for the next laboratory result would leave the source continuing to remove circulating volume."),assessment:e("Atony is a source clue",["Boggy, enlarged uterus","Brisk ongoing bleeding","Pale with cool extremities","Assess tone, trauma, tissue and coagulation"],"The boggy uterus gives us an immediate treatment direction. It should focus the first actions while we continue to check whether another cause is contributing."),vitals:e("Hemorrhage with impaired perfusion",[],"Tachycardia and hypotension fit the observed loss. The oxygen saturation is not a measure of how much blood remains in circulation or whether tissue delivery is adequate.",{label:"Act on physiology",text:"Ongoing loss + faintness + 88/52 mmHg"}),labs:e("The early hemoglobin can lag behind the event",[],"An early hemoglobin may sound less alarming than the bedside picture. Here the measured bleeding, perfusion findings and coagulation results carry more weight than an isolated initial concentration.",{label:"Do not wait for a late signal",text:"Early hemoglobin 10.4 g/dL does not exclude major acute loss"}),diagnostics:e("Control hemorrhage while assessing the cause",["Atony supported by examination","Continue evaluation for additional causes","Do not delay resuscitation for imaging"],"This diagnosis is being made through direct examination during treatment. The source assessment and the resuscitation are parallel tasks, and both need a clear team lead."),decision:e("Is the hemoglobin a reason to wait?",["Measured bleeding continues","The patient is hypotensive","The uterus is boggy"],"Decide what evidence is enough to activate the hemorrhage response. Think about what can change in the time it would take to wait for another sample."),reasoning:e("Treat the source and restore circulation",["Activate obstetric hemorrhage care","Uterine measures and indicated medications","Blood products, warming and monitoring","Escalate source control if bleeding persists"],"The treatments work toward complementary goals. Source control limits continued loss; resuscitation supports the patient while control is achieved. Neither task should wait for the other to be completely finished."),reassessment:e("Slowing bleeding still needs measurement",["Quantify further loss","Reassess perfusion","Document medications and blood products","Follow coagulation results"],"A visual impression that bleeding is slowing is welcome, but the trend still needs to be measured. The timeline helps the next team judge both the remaining deficit and the response."),synopsis:e("Atonic hemorrhage: act on loss and physiology",["Recognize shock early","Treat atony while checking other causes","Use ongoing loss and response to guide escalation"],"The critical decision was made before a dramatic hemoglobin fall. Remember the combination of ongoing bleeding, a boggy uterus and impaired perfusion.")},"pph-firm-uterus":{presentation:e("The uterus firms, but bleeding continues",["34 years \xB7 45 minutes postpartum","Instrument-assisted birth","More than 1,500 mL estimated loss","Uterine measures already performed"],"The team has treated a plausible cause, and one examination finding has improved. The unresolved question is why the patient is still bleeding."),assessment:e("The source needs another look",["Uterus now firm","Concern for genital tract laceration","Placental completeness uncertain","Pallor and anxiety"],"The firm uterus is useful new information. It should shift attention toward other sources instead of being interpreted as proof that the overall hemorrhage is controlled."),vitals:e("The circulation is still under threat",[],"The pressure and heart rate show why the reassessment must be urgent. The low temperature adds another problem to manage during ongoing hemorrhage resuscitation.",{label:"Unresolved emergency",text:"Firm uterus with persistent bleeding and shock"}),labs:e("Bleeding and coagulation must be followed together",[],"The laboratory results describe part of the evolving consequence of blood loss. They reinforce the need for coordinated resuscitation while the team finds and controls the source.",{label:"Trend the response",text:"Hemoglobin \xB7 fibrinogen \xB7 platelets \xB7 temperature"}),diagnostics:e("Tone is only one part of the source assessment",["Evaluate trauma","Reassess retained tissue","Assess coagulation","Multiple causes may coexist"],"A treatment response can teach us what remains unexplained. Here improved tone does not account for the continued loss, so the next assessment has to broaden."),decision:e("Would you repeat the same intervention?",["What has already changed?","What remains uncontrolled?","What source needs definitive assessment?"],"Imagine handing this patient to a new team with only the label postpartum hemorrhage. Which specific findings would stop them from repeating a plan that has already failed to control the loss?"),reasoning:e("Continue resuscitation; change the source strategy",["Immediate obstetric source-control assessment","Communicate instrumentation and placental uncertainty","Blood products, warming and serial coagulation checks"],"The resuscitation continues while the source plan changes. Make the reason for the change explicit so the team stays coordinated through repair or other definitive management."),reassessment:e("Handoff the sequence, not one total",["Definitive assessment and repair","Ongoing resuscitation","Intervention times and continued bleeding documented"],"A single estimate hides whether the patient lost blood before or after an intervention. The timeline explains what worked, what did not and how much uncertainty remains."),synopsis:e("Persistent PPH: improved tone is incomplete control",["Reassess when bleeding continues","Look for trauma, tissue and coagulation problems","Maintain resuscitation during definitive source control"],"The turning point was a firm uterus in a patient who was still hemorrhaging. Follow the unresolved physiological problem even after one treatment target has improved.")},"abruption-concealed":{presentation:e("Little visible blood, severe pain",["31 years \xB7 34 weeks + 4 days","Sudden abdominal pain","Reduced fetal movement","Small amount of dark vaginal blood"],"The visible blood invites an estimate of severity, but it may be an incomplete view of the loss. Start by asking whether the rest of the patient fits that small amount."),assessment:e("The examination suggests a larger problem",["Tender, persistently firm uterus","Pallor and diaphoresis","Weak peripheral pulses"],"The uterine findings and perfusion signs make the apparent size of the external bleed difficult to trust. This is a situation where what we cannot see may matter more than what we can."),vitals:e("Maternal shock with fetal concern",[],"The maternal circulation and the persistently low fetal rate both add urgency. Neither should be interpreted as an isolated monitor problem; they belong to the same evolving clinical emergency.",{label:"Combined concern",text:"Maternal 92/58 mmHg with fetal rate near 95/min"}),labs:e("The panel does not measure all concealed loss",[],"The hemoglobin concentration cannot quantify the acute bleeding behind the placenta. The coagulation findings are another reason to organize hemorrhage support while definitive care is arranged.",{label:"Clinical context first",text:"Pain + uterine firmness + perfusion change"}),diagnostics:e("Suspected abruption is a clinical emergency",["Bleeding may be concealed","Ultrasound cannot reliably exclude abruption","Urgent obstetric assessment"],"A scan that fails to show the cause does not make this examination disappear. The team has to act on the clinical pattern and the risk of delay."),decision:e("Can the visible loss explain the whole picture?",["Shock is present","Uterine pain and firmness persist","Fetal findings are concerning"],"Consider which evidence you would prioritize if the external blood loss and the physiological signs disagree. The care plan must account for the larger risk."),reasoning:e("Resuscitate and coordinate definitive obstetric care",["Urgent obstetric and hemorrhage escalation","Maternal support and indicated blood products","Continued maternal and fetal assessment"],"The destination and timing are part of the treatment. Support during transfer must be coordinated with a team able to provide the definitive obstetric intervention the patient may require."),reassessment:e("Keep concealed loss in the handoff",["Immediate obstetric intervention prepared","Support maternal circulation","Track coagulation and perfusion"],"State the discrepancy explicitly: little blood was visible, but the examination and physiology suggested significant concealed hemorrhage. That sentence preserves the reasoning across the handoff."),synopsis:e("Abruption: visible bleeding can underestimate risk",["Use uterine findings and perfusion together","Include fetal trajectory","Do not delay urgent action for a reassuring scan"],"The memorable feature is the mismatch between what was visible and how sick the patient was. Clinical reasoning made that mismatch an alarm.")},"abruption-trauma":{presentation:e("A modest crash, an important symptom pattern",["25 years \xB7 30 weeks + 5 days","Restrained collision","Abdominal pain and frequent contractions","No visible vaginal bleeding"],"The description low speed can shape the whole handoff before anyone examines the patient. Start with the mechanism, then allow the symptoms to change your assessment of risk."),assessment:e("Maternal trauma and pregnancy need parallel attention",["Uterine tenderness","Seat-belt mark","Currently alert","No obvious long-bone injury"],"The absence of a dramatic external injury does not settle the pregnancy assessment. Continue the maternal trauma examination while bringing the uterine findings into the same plan."),vitals:e("Maternal pressure and fetal findings differ",[],"The maternal pressure is maintained, while the fetal monitor reports recurrent decelerations with tachycardia. This difference is a reason to integrate the assessments rather than choose one as the whole story.",{label:"Do not lose the monitor context",text:"Fetal rate 170/min with recurrent decelerations"}),labs:e("A baseline panel needs a clinical trend",[],"These initial values provide a starting point. They do not overrule the pain, contractions and fetal findings. Repeated assessment is how we learn whether the situation is evolving.",{label:"Baseline, not closure",text:"Interpret fibrinogen with symptoms and its trend"}),diagnostics:e("Abruption remains a concern after trauma",["No bleeding does not exclude placental injury","Assess maternal occult injury","Ongoing obstetric evaluation and monitoring"],"The working concern follows the clinical pattern, even when the crash sounds minor. The trauma and obstetric assessments are connected parts of one resuscitation."),decision:e("Which facts should determine destination?",["Mechanism alone?","Pain and contractions?","Fetal monitoring abnormalities?","Potential maternal occult injury?"],"Imagine choosing a receiving center from the first radio report. Which additional findings would change the capabilities you need at that destination?"),reasoning:e("Choose care that can address both emergencies",["Maternal trauma priorities","Urgent obstetric consultation","Continued fetal monitoring as appropriate","Prepare for deterioration"],"The plan should remain useful if the patient worsens en route. That means sharing the current symptoms and monitoring changes, with a destination able to respond to both maternal injury and obstetric complications."),reassessment:e("Communicate symptoms and trajectory",["Trauma and obstetric capability arranged","Crash details and examination","Monitoring findings","Absence of external bleeding kept in context"],"A good handoff does not reduce this to a minor collision. It preserves the evidence that changed the risk assessment after the mechanism was known."),synopsis:e("Trauma-associated abruption: symptoms can outvote mechanism",["Examine beyond the crash label","Connect uterine and fetal findings","Plan for maternal and obstetric deterioration"],"The early description gave us a starting point. The symptoms and monitoring data determined the next level of care.")},"ppcm-cannot-lie-flat":{presentation:e("Sleeping upright after delivery",["33 years \xB7 3 weeks postpartum","Progressive dyspnea and leg swelling","Now unable to lie flat","No known cardiac disease"],"Fatigue and poor sleep are easy explanations after a new baby. Ask what the patient has had to change to breathe comfortably; sleeping upright gives that complaint a different meaning."),assessment:e("The examination suggests congestion",["Bilateral crackles","Elevated neck veins","Peripheral edema","Tachypneic but alert"],"The findings come from more than one part of the circulation. Together they make isolated dependent swelling an inadequate explanation for the patient\u2019s difficulty breathing."),vitals:e("Maintained pressure with respiratory compromise",[],"The pressure is currently preserved. The tachypnea and hypoxemia still demand support and an explanation. Heart failure does not have to arrive with hypotension to be important.",{label:"Functional clue",text:"Orthopnea with hypoxemia and pulmonary findings"}),labs:e("BNP adds support, not a complete diagnosis",[],"The biomarker is consistent with the congestive picture, but it does not identify the cause by itself. We need imaging and evaluation of other postpartum causes of breathlessness.",{label:"Keep the diagnostic sequence clear",text:"Clinical findings \u2192 cardiac assessment \u2192 cause evaluation"}),diagnostics:e("Global systolic dysfunction enters the story",["Ejection fraction reported at 28%","Pulmonary congestion","Evaluate other causes of postpartum dyspnea"],"The echocardiographic finding gives us a functional explanation for the congestion. The postpartum timing raises peripartum cardiomyopathy, while the team continues the work needed to establish the cause."),decision:e("What makes this more than postpartum fatigue?",["Orthopnea","Hypoxemia and crackles","Systolic dysfunction","Progressive functional limitation"],"Return to the first explanation the patient was given. Which findings now require a different level of assessment and care?"),reasoning:e("Support breathing and coordinate cardiac care",["Appropriate respiratory support","Treat congestion under specialist guidance","Cardiology and obstetric coordination","Evaluate competing postpartum emergencies"],"Care has to fit the postpartum context as well as the cardiac physiology. The handoff should include timing after delivery, current respiratory support and the evidence for ventricular dysfunction."),reassessment:e("Follow the response beyond the oxygen number",["Breathing improves with treatment","Continue clinical and cardiac assessment","Handoff postpartum timing and support"],"Improved breathing is the beginning of a response assessment. We still need a sustained trajectory and a shared specialist plan for the ventricular dysfunction and its cause."),synopsis:e("Peripartum heart failure: listen to the functional history",["Orthopnea deserves investigation","Connect congestion with ventricular dysfunction","Coordinate postpartum and cardiac assessment"],"The story changed when fatigue became an inability to lie flat. Functional detail can expose disease hidden behind a familiar life circumstance.")},"ppcm-shock":{presentation:e("Postpartum dyspnea with a failing circulation",["36 years \xB7 postpartum day 10","Dyspnea, confusion and scant urine","Small fluid intervention without improvement","No diagnosis assumed from timing alone"],"This companion presentation begins where a congestive illness becomes a circulatory emergency. The next decisions have to account for the lungs and the circulation at the same time."),assessment:e("Congestion and low output can coexist",["Cool, clammy skin and weak pulses","Crackles and elevated neck veins","Simultaneous congestion and poor perfusion"],"Crackles may dominate the first impression, but the perfusion examination changes the urgency and the support plan. Avoid allowing one organ system to occupy the whole assessment."),vitals:e("Support decisions have hemodynamic consequences",[],"Read the oxygenation and pressure together. An intervention intended to help breathing must be assessed for what it does to an already vulnerable circulation.",{label:"Combined assessment",text:"Gas exchange and forward flow"}),labs:e("Organ stress belongs in the shock story",[],"Use the laboratory results to track the consequences of poor perfusion alongside the examination. They contribute to the evolving picture rather than choosing the definitive cardiac diagnosis on their own.",{label:"Reassess serially",text:"Perfusion findings with laboratory trajectory"}),diagnostics:e("Define function and evaluate the cause",["Severe ventricular dysfunction","Urgent specialist cardiac assessment","Evaluate alternative peripartum emergencies"],"Echocardiography helps define the functional problem. The team still needs to evaluate why it is present and whether a competing diagnosis changes the immediate treatment."),decision:e("Would another fluid intervention help?",["Congestion is already present","The earlier fluid did not improve the picture","Reassess the form of circulatory support"],"Think through the next intervention as well as the next number you want to improve. What evidence would make more fluid helpful, and what evidence would make it poorly tolerated?"),reasoning:e("Coordinate a cardiac shock plan",["Urgent cardiology, obstetric and critical care input","Support oxygenation and circulation together","Advanced support planning when indicated"],"The transfer decision is part of the resuscitation. A patient with this combination may need capabilities beyond routine respiratory support, so the receiving team should help shape the plan early."),reassessment:e("Trend both sides of the response",["Reassess pressure and perfusion","Reassess oxygenation and lung findings","Communicate support and response"],"Describe the effect of each intervention on both breathing and circulation. That makes opposing responses visible and helps the next team continue an individualized plan."),synopsis:e("Peripartum shock: follow lungs and circulation together",["Congestion does not exclude poor forward flow","Evaluate the cause urgently","Plan support around treatment tolerance"],"The case is about keeping two physiological problems in view at once. The next step is useful only if its overall effect helps the patient.")}};var $={"asthma-speaking-in-words":{presentation:e("One word per breath",["8 years \xB7 26 kg","Previous ICU admission","Viral illness \u2192 worsening breathlessness","Little relief from home albuterol"],"Before looking at a gas, listen to how much of a sentence this child can manage. One word per breath tells us that ordinary conversation is competing with the work of breathing."),assessment:e("Alert does not mean comfortable",["Sitting forward; frightened but alert","Recession and prolonged expiration","Reduced basal air entry"],"Imagine kneeling beside the bed rather than talking over the child. You can follow air entry, effort and interaction together. The loudness of the wheeze is only one part of that picture."),vitals:e("A strained respiratory system",[],"Read these observations as a group: rapid breathing, tachycardia and hypoxemia in a child who is still working hard. Preserved pressure does not reduce the urgency of the breathing problem.",{label:"Connect the findings",text:"Speech + effort + air entry"}),labs:e("Does the gas fit the child?",[],"The temptation is to find one value that sounds reassuring and relax. Here the bedside trajectory has to carry more weight than a carbon dioxide value that seems unremarkable in isolation.",{label:"Interpret in context",text:"A single gas does not establish respiratory reserve"}),diagnostics:e("A clinical diagnosis first",["Typical asthma pattern","Routine radiograph not required","New focal findings would change the question"],"A test should answer a question. If the story becomes asymmetric or a complication is suspected, the imaging question changes. A routine film should not become a detour from effective treatment."),decision:e("What would convince you treatment is working?",["Air entry?","Speech and alertness?","Effort over the next treatment cycle?"],"Keep those three observations in mind. We are about to reassess the child; decide what combination would make you more confident that the treatment is reaching its target."),reasoning:e("Treat, then return to the bedside",["Oxygen and effective bronchodilator delivery","Repeat assessment after treatment","Prepare escalation early"],"Think of the first treatment as both therapy and a chance to learn. If the response is poor, check whether the medication is actually being delivered before concluding that the disease is unresponsive."),reassessment:e("A coherent improvement",["Speech: words \u2192 short sentences","Respiratory rate: 38 \u2192 30/min","SpO\u2082: 95% on oxygen","Continue to trend air entry and effort"],"The important feature is that several bedside findings move in the same direction. Better saturation alone would be less persuasive if the child were becoming less interactive or moving less air."),synopsis:e("Severe asthma: follow the whole child",["Recognize limited respiratory reserve","Judge response through speech, effort and air movement","Escalation planning starts before exhaustion"],"Carry this into the disease lesson: severity and response are patterns over time. A noisy chest can be very sick, and a quieter chest needs a fresh examination rather than an automatic label of improvement.")},"asthma-silent-chest":{presentation:e("The room becomes quieter",["12 years \xB7 42 kg","Severe asthma under treatment","Stops holding the nebulizer","Quiet breathing described as improvement"],"Picture the moment a busy team starts to pack for transfer. The child is making less noise, and that change is easy to welcome. Our job is to ask what changed along with the noise."),assessment:e("Less sound, less airflow",["Nearly silent chest","Shallow effort","Slow response to voice","Unable to complete a sentence"],"This is the turning point. The quieter chest arrives with less movement and less interaction. Those accompanying findings reverse the meaning of the apparent improvement."),vitals:e("A falling rate can signal fatigue",[],"Compare the respiratory rate with its earlier value. The fall occurs while oxygenation and consciousness are worsening. The direction of a number only becomes useful when we know what the patient is doing.",{label:"Earlier \u2192 now",text:"Respiratory rate 42 \u2192 18/min; breaths are shallow"}),labs:e("Ventilation is failing",[],"The blood gas now agrees with the bedside concern. Carbon dioxide retention and acidemia give us additional evidence, but we already had enough clinical change to escalate while those results were coming.",{label:"Clinical turning point",text:"Reduced effort + altered alertness + CO\u2082 retention"}),diagnostics:e("Stabilization comes before the film",["Failing ventilation","Assess immediate complications at the bedside","Imaging after initial support when indicated"],"A radiograph may help with a complication later. It cannot provide the ventilation the child needs now. This is where the order of actions matters as much as the diagnostic list."),decision:e("What will positive pressure change?",["Air trapping","Expiratory time","Venous return and blood pressure"],"Think beyond placing a tube. In a severely obstructed chest, the way we ventilate can change the circulation. Anticipate that problem before the first assisted breath."),reasoning:e("Escalate with an obstruction plan",["Expert airway and ventilation support","Allow adequate expiration","Follow pressure, flow and perfusion"],"The airway plan and ventilation plan belong together. A successful procedure does not finish the resuscitation; the next breaths and the next blood pressure reading are part of the same decision."),reassessment:e("Recheck the physiology after intervention",["Follow expiratory flow and pressures","Repeat gas exchange assessment","Track perfusion","Investigate sudden deterioration"],"Avoid the cognitive finish line of a secured airway. We still need evidence that ventilation is effective and tolerated, especially if the blood pressure changes or expiration remains incomplete."),synopsis:e("The silent chest: a trajectory toward failure",["Loss of wheeze can accompany loss of airflow","Reduced effort may represent exhaustion","Ventilation must account for air trapping"],"The memorable moment is the quiet room. Link that moment to the child who stopped participating, and the clinical warning becomes easier to recognize when the monitor alone looks ambiguous.")},"dka-first-diagnosis":{presentation:e("The vomiting has a longer story",["10 years \xB7 30 kg","Thirst, polyuria and weight loss","Then vomiting and abdominal pain","No previous diabetes diagnosis"],"If the handoff begins with vomiting, ask what happened before the vomiting. The two-week history changes the meaning of the final few hours and points us toward a metabolic process."),assessment:e("Deep breathing is part of the compensation",["Alert but tired","Dry mucosa; refill 3 seconds","Deep, regular breaths","Baseline neurological examination documented"],"The breathing can draw our attention toward a primary lung problem. Listen to its regular depth and connect it with the history. We also need a neurological baseline before the treatment course evolves."),vitals:e("Oxygenation and ventilation answer different questions",[],"Normal saturation tells us about oxygenation at this moment. It does not explain away the deep breathing or the metabolic illness. The respiratory pattern is doing useful compensatory work.",{label:"Keep the story connected",text:"Deep breathing with preserved saturation"}),labs:e("Glucose, ketones and acidosis",[],"Now the history and the laboratory pattern meet. Keep the potassium value in view: its initial position in the reference range is not a measure of how much potassium remains in the body.",{label:"Anticipate the next change",text:"Serum potassium may fall during treatment"}),diagnostics:e("DKA: establish the pathway",["Hyperglycemia + ketonemia + acidosis","Compensatory breathing","Serial metabolic and neurological assessment"],"We have enough information to organize a pediatric DKA handoff. The next task is to reconstruct what fluids and medications have already been given, so the receiving team is continuing one coherent course."),decision:e("What must travel with this child?",["Measured weight","Fluid and insulin timeline","Electrolyte and glucose trends","Neurological baseline"],"Imagine a handoff that only says the glucose is improving. What would the next team still need to safely continue treatment? Think about the timeline as well as the latest laboratory panel."),reasoning:e("Plan a monitored metabolic correction",["Pediatric DKA fluid and insulin pathway","No insulin bolus","Serial electrolytes, glucose and neurological checks"],"The pathway links several moving parts. A change in glucose may alter dextrose needs while ketosis still requires treatment. That is why isolated numbers are a poor substitute for a shared plan."),reassessment:e("Glucose improves; treatment continues",["Glucose: 480 \u2192 330 mg/dL","Potassium: 4.8 \u2192 3.7 mmol/L","Still alert","Continue to assess ketosis and electrolytes"],"This is the result we were preparing to interpret. Potassium has moved even though the child looks better. Reassessment changes the next treatment adjustment rather than simply confirming the first diagnosis."),synopsis:e("New-onset DKA: the correction needs a timeline",["Connect the preceding symptoms","Preserve compensatory physiology","Follow potassium and neurological status","Glucose improvement alone is incomplete"],"Remember the child behind the glucose value: the history established the problem, the breathing reflected compensation, and the serial examination and laboratories guided what came next.")},"dka-new-headache":{presentation:e("A new symptom changes the case",["7 years \xB7 22 kg","Three hours into severe DKA treatment","Headache \u2192 vomiting \u2192 drowsiness","Glucose is falling"],"The metabolic numbers are moving in a direction the team expected. Then the child develops a new problem. This case asks us to notice when the original treatment story is no longer the only story."),assessment:e("The neurological baseline has changed",["Reduced interaction","Eyes open to voice","No sedative given","Pupils remain equal"],"Equal pupils can be a powerful distraction when we are hoping the child is simply tired. The comparison that matters is with this child\u2019s earlier interaction, especially without a medication explanation."),vitals:e("Read the change in heart rate",[],"A lower heart rate can look like recovery from dehydration. Here it arrives with headache and declining interaction. Pair the trend with those new symptoms before deciding what it means.",{label:"Earlier \u2192 now",text:"Heart rate 132 \u2192 82/min with neurological decline"}),labs:e("Metabolic improvement does not settle neurological risk",[],"These values help us assess immediate alternatives, including glucose abnormalities. They do not cancel a new neurological examination. We can investigate competing explanations while acting on a time-critical concern.",{label:"Avoid a false finish line",text:"Improving glucose is not a neurological clearance"}),diagnostics:e("A clinical emergency before confirmation",["Suspected DKA-associated cerebral injury","Check immediate alternative causes","Do not delay indicated treatment for a scan"],"The important decision is about timing. A later image may help clarify the course, but a request for proof should not become the reason a deteriorating child waits for treatment."),decision:e("Which trend changes the next minute?",["Falling glucose","New headache and altered interaction","Relative slowing of the heart rate"],"Put yourself at the transfer bedside. What would make you stop departure preparation and call for an immediate change in the resuscitation plan? Hold that answer as we move to management."),reasoning:e("Treat the new syndrome and reassess",["Urgent pediatric critical care escalation","Protocol-directed cerebral injury treatment","Airway, perfusion and glucose reassessment"],"Two tasks run together: act on suspected cerebral injury and check for another reversible cause of deterioration. If an airway intervention becomes unavoidable, the metabolic compensation needs explicit planning."),reassessment:e("Follow recovery, then clarify the cause",["Frequent documented neurological checks","Continue respiratory and perfusion monitoring","Further imaging after initial stabilization as indicated"],"A handoff should describe the exact sequence of headache, behavior change, intervention and response. That sequence helps the next team understand a patient whose examination may already have changed again."),synopsis:e("DKA: reassessment can reveal a second emergency",["New neurological symptoms outweigh reassuring trends","Equal pupils do not exclude cerebral injury","Initial treatment precedes confirmatory imaging"],"The teaching point lives in the change from baseline. A patient can improve in one physiological domain while becoming critically worse in another, and our plan must be able to change with that.")},"sepsis-normal-pressure":{presentation:e("A normal pressure in a sick child",["4 years \xB7 17 kg","Fever and poor intake","Reduced interaction","No urine for 8 hours"],"The clinic\u2019s blood pressure reading is accurate information, but it is an incomplete summary. Before accepting the word stable, ask how the child has been behaving and whether the kidneys are producing urine."),assessment:e("The periphery tells a different story",["Lethargic but rousable","Cool, mottled extremities","Weak peripheral pulses","Refill 5 seconds"],"These are direct clues about perfusion. Notice the mismatch between a maintained pressure and the examination. That mismatch should sharpen our assessment rather than reassure us."),vitals:e("Compensation can preserve pressure",[],"The child is using a fast heart rate and compensatory physiology to maintain the measured pressure. Waiting for that pressure to fall would mean waiting for a later stage of deterioration.",{label:"Assess perfusion together",text:"Interaction \xB7 pulses \xB7 refill \xB7 urine output"}),labs:e("Lactate supports the concern",[],"The lactate fits the clinical picture of impaired perfusion, but we did not need a laboratory permission slip to recognize a sick child. We still need repeated clinical assessment as treatment begins.",{label:"Use the result with the examination",text:"One lactate cannot establish or exclude shock"}),diagnostics:e("Suspected infection with impaired perfusion",["Recognize shock before hypotension","Evaluate source and alternatives","Coordinate cultures without avoidable treatment delay"],"A working diagnosis is enough to organize urgent care while we continue to investigate. The source may become clearer later; the perfusion problem is already in front of us."),decision:e("Would you wait for hypotension?",["The pressure is maintained","The child remains poorly perfused","Treatment response needs repeated assessment"],"Consider what threshold you would use to act if the monitor were covered. The history and examination should still lead you to a resuscitation plan."),reasoning:e("Intervene and reassess each step",["Timely sepsis treatment","Measured fluids with assessment of tolerance","Prepare indicated vasoactive support"],"Resuscitation is a series of decisions informed by response. After each intervention, ask whether perfusion improved and whether the lungs or heart are showing a cost from the treatment."),reassessment:e("A partial response is useful information",["Pulses and refill improve only partly","Recheck lungs and cardiac function","Prepare the next form of support"],"A partial response is neither a reason to abandon the diagnosis nor a reason to repeat the same action indefinitely. It tells us to re-examine the physiology before choosing the next intervention."),synopsis:e("Pediatric shock: pressure can lag behind perfusion",["Recognize the clinical perfusion pattern","Treat suspected infection promptly","Use response and tolerance to guide escalation"],"The normal pressure was the opening trap. Remember the child who stopped interacting and stopped making urine; those details gave the blood pressure its proper context.")},"sepsis-fluid-intolerance":{presentation:e("More oxygen after initial resuscitation",["9 years \xB7 29 kg","Fluids and antimicrobials already given","Poor perfusion persists","Oxygen requirement is rising"],"You arrive after the first phase of treatment. The question is no longer whether the child needs resuscitation; it is which form of resuscitation the child can now tolerate."),assessment:e("A new finding changes the next step",["Confusion and weak pulses","New bilateral crackles","More prominent liver edge"],"The new lung findings and liver examination belong in the same conversation as the low pressure. They are evidence that repeating the previous intervention may carry a different cost now."),vitals:e("Shock and respiratory compromise coexist",[],"The pressure demands action, but it does not specify the action by itself. Pair it with the oxygen requirement and the new examination before deciding whether more fluid is appropriate.",{label:"Two questions",text:"Is perfusion adequate? Is further fluid tolerated?"}),labs:e("Persistent physiological stress",[],"The lactate and acidemia add urgency. They do not tell us that every remaining deficit should be treated with another bolus. The next decision needs a broader assessment.",{label:"Interpretation",text:"Persistent shock does not identify a single treatment"}),diagnostics:e("Cardiac and lung findings guide tolerance",["Reduced global ventricular function","Bilateral lung B-lines","Source still requires evaluation"],"Ultrasound helps us understand the response to treatment, with the limits of the examination kept in mind. It does not replace the infection workup or turn one image into a complete shock diagnosis."),decision:e("What changes after the crackles appear?",["Reassess additional fluid","Escalate circulation support","Address worsening respiratory function"],"Choose the next intervention using both perfusion and tolerance. The challenge is to keep resuscitating while changing its form as the evidence changes."),reasoning:e("Adjust the resuscitation to the physiology",["Vasoactive and respiratory escalation","Stop automatic fluid repetition","Recheck source, access and treatment delivery"],"The team needs a shared explanation for the change in plan. Describe the new findings, the earlier interventions and their response so the next clinician does not restart the same sequence blindly."),reassessment:e("Document what changed and why",["Perfusion begins to improve with support","Track oxygen requirement","Handoff: fluids, responses and ultrasound limits"],"The volume already given is only part of the handoff. The response to each amount, and the point at which respiratory findings emerged, explain the reasoning behind the current support."),synopsis:e("Septic shock: perfusion and tolerance travel together",["Shock can coexist with myocardial dysfunction","New findings can change the next intervention","Reassess the response to every treatment"],"Remember the moment the examination changed. That is the clue that turns a routine sequence of orders into an individualized resuscitation.")},"bronchiolitis-feeding":{presentation:e("Breathing interrupts feeding",["5 months \xB7 6.4 kg \xB7 term birth","Coryza and cough for 3 days","Reduced feeds and wet diapers","No witnessed apnea"],"For an infant, a feeding history is also a functional respiratory history. Ask the caregiver what happens when the bottle or breast is offered, and how that compares with yesterday."),assessment:e("Effort and intake are linked",["Alert with subcostal recession","Diffuse crackles and wheeze","Copious nasal secretions","Feeding increases distress"],"The child has to coordinate breathing with feeding. When that ordinary task becomes difficult, it adds information that a spot saturation cannot capture."),vitals:e("Persistent hypoxemia with rapid breathing",[],"The saturation needs attention, and so does the sustained effort. An oxygen response will help one part of the problem while we continue to assess fatigue and the ability to hydrate safely.",{label:"Follow both",text:"Breathing effort and feeding tolerance"}),labs:e("Testing follows a clinical question",[],"The absence of a routine blood panel is a deliberate decision here. A test earns its place when its result would change the next step, particularly in a distressed infant.",{label:"Current plan",text:"Bedside glucose checked; other testing not routinely required"}),diagnostics:e("A clinical bronchiolitis pattern",["Typical history and diffuse findings","Routine X-ray and viral testing not always needed","Investigate a new or atypical concern"],"The wheeze can tempt us to borrow an asthma treatment story. Start instead with the infant\u2019s age, course and overall pattern, and build supportive care around the problems actually present."),decision:e("What does the feeding history change?",["Hydration planning","Assessment of respiratory burden","Need for further support"],"Imagine the oxygen number improves but the infant still cannot feed without distress. Would the overall problem be solved? Keep that question for the reassessment."),reasoning:e("Support breathing and hydration together",["Oxygenation and nasal secretion management","A tolerable hydration plan","Escalate for persistent distress or fatigue"],"A useful plan describes how we will know supportive care is enough. That means naming the signs that would trigger a change in respiratory support, rather than only naming a saturation goal."),reassessment:e("The saturation improves first",["SpO\u2082: 88% \u2192 94%","Respiratory rate remains high","Effort and hydration still need assessment"],"This is a real improvement in one domain. The continuing respiratory rate and feeding problem explain why the team keeps watching and adjusting rather than closing the case."),synopsis:e("Bronchiolitis: breathing and feeding are one story",["Use function as well as monitor data","Support hydration safely","Reassess beyond the oxygen number"],"The caregiver\u2019s account of feeding was central evidence. Carry it forward alongside the respiratory examination when you decide whether an infant is improving.")},"bronchiolitis-apnea":{presentation:e("The dangerous moments are intermittent",["6 weeks \xB7 3.6 kg","Born at 34 weeks","Congestion with witnessed pauses in breathing","Another episode during assessment"],"This infant may look relatively comfortable when you first arrive. The caregiver\u2019s account and the observed event tell a much more serious story than the appearance between episodes."),assessment:e("Examine the event, not only the interval",["Mild recession between events","Limpness during apnea","Heart rate falls during the episode"],"A brief bedside snapshot can miss the highest-risk physiology. Ask what happened during the event, what restored breathing and how completely the infant recovered."),vitals:e("Apnea changes the risk assessment",[],"These are values during the event, not a routine resting baseline. Their timing matters: the heart rate and saturation fall with loss of effective breathing.",{label:"Event context",text:"Heart rate 76/min and SpO\u2082 72% during apnea"}),labs:e("Results obtained after stabilization",[],"Sampling follows the immediate ventilation response. The gas adds to our understanding after the event; it was not a reason to delay effective breaths when the infant stopped breathing.",{label:"Sequence",text:"Restore ventilation \u2192 reassess \u2192 investigate"}),diagnostics:e("Keep the cause of apnea open",["Bronchiolitis remains possible","Evaluate infection and metabolic or neurological causes","Young age and prematurity increase concern"],"A viral prodrome gives us a plausible context, but plausibility should not close the differential. The repeated episodes deserve their own evaluation and escalation plan."),decision:e("Can the interval examination establish safety?",["What happens during the event?","How is ventilation restored?","Can the team manage recurrence?"],"Think about the next episode occurring during movement or transport. The care plan has to work at that moment, not only during the quiet minute when everyone is looking at the infant."),reasoning:e("Build a reliable ventilation plan",["Immediate support when breathing is inadequate","Continuous cardiorespiratory monitoring","Appropriate critical care destination"],"Monitoring detects a problem, but it does not provide the response. The team also needs the equipment, skills and shared plan to establish ventilation promptly if apnea returns."),reassessment:e("Recovery does not remove recurrence risk",["Assisted ventilation restores heart rate and saturation","Episodes recur","Document timing, response and recovery"],"The recovery shows that the intervention worked for that event. The recurrent pattern still determines the required level of supervision and the capabilities needed during the journey."),synopsis:e("Apnea: the event drives the plan",["A comfortable interval can be misleading","Ventilation takes priority during apnea","Investigate the cause and prepare for recurrence"],"Remember the difference between how the infant looks now and what the infant can do next. A good handoff describes both.")},"croup-at-rest":{presentation:e("Noisy breathing persists while calm",["2 years \xB7 12 kg","Viral prodrome","Barking cough and hoarse voice","Stridor on caregiver\u2019s lap"],"The caregiver\u2019s lap gives us a useful low-distress observation. Stridor that persists there has a different meaning from a sound heard only while the child is crying."),assessment:e("Assess without adding distress",["Alert with inspiratory stridor","Moderate sternal recession","No drooling or tripod posture","No reported choking"],"The examination is partly about restraint. We want the information that changes care without turning a calm child into an agitated one and making the breathing harder."),vitals:e("A normal saturation can coexist with obstruction",[],"The oxygen reading is reassuring about current oxygenation. The stridor at rest and recession still tell us that the upper airway is significantly narrowed.",{label:"Bedside severity",text:"Stridor at rest + recession + behavior + air entry"}),labs:e("No routine panel to wait for",[],"This is a case where the useful information comes from observation and response to treatment. Avoid making routine testing a prerequisite for acting on a typical clinical presentation.",{label:"Clinical assessment",text:"Routine blood tests are not indicated initially"}),diagnostics:e("Use imaging for a question, not a ritual",["Typical croup is a clinical diagnosis","The optional image is a separate teaching reference","Atypical findings would broaden the workup"],"A reference image can help with later learning without being something this child needs now. Keep the teaching illustration separate from the sequence of care at the bedside."),decision:e("Would 96% make you call this mild?",["Stridor continues at rest","Recession is present","The child is currently alert"],"Choose the findings that determine your severity assessment. Then think about which findings you would want to see change after treatment."),reasoning:e("Calm care, treatment, observation",["Minimize distress","Protocol-directed corticosteroid and epinephrine","Observe response and recurrence"],"The response over time matters. A treatment can reduce symptoms before we know whether that improvement will last, so the observation timeline belongs in the plan."),reassessment:e("Stridor resolves at rest",["Continue pathway-directed observation","Watch for recurrence","Handoff medication and observation times"],"A quieter child is reassuring here because the overall assessment improves. Compare that with the exhausted child in the companion case, where the same reduction in sound means something very different."),synopsis:e("Croup: assess the airway before the saturation falls",["Stridor at rest carries weight","Keep assessment calm","Response and recurrence guide the next step"],"The useful lesson is how the observations fit together. Sound, effort, behavior and the course after treatment explain more than an oxygen number alone.")},"croup-exhaustion":{presentation:e("The stridor gets softer as the child tires",["3 years \xB7 14 kg","Barking cough followed by distress","Drowsiness develops","Softer stridor"],"The change in sound is easy to notice; the change in the child is more important. This case begins at the point where an expected croup story becomes a threatened-airway story."),assessment:e("Airflow and interaction are falling",["Severe recession","Poor air movement","Reduced interaction","Broaden the airway differential"],"We should resist interpreting softer noise without checking air movement. The drowsiness and reduced airflow are the findings that change the urgency and the expertise required."),vitals:e("Reduced effort with worsening oxygenation",[],"The respiratory rate has fallen, but the breathing is less effective. A lower count is not a recovery signal when the child is tiring and becoming hypoxemic.",{label:"Direction needs context",text:"Fewer breaths with less effective air movement"}),labs:e("Do not interrupt airway support for sampling",[],"The missing laboratory result is not the missing answer. The immediate problem is effective ventilation through a critically narrowed airway, and the team must organize around that.",{label:"Immediate priority",text:"Airway support before routine blood sampling"}),diagnostics:e("Atypical severity broadens the differential",["Croup","Bacterial tracheitis or epiglottitis","Foreign-body obstruction","Support the airway before imaging"],"The first label may still be right, but it should not limit the rescue plan. Poor response or an atypical course is a reason to bring in airway expertise and reconsider the cause."),decision:e("What does less noise mean here?",["Less airflow?","Exhaustion?","A need for coordinated rescue?"],"Picture this child becoming upset during a throat examination or a trip to radiology. Decide which information is worth that disruption while the airway is already failing."),reasoning:e("Coordinate the rescue before the next deterioration",["Immediate pediatric airway expertise","Support oxygenation and ventilation","Minimize agitation and unnecessary movement"],"A threatened pediatric airway benefits from a shared plan. The people, equipment and rescue options need to be organized together while disease-directed treatment continues."),reassessment:e("Describe the trajectory in the handoff",["Controlled resuscitation setting","Expert airway management","Trend sound, effort and consciousness"],"The final saturation is only the last frame of the story. The receiving team needs to know that noise softened while effort and interaction declined, because that explains the intervention."),synopsis:e("A quiet upper airway can be a failing airway",["Less noise can reflect less airflow","Consciousness and effort determine urgency","Rescue and diagnosis proceed in the right order"],"The same word, quieter, described recovery in one child and exhaustion in another. The accompanying physiology gives the word its meaning.")}};var Y={...U,..._,...K,...$};var c=(s,n)=>({title:s,url:n}),I={child:c("RCH \xB7 Acceptable observations for unwell children","https://www.rch.org.au/clinicalguide/guideline_index/normal_ranges_for_physiological_variables/"),lab:c("NBME \xB7 Laboratory reference values","https://www.nbme.org/laboratory-values/"),arterial:c("University of Iowa \xB7 Arterial blood gases","https://www.healthcare.uiowa.edu/path_handbook/handbook/test303.html"),venous:c("University of Iowa \xB7 Peripheral venous blood gases","https://www.healthcare.uiowa.edu/path_handbook/handbook/test3479.html"),glucose:c("University of Iowa \xB7 Random glucose","https://www.healthcare.uiowa.edu/path_handbook/handbook/test883.html"),lactate:c("University of Iowa \xB7 Whole-blood lactate","https://www.healthcare.uiowa.edu/path_handbook/handbook/test1184.html"),neonatalLactate:c("University of Iowa \xB7 Plasma lactic acid by age","https://www.healthcare.uiowa.edu/path_handbook/handbook/test3349.html"),newborn:c("AHA / AAP \xB7 Neonatal resuscitation (2025)","https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/neonatal-resuscitation"),newbornGlucose:c("Pediatric Endocrine Society \xB7 Neonatal hypoglycemia recommendations","https://pedsendo.org/wp-content/uploads/2020/06/PES_recommendation_hypoglycemia.pdf"),dka:c("RCH \xB7 Pediatric diabetic ketoacidosis","https://www.rch.org.au/clinicalguide/guideline_index/Diabetic_Ketoacidosis/"),preterm:c("NICE NG124 \xB7 Preterm respiratory support","https://www.nice.org.uk/guidance/ng124/chapter/Recommendations"),ob:c("ACOG \xB7 Gestational hypertension and preeclampsia, Bulletin 222","https://www.preeclampsia.org/frontend/assets/img/advocacy_resource/Gestational_Hypertension_and_Preeclampsia_ACOG_Practice_Bulletin,_Number_222_1605448006.pdf"),fetal:c("NICE NG229 \xB7 Fetal monitoring in labour","https://www.nice.org.uk/guidance/ng229/chapter/Recommendations"),pph:c("WHO \xB7 Consolidated postpartum haemorrhage guideline (2025)","https://www.who.int/publications/i/item/9789240115637"),sepsis:c("SCCM \xB7 Adult sepsis guidelines","https://www.sccm.org/survivingsepsiscampaign/guidelines-and-resources/surviving-sepsis-campaign-adult-guidelines"),ards:c("ATS \xB7 ARDS guideline update (2024)","https://pmc.ncbi.nlm.nih.gov/articles/PMC10870893/"),bnp:c("University of Florida \xB7 BNP assay and reference values","https://pathlabs.ufl.edu/tests/test-directory-b/b-type-natriuretic-peptide/"),ef:c("AHA \xB7 Ejection fraction","https://www.heart.org/en/health-topics/heart-failure/diagnosing-heart-failure/ejection-fraction-heart-failure-measurement"),adult:c("MedlinePlus \xB7 Vital signs","https://medlineplus.gov/ency/article/002341.htm"),temperature:c("HealthLink BC \xB7 Temperature, fever and measurement context","https://www.healthlinkbc.ca/healthwise/fever"),oxygen:c("MedlinePlus \xB7 Pulse oximetry","https://medlineplus.gov/lab-tests/pulse-oximetry/")},r=(s,n)=>({text:s,source:I[n]}),i={hrAdult:r("A resting adult heart rate is commonly 60 to 100 beats per minute. Pregnancy, pain and medications can shift the baseline.","adult"),rrAdult:r("This resting adult respiratory-rate reference is 12 to 18 breaths per minute; assess depth and effort as well as the count.","adult"),bpAdult:r("An adult pressure is commonly around 90 over 60 to below 120 over 80 at rest. A systolic pressure below 90 is concerning in an acutely ill patient; perfusion and baseline matter.","adult"),bpOb:r("In pregnancy, a pressure below 140 over 90 is below the hypertension threshold. Severe hypertension is a systolic pressure of at least 160 or a diastolic pressure of at least 110; either component qualifies.","ob"),sat:r("At sea level, oxygen saturation is usually 95 to 100 percent in a person without a special oxygen target. Verify signal quality and the oxygen support in use.","oxygen"),temp:r("Temperature depends on site and time of day; about 36.5 to 37.5 degrees Celsius is a useful reference. A temperature of 38 or more is fever, and below 36 is concerning in an ill patient.","temperature"),apH:r("The usual arterial pH reference is 7.35 to 7.45; lower is acidemia and higher is alkalemia.","arterial"),npH:r("For the first month of life, this laboratory lists arterial pH from 7.32 to 7.42. Ventilation goals in a preterm infant are individualized.","arterial"),vpH:r("This pediatric peripheral venous pH reference is 7.30 to 7.40. Venous and arterial samples must be identified separately.","venous"),avpH:r("This adult peripheral venous pH reference is 7.33 to 7.43.","venous"),co2:r("The usual adult arterial carbon dioxide reference is 35 to 45 millimeters of mercury.","arterial"),pco2:r("This laboratory lists pediatric arterial carbon dioxide from 30 to 40 millimeters of mercury. A treatment target may differ from a laboratory reference.","arterial"),vco2:r("This laboratory lists pediatric peripheral venous carbon dioxide from 32 to 45 for girls and 35 to 48 for boys, in millimeters of mercury. It cannot measure arterial oxygenation.","venous"),po2:r("This laboratory lists adult arterial oxygen tension from 80 to 90 millimeters of mercury. Inspired oxygen, altitude and age affect interpretation.","arterial"),ppo2:r("For children older than one month, this laboratory lists arterial oxygen tension from 80 to 100 millimeters of mercury. Always state the oxygen support.","arterial"),npo2:r("For the first month this laboratory lists arterial oxygen tension from 60 to 80 millimeters of mercury. A congenital cardiac lesion can require a different treatment target.","arterial"),k:r("The serum potassium teaching reference is 3.5 to 5.0 millimoles per liter; use the reporting laboratory and exclude sample hemolysis.","lab"),na:r("The serum sodium teaching reference is 136 to 146 millimoles per liter; in DKA also consider the effect of hyperglycemia and the trend.","lab"),glucose:r("For a random sample after the first month, this laboratory lists glucose from 65 to 139 milligrams per deciliter. Fasting reference limits and treatment thresholds differ.","glucose"),bicarb:r("The serum bicarbonate teaching reference is 22 to 28 millimoles per liter.","lab"),ketone:r("In a fed child, significant ketonemia is not expected. In the pediatric DKA pathway, beta hydroxybutyrate of at least 3 millimoles per liter is a diagnostic ketosis threshold, not a normal limit.","dka"),lactate:r("The whole-blood lactate reference here is 0.5 to 2.0 millimoles per liter for adults. A high value is a stress and perfusion clue, not a diagnosis by itself.","lactate"),plactate:r("The whole-blood lactate reference here is 0.5 to 2.2 millimoles per liter below age sixteen. Sampling method and the clinical trend matter.","lactate"),platelets:r("An adult platelet count is commonly about 150 to 400 times ten to the ninth per liter. In preeclampsia, a count below 100 is a severe-feature threshold.","ob"),ast:r("The adult AST teaching reference is 12 to 38 units per liter; local assay limits vary. More than twice the upper limit is relevant to preeclampsia assessment.","lab"),ldh:r("The adult LDH teaching reference is 45 to 200 units per liter, with substantial assay variation. In HELLP, an LDH of at least 600 is commonly used as evidence supporting hemolysis.","ob"),creatinine:r("A general adult creatinine reference is 0.6 to 1.2 milligrams per deciliter. Pregnancy usually lowers creatinine; a value above 1.1 or doubling from baseline is a preeclampsia severe-feature criterion without another renal cause.","ob"),adultCreatinine:r("The adult creatinine teaching reference is 0.6 to 1.2 milligrams per deciliter. Acute change from baseline and urine output matter more than the reference interval alone.","lab"),fibrinogen:r("Fibrinogen normally rises in late pregnancy. During postpartum hemorrhage, less than 200 milligrams per deciliter is a replacement threshold in the WHO guideline; 200 is a treatment threshold, not a normal pregnancy value.","pph"),hemoglobin:r("The nonpregnant adult female hemoglobin teaching reference is 12 to 16 grams per deciliter. Gestation and fluid shifts change the baseline, and an early sample can underestimate acute blood loss.","lab"),fetal:r("The usual fetal baseline heart rate is 110 to 160 beats per minute. Baseline duration, variability and decelerations must also be reviewed.","fetal"),troponin:r("High-sensitivity troponin is interpreted against the assay-specific ninety-ninth percentile, with sex-specific limits where provided. There is no single interchangeable normal number across assays.","lab"),newbornHR:r("The RCH term-newborn observation reference is 120 to 170 beats per minute. In a preterm infant, gestation, sleep and respiratory support also affect the expected rate.","child"),newbornRR:r("A term-newborn observation reference is 25 to 60 breaths per minute. Preterm respiratory effort and gas exchange require individual assessment.","child"),newbornBP:r("The RCH term-newborn systolic observation reference is 60 to 95 millimeters of mercury. Compare limb measurements with correct cuffs, pulses and perfusion.","child"),newbornTemp:r("The neonatal resuscitation temperature goal is 36.5 to 37.5 degrees Celsius.","newborn"),pretermSat:r("After initial stabilization, NICE recommends a preterm oxygen saturation target of 91 to 95 percent. That is a treatment target, not a delivery-room first-minute reference.","preterm")},g=(s,n,o,l)=>({hr:r(`For ${s}, the RCH acceptable heart-rate range for unwell children is ${n} beats per minute. This is broader than a healthy resting range; trends and examination still determine severity.`,"child"),rr:r(`For ${s}, the RCH acceptable respiratory-rate range for unwell children is ${o} breaths per minute. A count in range does not establish adequate ventilation.`,"child"),bp:r(`For ${s}, the RCH acceptable systolic-pressure range for unwell children is ${l} millimeters of mercury. It is an observation reference, not a shock rule-out threshold.`,"child")}),a=(s,n,o)=>({reference:s,interpretation:n,associations:o}),d=r;var q=g("an eight-year-old","70 to 130","16 to 30","80 to 115"),L=g("a twelve-year-old","65 to 120","15 to 25","90 to 120"),O=g("a ten-year-old","60 to 130","15 to 25","85 to 120"),D=g("the six-year observation band, used here as a nearby reference for a seven-year-old","75 to 140","16 to 30","80 to 115"),B=g("a four-year-old","80 to 150","17 to 30","75 to 110"),z=g("the eight-year observation band, used here as a nearby reference for a nine-year-old","70 to 130","16 to 30","80 to 115"),Q=g("the six-month observation band, used here as a nearby reference for a five-month-old","110 to 170","20 to 55","75 to 105"),Te=g("a young infant, using the term-newborn observation band as a reference","120 to 170","25 to 60","60 to 95"),X=g("a two-year-old","95 to 150","20 to 40","70 to 105"),J=g("the two-year observation band, used here as a nearby reference for a three-year-old","95 to 150","20 to 40","70 to 105"),j=d("A typical clinical airway presentation does not require a normal laboratory panel before treatment. No measured value exists here.","child"),Z={"asthma-speaking-in-words":{diagnosis:"Acute severe asthma exacerbation with hypoxemia",imaging:{ids:["cxr-hyperinflation-asthma-2025"],narration:"The real comparison radiograph comes from a different child with near-fatal asthma. Look at the expanded dark lung fields and low flattened diaphragms, appearances of hyperinflation from trapped gas. A normal film would have less expansion and more domed diaphragms. For an audio-only listener, imagine air getting in more easily than it gets out through narrowed bronchi. Hyperinflation is not specific to asthma, and a radiograph is not needed to recognize this child\u2019s typical exacerbation."},handoff:"EMS brings this child from home to the emergency department. The mother says the usual rescue inhaler has stopped giving lasting relief since a cold began yesterday. The crew found bilateral wheeze, gave inhaled albuterol with oxygen, and reports only brief improvement in speech. There is no urticaria, facial swelling or sudden choking event. We are presenting severe asthma, not an unexplained wheezing syndrome.",course:"In the emergency department, oxygen, repeated albuterol with initial ipratropium, and an early systemic corticosteroid are delivered under the pediatric asthma pathway. Staff confirm that the mask fits and that medication is actually reaching the child. Because substantial distress persists after the initial cycle, pediatric critical care is consulted and intravenous magnesium is considered under that pathway. With improved speech and air entry, the child is admitted for continued bronchodilators and monitoring rather than discharged after one better saturation. In this synthetic course, there is no intubation. Before discharge after sustained improvement, the family demonstrates spacer technique and receives a controller review and a written action plan.",findings:{"Heart rate":a(q.hr,"This is tachycardia. Distress, hypoxemia and albuterol can all contribute; the rate alone cannot separate them.","A fast pulse may accompany agitation, tremor or palpitations; poor perfusion would add concern rather than being assumed from the rate."),"Blood pressure":a(q.bp,"The systolic pressure is within this reference. Strong pulses fit preserved perfusion at this assessment, while the respiratory problem remains severe.","Shock would commonly add weak pulses, delayed refill, cool extremities or altered interaction; we are actively checking for those changes."),"Respiratory rate":a(q.rr,"This is tachypnea. The prolonged expiratory phase, recession and one-word speech connect the high count to lower-airway obstruction.","Associated signs include accessory-muscle use, inability to speak normally and fatigue. This child already has the first two."),"SpO\u2082":a(i.sat,"This is hypoxemia on room air. Obstructed lung units are ventilated unevenly, reducing effective oxygen transfer.","Restlessness and tachycardia may precede cyanosis; absence of visible cyanosis would not make this saturation normal."),Temperature:a(i.temp,"This reading is slightly above the teaching interval but below the fever threshold. A viral trigger is plausible; this value does not establish bacterial pneumonia.","Fever may cause flushing or chills. New focal crackles or a sustained high fever would change the infection assessment."),"Venous pH":a(i.vpH,"This venous pH is in the stated range. It does not show severe acidemia, but it also does not measure how much respiratory reserve remains.","Worsening ventilatory failure can add drowsiness and shallow breathing; those bedside changes outrank a previously acceptable pH."),"Venous PCO\u2082":a(i.vco2,"This value is within the cited peripheral venous ranges. A severely distressed child may initially lower carbon dioxide; a normal-looking value with worsening effort can therefore be concerning.","Carbon dioxide retention may be accompanied by headache, confusion or drowsiness. None is inferred merely from this single venous value."),Potassium:a(i.k,"This is mild hypokalemia. Beta agonists can shift potassium into cells, so repeated treatment makes the trend relevant.","More marked hypokalemia can cause weakness, cramps, ectopy and flattened T waves; those are associations to monitor, not documented findings here.")}},"asthma-silent-chest":{diagnosis:"Life-threatening status asthmaticus with acute hypercapnic and hypoxemic respiratory failure",imaging:{ids:["cxr-hyperinflation-asthma-2025"],narration:"The slide includes a real chest radiograph from a different twelve-year-old with near-fatal asthma, not our synthetic patient. The lungs look overexpanded and unusually dark, with flattened low diaphragms. Normally those diaphragms are more domed. The comparison illustrates gas trapping behind narrowed airways. It cannot measure this patient\u2019s ventilation or prove the cause of a silent chest. In our case, bedside failure prompted resuscitation first; the later fictional post-intubation report excluded a pneumothorax."},handoff:"Let us name the diagnosis at the outset: this child has status asthmaticus and is now failing ventilation. EMS originally brought the child to a community emergency department after the mother found the rescue inhaler was no longer helping. The mother reports established asthma, a prior admission, two days of rhinorrhea and cough, and no choking, hives or facial swelling. The EMS report describes an alert child sitting forward with diffuse expiratory wheeze and marked retractions. Repeated inhaled albuterol and ipratropium, oxygen, a systemic corticosteroid and then intravenous magnesium were given through the referring pediatric pathway. Thirty minutes later, while the transfer team checks the stretcher and oxygen supply, the child can no longer hold the nebulizer. That is the time point we are examining.",course:"The team stops departure and calls pediatric anesthesia and critical care to the resuscitation bay. Oxygen and inhaled bronchodilation continue while ventilation is supported and an airway plan is executed for exhaustion and declining consciousness. After intubation, waveform carbon dioxide, chest movement and auscultation confirm effective ventilation; a radiograph obtained only after stabilization confirms tube position without pneumothorax. Ventilation is adjusted for severe obstruction with a low enough minute ventilation to allow expiration, watching the expiratory flow return toward baseline and monitoring pressures and blood pressure. We do not force carbon dioxide immediately into a normal interval at the cost of air trapping. Forty minutes after stabilization, a repeat arterial gas on reduced supplemental oxygen shows pH 7.28 and carbon dioxide 55. Both remain abnormal against the earlier reference, but the acidemia and hypercapnia are improving. Saturation is 95 percent, within the usual oxygenation reference, and blood pressure is 106 over 64 with warm extremities. In this synthetic outcome, bronchospasm improves over the next day, the child is extubated on the second hospital day, and the family receives asthma prevention and inhaler education before discharge. The confirmed diagnosis remains asthma-associated respiratory failure; no foreign body, focal pneumonia or anaphylaxis is found.",findings:{"Heart rate":a(L.hr,"This is marked tachycardia. Respiratory distress, hypoxemia and repeated beta agonist treatment can all contribute in this child.","Common associations include a visibly pounding pulse, tremor and agitation; new weak pulses or cool skin would suggest compromised circulation."),"Blood pressure":a(L.bp,"The systolic reading lies near the lower end of this broad observation range. It does not by itself prove hypotensive shock, but leaves little reassurance in a drowsy child about to receive positive pressure.","Reduced cardiac output may produce delayed refill, weak pulses and cool extremities. Recheck the cuff and trend perfusion during airway management."),"Respiratory rate":a(L.rr,"Eighteen is numerically within the reference, but the fall from forty-two with shallow breaths and drowsiness is respiratory exhaustion, not recovery. Minute ventilation depends on breath size as well as rate.","Impending failure commonly brings poor chest excursion, inability to speak, reduced air entry and altered consciousness. All are present in this case."),"SpO\u2082":a(i.sat,"This is persistent hypoxemia despite oxygen, verified with a reliable waveform. The support requirement makes it more concerning than the same reading without oxygen.","Hypoxemia can cause restlessness, tachycardia and later cyanosis or reduced consciousness; this child already has tachycardia and reduced interaction."),"Arterial pH":a(i.apH,"This is substantial acidemia. With the raised arterial carbon dioxide and shallow breathing, a respiratory acidosis is present; bicarbonate and the wider chemistry would assess any additional metabolic component.","Acidemia can accompany cardiovascular instability. In respiratory failure, fatigue and declining consciousness are clinically important accompanying signs."),"PaCO\u2082":a(i.pco2,"This is hypercapnia, meaning inadequate alveolar ventilation relative to carbon dioxide production. In this exhausted asthmatic child it confirms ventilatory failure, not simply an obstructed but compensating airway.","Carbon dioxide retention can cause headache, confusion and drowsiness. The slow response to voice is already part of this child\u2019s examination."),"PaO\u2082":a(i.ppo2,"This is arterial hypoxemia despite supplemental oxygen. The exact delivered oxygen fraction through a nebulizer interface is uncertain, so we do not calculate an oxygenation ratio from it.","Severe oxygen deficit may cause cyanosis and impaired consciousness; visible color is an insensitive way to exclude it.")}},"dka-first-diagnosis":{diagnosis:"New-onset type 1 diabetes presenting with diabetic ketoacidosis",handoff:"EMS was called for repeated vomiting and fast breathing. The father describes a previously well child who has been taking water to bed and waking to urinate for two weeks. The referring examination finds dehydration and a clear chest rather than a primary wheezing illness. The diagnosis is DKA; the deep breathing is part of the metabolic presentation.",course:"After the initial circulation assessment, the team uses a pediatric DKA pathway for measured isotonic fluid, followed by insulin infusion without an insulin bolus and potassium management based on repeated chemistry and urine output. Dextrose is added as glucose falls so insulin can continue treating ketogenesis. The later glucose of 330 remains hyperglycemic compared with the stated reference. Potassium of 3.7 is still in range but falling, which makes replacement and surveillance important. In this synthetic hospital course, ketones and acidosis resolve with continued monitored treatment, mental status remains normal, and diabetes education begins before discharge. Glucose alone is never used to declare DKA resolved.",findings:{"Heart rate":a(O.hr,"This rate is toward the upper end of the broad unwell-child range. With dry mucosa and delayed refill, volume depletion is clinically important even without crossing that upper limit.","Dehydration commonly causes thirst, dry mucosa, reduced urine output and tachycardia; polyuria can precede the later fall in output."),"Blood pressure":a(O.bp,"The systolic pressure is within range. Children can preserve pressure despite substantial dehydration, so this does not cancel the refill and mucosal findings.","Worsening volume loss may add weak pulses, cool skin or lethargy before overt hypotension."),"Respiratory rate":a(O.rr,"This is tachypnea with deep compensatory breathing, often called Kussmaul respiration in DKA. Carbon dioxide elimination partially compensates for metabolic acidosis.","Deep regular breaths, acetone odor, abdominal pain and vomiting often accompany this presentation; wheeze is not required."),"SpO\u2082":a(i.sat,"Oxygenation is within the usual reference on room air. The rapid deep breathing is driven by acidosis, not demonstrated hypoxemia.","Acidotic respiratory effort can be substantial without cyanosis; normal saturation does not exclude a metabolic emergency."),Glucose:a(i.glucose,"This is marked hyperglycemia. Glucose-driven osmotic diuresis explains the thirst, frequent urination and dehydration.","Common associated symptoms are polyuria, polydipsia, weight loss and blurred vision; the family has already supplied the first three."),"Venous pH":a(i.vpH,"This is acidemia. Together with ketonemia and low bicarbonate it supports the metabolic acidosis of DKA.","Acidosis commonly produces deep breathing, nausea, abdominal pain and fatigue; neurological deterioration requires separate urgent evaluation."),Bicarbonate:a(i.bicarb,"This is markedly reduced bicarbonate, consumed buffering ketoacids. It explains why the child is trying to lower carbon dioxide through deep breathing.","Low bicarbonate from metabolic acidosis may accompany Kussmaul breathing and vomiting; it is not evidence of an asthma attack."),"\u03B2-hydroxybutyrate":a(i.ketone,"This is significant ketonemia above the DKA threshold. Insulin deficiency is allowing fat-derived ketone production.","Ketosis may be associated with acetone odor, nausea and abdominal pain; odor alone is neither required nor diagnostic."),Potassium:a(i.k,"The serum value is within range, but total-body potassium is commonly depleted in DKA. Insulin and correction of acidosis can lower the measured value rapidly.","A subsequent potassium deficit may cause weakness or arrhythmias; a normal initial result does not eliminate that risk.")}},"dka-new-headache":{diagnosis:"DKA complicated by suspected cerebral injury during treatment",handoff:"At handoff, the referring nurse says the child was conversing normally before the new headache, vomiting and irritability began. The parent now struggles to keep the child awake. We are treating a clinical diagnosis of DKA-associated cerebral injury; imaging has not confirmed its mechanism, and a normal glucose trend would not exclude it.",course:"The team calls pediatric critical care, treats suspected cerebral injury immediately with pathway-directed hyperosmolar therapy, positions the head appropriately, and reassesses the fluid plan and airway. Treatment is not postponed for a CT scan. The child becomes more responsive after emergency treatment and is transferred with serial neurological examinations. In the synthetic receiving-unit course, imaging after stabilization excludes hemorrhage and another structural cause; it does not retrospectively replace the clinical diagnosis. The child recovers without a persistent focal deficit. DKA treatment continues with repeated sodium, potassium, glucose and acid-base assessment.",findings:{"Heart rate":a(D.hr,"Eighty-two lies within the nearby age-band range, but the fall from 132 accompanying headache and drowsiness is relative bradycardia. The trajectory is concerning for cerebral injury.","Raised intracranial pressure can produce a slowing pulse, rising pressure and altered breathing; the full late triad need not be present."),"Blood pressure":a(D.bp,"The systolic value exceeds this nearby observation band. With the slowing pulse and altered consciousness, a rising pressure increases concern, though a pediatric hypertension diagnosis requires proper age, sex and height assessment.","Associated warning signs include worsening headache, vomiting, altered consciousness and new abnormal respiratory pattern."),"Respiratory rate":a(D.rr,"The count is within the nearby band. It does not establish neurological safety; inspect pattern, depth and whether compensatory ventilation is being maintained.","Cerebral deterioration may cause irregular or inadequate breathing, so a new pattern matters even before the count leaves range."),"SpO\u2082":a(i.sat,"This is normal measured oxygen saturation. It cannot exclude raised intracranial pressure or ongoing DKA.","Neurological injury can cause headache, vomiting and drowsiness while oxygen saturation remains normal."),Glucose:a(i.glucose,"This remains hyperglycemia despite improvement from the original DKA presentation. A falling glucose does not explain away new neurological signs.","Hyperglycemia may cause thirst and polyuria; headache with declining consciousness here needs the cerebral-injury pathway."),"Venous pH":a(i.vpH,"There is persistent acidemia. DKA has not resolved, even though its chemistry may be improving.","Deep breathing and fatigue can persist with acidosis, but a new neurological change must not be attributed to fatigue without action."),Sodium:a(i.na,"This measured sodium is within the reference. Its trend and glucose-corrected context matter; one normal sodium does not exclude cerebral injury.","Major sodium disturbances may cause confusion or seizures, but no sodium disturbance is established by this measurement."),Potassium:a(i.k,"This is within range near the lower limit. Continued insulin can lower it further, so replacement decisions need the next result and urine output.","Falling potassium can cause muscle weakness and arrhythmias; it does not account for the entire neurological pattern here.")}},"sepsis-normal-pressure":{diagnosis:"Pediatric sepsis with compensated shock from a febrile urinary infection",handoff:"The mother tells EMS that the child has become unusually sleepy, has pain on urination and has not passed urine for eight hours. At the community department, urine microscopy shows pyuria and cultures are sent. There is no focal chest finding. We diagnose sepsis with clinical shock before the pressure falls; the urinary source remains provisional until cultures return.",course:"The team gives prompt intravenous antimicrobials and carefully reassessed isotonic fluid under the pediatric sepsis pathway. Refill improves only partly, so repeated boluses are not automatic and vasoactive escalation is prepared. During the next hour the child becomes more interactive, pulses strengthen and urine output returns after sustained resuscitation. The receiving service later identifies Escherichia coli in urine and blood cultures and narrows therapy to susceptibility results. This synthetic outcome establishes a urinary source with bacteremia rather than leaving infection unspecified.",findings:{"Heart rate":a(B.hr,"This is tachycardia beyond the broad unwell-child range. Fever contributes, but the weak pulses, lethargy and prolonged refill indicate more than fever alone.","Shock may be accompanied by cool or mottled skin, delayed refill, reduced urine and altered interaction; several are present."),"Blood pressure":a(B.bp,"Systolic pressure is preserved within the reference. This is compensated shock: the examination shows poor perfusion despite a maintained pressure.","Vasoconstriction may preserve pressure while extremities cool, pulses weaken and urine output falls."),"Respiratory rate":a(B.rr,"This is tachypnea. Fever and metabolic stress from poor perfusion can drive breathing even without a focal lung disease.","In sepsis, rapid breathing may accompany lethargy, fever and poor perfusion; new crackles would prompt reassessment for lung involvement or fluid intolerance."),Temperature:a(i.temp,"This is fever. It supports the infectious history but neither measures shock severity nor identifies the organism.","Fever can produce flushing, rigors and a rapid pulse; a child with sepsis may also be normothermic or hypothermic."),"SpO\u2082":a(i.sat,"This is at the lower boundary of the usual reference. It does not measure systemic oxygen delivery or exclude shock.","Tissue hypoperfusion can cause mottling and altered consciousness despite an acceptable saturation."),Lactate:a(i.plactate,"This is hyperlactatemia in a child with poor perfusion. Adrenergic stress and impaired clearance can contribute, so we follow the clinical response as well as the number.","Associated bedside findings of shock include delayed refill, oliguria and reduced interaction; those are actually documented here."),Glucose:a(i.glucose,"This is within the random reference toward its lower end. Poor intake and sepsis justify repeat monitoring, but this result does not establish hypoglycemia.","Hypoglycemia may cause sweating, pallor, irritability or seizures; none should be assumed from an in-range measurement."),"Venous pH":a(i.vpH,"This is acidemia. In this circulation-focused presentation, metabolic acidosis is likely; carbon dioxide and bicarbonate are needed to characterize the full acid-base disorder.","Poor perfusion with acidosis may produce tachypnea and lethargy, both seen in this child.")}},"sepsis-fluid-intolerance":{diagnosis:"Pneumococcal septic shock with myocardial dysfunction and evolving pulmonary edema",handoff:"EMS brings the child after fever, cough and progressive lethargy. At the referring department, focal left basal crackles and a synthetic radiology report of left lower-lobe consolidation suggest pneumonia. Initial antimicrobials and measured isotonic fluid have been delivered, but perfusion stays poor and the examination now adds bilateral crackles and a larger liver edge. We are presenting septic shock with impaired fluid tolerance, not simply unexplained hypotension.",course:"The team stops automatic fluid repetition, begins specialist-directed vasoactive support and escalates respiratory support while continuing antibiotics. Serial ultrasound is used to reassess cardiac function and pulmonary congestion alongside the examination. Perfusion and alertness improve with circulation support, and urine output resumes in the receiving unit. A later blood culture grows Streptococcus pneumoniae. Ventricular function recovers during treatment of infection in this synthetic course, supporting sepsis-associated myocardial dysfunction. The new bilateral crackles after resuscitation are tracked separately from the original focal pneumonia finding.",findings:{"Heart rate":a(z.hr,"This is tachycardia with weak pulses and confusion, indicating a strained circulation in the infectious context.","Poor cardiac output commonly adds cool skin, delayed refill and reduced urine output, rather than merely a rapid monitor rate."),"Blood pressure":a(z.bp,"This systolic value is below the nearby age-band reference. Hypotension now accompanies the clinical evidence of shock.","Hypotensive shock may produce confusion, weak pulses, cool extremities and oliguria; this child is already confused and poorly perfused."),"Respiratory rate":a(z.rr,"This is tachypnea. Both pneumonia and new pulmonary congestion can contribute to the increased work.","Associated signs include recession, crackles and increasing oxygen need; those evolving findings are why more fluid may be poorly tolerated."),"SpO\u2082":a(i.sat,"This is hypoxemia despite oxygen. New diffuse lung findings make fluid accumulation and worsening lung disease important considerations.","Hypoxemia may accompany agitation, cyanosis or fatigue; crackles and increased work are observed in this case."),Lactate:a(i.plactate,"This is substantial hyperlactatemia with shock. It supports urgency but does not specify that another fluid bolus is the correct intervention.","Poor perfusion commonly gives delayed refill, reduced urine and altered consciousness; trend those alongside lactate."),"Venous pH":a(i.vpH,"This is acidemia. Shock can cause metabolic acidosis, while respiratory failure may contribute; a complete gas and chemistry clarify the components.","Acidemia and shock may accompany tachypnea and reduced interaction; both are present."),Glucose:a(i.glucose,"This is within the random reference. It makes a major glucose disturbance an unlikely explanation for the confusion at this moment.","Glucose emergencies can cause sweating, altered behavior or seizures; continued surveillance remains appropriate during critical illness.")}},"bronchiolitis-feeding":{diagnosis:"Acute viral bronchiolitis with hypoxemia and inadequate oral intake",handoff:"The father calls EMS because the infant takes only brief feeds before pulling away to breathe. A sibling has a cold. The infant has diffuse bilateral findings and no focal asymmetry or choking history. The disease process is viral bronchiolitis; the specific virus is not identified because the initial management does not require that result.",course:"Oxygen and gentle nasal suction improve oxygenation, but feeding still produces distress. The team arranges hydration through a route selected by the pediatric service according to respiratory effort and aspiration risk rather than forcing oral feeds. Because effort persists, the infant is admitted and respiratory support is escalated as clinically indicated. In this synthetic course, breathing and feeding improve over two hospital days; the infant returns to adequate oral intake and maintains the pathway discharge saturation without supplemental oxygen. No bacterial pneumonia is diagnosed.",findings:{"Heart rate":a(Q.hr,"This is near the upper end of the nearby infant observation range. Work of breathing and reduced intake give it clinical context rather than proving shock from the pulse alone.","Dehydration may add dry mucosa, fewer wet diapers and delayed refill; the caregiver reports reduced diapers."),"Respiratory rate":a(Q.rr,"This is tachypnea beyond the nearby infant reference. Small-airway inflammation and secretions increase respiratory work.","Subcostal recession, nasal flaring and difficulty coordinating feeds are common associations; recession and feeding difficulty are present."),"SpO\u2082":a(i.sat,"This is persistent hypoxemia on room air. It is below usual oxygenation and below bronchiolitis oxygen-treatment thresholds.","Hypoxemia may cause pallor, restlessness or cyanosis, but visible color can remain deceptively reassuring."),Temperature:a(i.temp,"This is above the teaching interval but below 38 degrees. It fits a viral illness without establishing a bacterial source.","Fever may cause flushing or irritability; the clinical examination still determines whether an alternative infection needs investigation."),Glucose:a(i.glucose,"This is in the random reference. Feeding difficulty has not produced measured hypoglycemia at this time.","Hypoglycemia in an infant can cause jitteriness, lethargy or apnea, so reduced intake warrants continued reassessment."),"Other labs":a(j,"No result has been omitted from an otherwise completed routine panel: the panel was not clinically required at this stage.","Unexpected lethargy, shock, focal findings or recurrent apnea would create new questions and may justify testing.")}},"bronchiolitis-apnea":{diagnosis:"Viral bronchiolitis presenting with recurrent apnea in a young former preterm infant",handoff:"The mother calls EMS after congestion is followed by a pause in breathing and a dusky face. The crew witnesses another event and provides assisted breaths. The age is six weeks chronologically, only about term-equivalent after birth at thirty-four weeks. We call this bronchiolitis-associated apnea provisionally while urgently excluding sepsis and other causes; a mild interval examination cannot establish safety.",course:"Ventilation is supported immediately during each apnea, and the infant is admitted to intensive care with a reliable escalation plan. Because of young age and recurrent events, the receiving team obtains a sepsis evaluation and uses empiric antimicrobials while results are pending. A respiratory sample detects RSV, cultures remain negative, and no metabolic or structural neurological cause is found. In this synthetic course, repeated apnea requires invasive ventilatory support overnight, then resolves as the illness improves. The final diagnosis is RSV bronchiolitis with apnea, not an unexplained breathing theory.",findings:{"Heart rate during apnea":a(Te.hr,"This is bradycardia for the young infant and occurs during absent ventilation. Effective breaths are the immediate priority.","Hypoxic bradycardia may accompany limpness, pallor and reduced responsiveness; those event signs are present here."),"SpO\u2082 during apnea":a(i.sat,"This is severe desaturation during apnea, not the infant\u2019s usual baseline. The temporal link establishes an immediate oxygenation and ventilation problem.","Apneic infants may become dusky, limp or bradycardic, sometimes with only mild distress between episodes."),Temperature:a(i.temp,"This is at the lower edge of the teaching interval. An in-range temperature does not exclude invasive infection in a young infant.","Sepsis in this age group can cause apnea, poor feeding or lethargy with fever, low temperature or neither."),Glucose:a(i.glucose,"This is near the lower end of the random reference but not measured hypoglycemia by that interval. It does not explain away recurrent apnea.","Low glucose can cause jitteriness, poor feeding, lethargy or seizures; repeat assessment is appropriate in an infant with poor intake."),"Venous pH":a(i.vpH,"This is acidemia after the event. The elevated venous carbon dioxide supports a respiratory component from inadequate ventilation.","Ventilatory failure may produce lethargy, apnea and bradycardia; the event itself, not waiting for this gas, triggered support."),"Venous PCO\u2082":a(i.vco2,"This is elevated venous carbon dioxide, consistent with inadequate ventilation around the apneic episodes. It is not an arterial oxygen value.","Carbon dioxide retention may accompany depressed responsiveness and reduced effective breathing; both fit the observed event.")}},"croup-at-rest":{diagnosis:"Moderate viral croup with stridor at rest",handoff:"EMS finds the child upright on the mother\u2019s lap after a cold is followed by a barking cough overnight. The mother says the noisy inspiration continues even after crying stops. The child can swallow saliva and has no abrupt choking episode. This is a typical clinical croup presentation, caused by inflammatory narrowing below the vocal cords.",course:"The child remains with the caregiver, receives dexamethasone and nebulized epinephrine according to the pediatric pathway, and is reassessed without an unnecessary throat examination. Stridor resolves at rest and recession decreases. After the pathway observation period following the last epinephrine treatment, the child remains comfortable, drinks normally and has no recurrence at rest. In this synthetic outcome, discharge includes explicit return precautions for stridor at rest, increased effort, reduced interaction or poor intake. No neck film is obtained in this typical improving patient.",imaging:{ids:["peds-croup-steeple-2019"],narration:"On the visual slide, the real comparison film is a frontal neck radiograph from a different child. Follow the dark central air column upward from the upper chest. Immediately below the larynx it tapers into a narrow pointed column: the steeple sign, reflecting subglottic narrowing. A normal subglottic air column is wider. This sign supports croup but can be absent and does not grade severity reliably. For listeners, connect that narrowing to this child\u2019s barking cough, hoarse voice and inspiratory stridor. Our fictional child was treated clinically without an X-ray."},findings:{"Heart rate":a(X.hr,"This is toward the upper end of the broad unwell-child reference. Distress and the mildly raised temperature can contribute without establishing shock.","A distressed toddler may be frightened and tachycardic; poor perfusion would add weak pulses, delayed refill or altered interaction."),"Respiratory rate":a(X.rr,"The count is within this broad reference, yet stridor at rest and recession establish meaningful upper-airway obstruction.","Croup commonly adds a barking cough, hoarse voice and inspiratory stridor; these are already documented."),"SpO\u2082":a(i.sat,"This is within the usual oxygenation reference. Upper-airway obstruction can be important before desaturation develops.","Retractions and stridor at rest can precede cyanosis. A normal saturation does not make these findings mild."),Temperature:a(i.temp,"This is fever, consistent with the viral prodrome. The modest elevation does not itself identify the pathogen.","Viral croup commonly includes coryza and hoarseness. High fever with drooling or toxic appearance would broaden the differential."),"Blood tests":a(j,"This typical croup presentation is assessed clinically. No invented normal blood values are needed to complete the case.","Drooling, toxicity, poor response or altered consciousness would trigger reassessment for another airway disease.")}},"croup-exhaustion":{diagnosis:"Life-threatening croup with exhaustion and impending complete upper-airway obstruction",handoff:"EMS is called for a barking cough and stridor that has progressed through the evening. The father reports an earlier cold, then progressively deeper chest recession. There is no abrupt choking event. Initial corticosteroid and nebulized epinephrine at the referring department give only transient benefit. The child now has less audible stridor while becoming drowsy. Severe croup is the working diagnosis; poor response obliges us to consider epiglottitis, bacterial tracheitis and a foreign body while preparing rescue.",course:"The child stays in a position of comfort while the senior pediatric airway and ENT teams assemble with a shared rescue plan. Oxygen and temporizing nebulized epinephrine are given without delaying definitive support. In the controlled airway setting, intubation is required for exhaustion and poor air movement. The airway team documents marked subglottic edema, without an epiglottic swelling, foreign body or purulent tracheal secretions. Those later findings support severe croup as the final diagnosis in this synthetic case. The child receives continued corticosteroid treatment, improves in intensive care and is extubated after the airway swelling settles. The quieter stridor before intubation was loss of airflow, whereas the quiet breathing after recovery accompanies normal interaction and effective air movement.",imaging:{ids:["peds-croup-steeple-2019","peds-epiglottitis-thumb-2026"],narration:"Two real comparison films explain the anatomical differential, not studies obtained from our unstable fictional child. On the frontal croup film, the dark subglottic air column narrows into the steeple sign below the larynx. On the lateral epiglottitis film, the original arrow identifies a swollen rounded epiglottis: the thumb sign. A normal epiglottis is a thin curved structure. Epiglottitis more often brings painful swallowing, drooling and a muffled voice rather than the classic barking cough. These signs can overlap; no film is required before rescuing a threatened airway. Our case ultimately demonstrates subglottic edema from croup, not epiglottitis."},findings:{"Heart rate":a(J.hr,"This is tachycardia above the nearby toddler reference. With exhaustion and hypoxemia it indicates severe physiological stress.","A failing upper airway may cause agitation followed by drowsiness, poor chest movement and eventually bradycardia."),"Respiratory rate":a(J.rr,"The count falls inside the nearby range, but the reduced effort, drowsiness and poor air movement make it inadequate. We do not call it recovery or diagnose bradypnea from the number alone.","Impending failure may produce softer stridor, less chest movement, fatigue and altered consciousness; all accompany the change here."),"SpO\u2082":a(i.sat,"This is severe hypoxemia despite oxygen, a late danger sign in upper-airway obstruction.","Associated signs can include cyanosis, agitation and then reduced consciousness; drowsiness is already documented."),"Blood tests":a(j,"Sampling is deliberately deferred while the airway fails. The absence of results must not delay rescue or imply that laboratory values are normal.","The observed reduced airflow, exhaustion and altered interaction are sufficient to trigger emergency airway escalation.")}}};var v="Tachycardia may accompany pain, anxiety or reduced circulating volume; weak pulses, cool skin and oliguria would add evidence of poor perfusion.",w="Hypoxemia can cause restlessness, tachycardia or cyanosis; oxygen saturation alone does not measure perfusion or cardiac output.",T="Thrombocytopenia may cause petechiae, bruising or mucosal bleeding, but significant depletion can exist without visible bleeding.",W="Liver injury in this setting may accompany right upper quadrant pain, nausea or malaise; severe escalating pain warrants evaluation for hepatic complications.",y="Hemorrhagic shock commonly causes pallor, diaphoresis, weak pulses, confusion and reduced urine output; external blood loss may underestimate total loss.",ee={"preeclampsia-visual-symptoms":{diagnosis:"Preeclampsia with severe features at 33 weeks",handoff:"EMS brings the patient from home after a persistent headache is joined by flashing lights. The partner says these symptoms are new, and prenatal records show no chronic hypertension. The repeat pressure and organ-injury pattern establish the conference diagnosis early: preeclampsia with severe features, before any seizure occurs.",course:"The obstetric team treats persistent severe hypertension with a pathway-selected antihypertensive and gives magnesium for seizure prophylaxis as a separate intervention. Respiratory rate, reflexes, urine output and infusion delivery are monitored. After maternal stabilization, the obstetric team recommends delivery because of the severe maternal disease; gestational age, symptoms and fetal assessment inform its timing and route. In this synthetic course, mother and infant receive inpatient care and the mother leaves hospital with pressure follow-up and postpartum warning signs. Better headache alone does not mean the disease has resolved.",findings:{"Heart rate":a(i.hrAdult,"This is mild tachycardia against the nonpregnant resting reference. Pregnancy and distress may contribute; it is not the criterion establishing severe preeclampsia.",v),"Blood pressure":a(i.bpOb,"Both components are in the severe range and remain severe on repeat. This requires urgent treatment rather than waiting for proteinuria or a seizure.","Severe preeclampsia may cause headache, visual symptoms, hyperreflexia, epigastric pain or pulmonary edema; headache and visual disturbance are present."),"SpO\u2082":a(i.sat,"This is within the usual reference, and the lungs are currently clear. There is no documented hypoxemia at this assessment.",w),"Fetal heart rate":a(i.fetal,"This spot rate is in the usual baseline interval. It cannot establish a normal full tracing or override the maternal emergency.","Fetal compromise can appear through recurrent decelerations or abnormal variability even when a single rate is in range."),Platelets:a(i.platelets,"This is thrombocytopenia, but above the below-100 severe-feature threshold. Its trend matters, and other severe features are already present.",T),AST:a(i.ast,"This is more than twice the stated upper reference limit, supporting hepatic involvement in the setting of severe hypertension.",W),Creatinine:a(i.creatinine,"This exceeds the obstetric 1.1 criterion even though it sits at the upper end of a general adult interval. Gestational physiology changes its meaning.","Renal involvement may produce oliguria or fluid accumulation; monitor urine output and magnesium clearance rather than assuming symptoms must be present.")}},"eclampsia-postpartum":{diagnosis:"Delayed postpartum eclampsia",handoff:"A partner calls EMS after headache and flashing lights are followed by a generalized convulsion. The baby was delivered five days earlier, and the family initially omits that history because the pregnancy is over. EMS protects the patient from injury and finds severe hypertension after the seizure. The working diagnosis is postpartum eclampsia while intracranial hemorrhage and venous thrombosis remain active alternatives.",course:"After the initial seizure ends, magnesium is given to treat eclampsia and prevent recurrence, with airway and ventilation support as needed. Persistent severe pressure receives a separate antihypertensive. Ongoing confusion prompts brain imaging after stabilization; in this synthetic course, no hemorrhage or venous thrombosis is found. Consciousness returns, no further seizure occurs during monitored treatment, and the patient is admitted with obstetric and neurological follow-up. Delivery did not end the period of risk.",findings:{"Heart rate":a(i.hrAdult,"This is tachycardia after a seizure. Adrenergic stress is plausible, but perfusion and rhythm are reassessed rather than attributed automatically to the postictal state.",v),"Blood pressure":a(i.bpOb,"Both components are severe, including in this postpartum setting. The pressure raises the risks of stroke and further neurological injury.","Headache, visual symptoms, seizures and altered consciousness can accompany hypertensive obstetric disease; the first three preceded this assessment."),"Respiratory rate":a(i.rrAdult,"This is tachypnea after the seizure. Assess airway patency, aspiration risk and ventilation rather than assuming every postictal patient ventilates effectively.","Seizures may be followed by obstruction, hypoventilation or aspiration; gurgling, poor chest movement or new crackles would be important."),"SpO\u2082":a(i.sat,"This is below the usual oxygenation reference on room air. Seizure-associated hypoventilation or aspiration may contribute and need reassessment.",w),Glucose:a(i.glucose,"This random value is in range. Measured hypoglycemia is not the explanation for this seizure.","Hypoglycemia may cause sweating, confusion or convulsions, which is why a bedside glucose is checked promptly."),Platelets:a(i.platelets,"This count is in the adult reference. A normal count does not exclude eclampsia or remove the need to treat the seizure and hypertension.",T),Creatinine:a(i.creatinine,"This is within the general adult interval and below the stated obstetric severe-feature cutoff. Its postpartum trend and urine output still matter.","Renal dysfunction can reduce magnesium clearance, producing reduced reflexes and respiratory depression during excess exposure; monitor clinically and by the pathway.")}},"hellp-epigastric-pain":{diagnosis:"HELLP syndrome with severe systolic hypertension",handoff:"EMS is called because presumed indigestion becomes persistent right upper quadrant pain and vomiting. The patient is late in pregnancy, has no known liver disease and has not had trauma. The laboratory pattern turns the complaint into a specific obstetric emergency: hemolysis, elevated liver enzymes and low platelets.",course:"The team treats the severe systolic pressure, gives indicated magnesium and arranges urgent delivery after maternal stabilization with obstetric, anesthesia and blood-bank support. Serial blood counts and coagulation studies guide hemorrhage preparation. In this synthetic course, platelet count initially falls further after delivery before recovering with clinical stabilization; liver tests then improve. Persistent or escalating pain would require evaluation for hepatic hematoma or rupture rather than attributing it to routine HELLP discomfort.",findings:{"Heart rate":a(i.hrAdult,"This is tachycardia. Pain and systemic illness can contribute; absence of external bleeding does not exclude a developing complication.",v),"Blood pressure":a(i.bpOb,"The systolic component alone meets the severe threshold. A diastolic value below 110 does not make this nonsevere.","Headache, visual disturbance, seizures or epigastric pain may accompany severe disease; abdominal pain is the presenting feature here."),"SpO\u2082":a(i.sat,"This is in the usual oxygenation interval; it does not exclude major hematologic or hepatic disease.",w),"Fetal heart rate":a(i.fetal,"This is in the baseline interval at this assessment. Maternal stabilization and ongoing fetal monitoring remain necessary.","Recurrent decelerations or abnormal variability would add concern even before a sustained abnormal baseline develops."),Platelets:a(i.platelets,"This is marked thrombocytopenia, below 100 and consistent with the low-platelet component of HELLP.",T),AST:a(i.ast,"This is substantially elevated, indicating hepatocellular injury in the right clinical setting.",W),LDH:a(i.ldh,"This is markedly elevated and exceeds the HELLP-supporting threshold. LDH is nonspecific, but schistocytes add evidence of microangiopathic hemolysis.","Hemolysis may produce pallor, jaundice or dark urine; their absence would not negate the laboratory pattern."),Smear:a(d("A normal smear does not contain a pathological excess of fragmented red cells.","lab"),"Schistocytes are red-cell fragments, supporting microangiopathic hemolysis when interpreted with the platelet and enzyme findings.","Hemolysis can accompany fatigue, pallor and jaundice; the smear supplies evidence even before these become prominent.")}},"hellp-without-severe-bp":{diagnosis:"Postpartum HELLP syndrome with nonsevere hypertension",handoff:"The bedside nurse requests review because upper abdominal pain and profound malaise persist after delivery. Petechiae appear at recent puncture sites. The pressure is only mildly elevated, but it does not explain or dismiss the severe platelet and hemolysis abnormalities. This conference concerns postpartum HELLP, not routine postoperative discomfort.",course:"Obstetrics and critical care repeat blood counts, liver and coagulation tests, assess for bleeding and consider the broader postpartum thrombotic microangiopathy differential. Blood-bank and anesthesia teams are involved according to procedural and bleeding needs. The synthetic course shows no focal hepatic hemorrhage; the platelet count and hemolysis markers recover over the next several days with specialist management. Failure to improve would trigger reassessment for conditions such as TTP or complement-mediated hemolytic uremic syndrome rather than preserving the HELLP label at all costs.",findings:{"Heart rate":a(i.hrAdult,"This is mild tachycardia, consistent with pain or systemic illness and worth trending with bleeding and perfusion findings.",v),"Blood pressure":a(i.bpOb,"This is hypertension but does not meet the severe threshold. HELLP can still be severe despite this pressure.","Abdominal pain, malaise, nausea and bruising can be the dominant presentation without extreme hypertension."),"SpO\u2082":a(i.sat,"This is normal measured oxygenation. It does not reduce the urgency of hemolysis and severe thrombocytopenia.",w),Platelets:a(i.platelets,"This is severe thrombocytopenia, matching the petechiae and creating bleeding and procedural concerns.",T),AST:a(i.ast,"This is markedly elevated AST, supporting hepatic injury rather than isolated postpartum discomfort.",W),LDH:a(i.ldh,"This is markedly elevated. Alongside low haptoglobin it supports hemolysis, while other causes of tissue injury must still be considered.","Hemolysis may cause fatigue, pallor, jaundice or dark urine; pallor and malaise are observed."),Haptoglobin:a(d("Haptoglobin is normally detectable within an assay-specific interval; no universal qualitative normal number is supplied here.","lab"),"A low result supports consumption as haptoglobin binds free hemoglobin during intravascular hemolysis. Liver disease and other causes can also lower it.","Hemolysis may cause pallor, jaundice and dark urine; interpret this qualitative result alongside LDH, smear and the blood count.")}},"pph-boggy-uterus":{diagnosis:"Primary postpartum hemorrhage from uterine atony with hemorrhagic shock",handoff:"The midwife reports a term vaginal birth followed by a quantified loss of twelve hundred milliliters that is still increasing. The uterus is large and boggy. The patient becomes pale and lightheaded. The disease process is uterine atony causing primary postpartum hemorrhage, with shock established clinically rather than by the first hemoglobin.",course:"The team activates the obstetric hemorrhage response, performs uterine massage and gives uterotonics selected around contraindications, early tranexamic acid and resuscitation with blood products as indicated. Access, warming and repeated coagulation assessment proceed together. Persistent atony in this synthetic case requires uterine balloon tamponade in the receiving obstetric unit. Bleeding then slows, circulation improves and serial laboratory results guide further replacement. A firming uterus plus falling blood loss and improved perfusion are the response measures; a single early hemoglobin is not.",findings:{"Heart rate":a(i.hrAdult,"This is marked tachycardia in ongoing hemorrhage, consistent with compensatory sympathetic activation.",y),"Blood pressure":a(i.bpAdult,"This is hypotension accompanying ongoing blood loss. The patient has hemorrhagic shock, not simply an expected postpartum pressure change.",y),"Respiratory rate":a(i.rrAdult,"This is tachypnea. Shock and metabolic stress can increase breathing even while saturation remains acceptable.","Poor oxygen delivery may produce rapid breathing, pallor and altered interaction without primary lung disease."),"SpO\u2082":a(i.sat,"This is in the usual reference. It describes hemoglobin saturation, not how much hemoglobin or blood flow remains available.",y),Hemoglobin:a(i.hemoglobin,"This value is low against the nonpregnant reference, but an early sample can still substantially underrepresent the scale of acute hemorrhage. Do not wait for it to fall before resuscitating.","Acute anemia and hypovolemia may cause pallor, dizziness, tachycardia and syncope; symptoms depend on rate and volume of loss."),Fibrinogen:a(i.fibrinogen,"This is below 200 and especially concerning after a term birth. Consumption and dilution can rapidly compromise clot formation.","Low fibrinogen may accompany persistent bleeding or diffuse oozing; product replacement follows the hemorrhage protocol and repeated tests."),Lactate:a(i.lactate,"This is hyperlactatemia in hemorrhagic shock, supporting impaired tissue perfusion without quantifying total blood loss.",y)}},"pph-firm-uterus":{diagnosis:"Primary postpartum hemorrhage from a cervical laceration with evolving coagulopathy",handoff:"Following an instrument-assisted birth, the team reports more than fifteen hundred milliliters of continued blood loss despite a firm uterus. The placenta appears complete. This shifts the working source from uterine atony toward genital-tract trauma while other causes remain under review.",course:"The hemorrhage team gives resuscitation, early tranexamic acid, warming and indicated blood and coagulation products while an obstetric clinician examines for trauma in a controlled setting. A bleeding cervical laceration is found and repaired in this synthetic case. The uterus remains firm. Hemorrhage decreases after repair and correction of coagulopathy, linking the treatment response to the actual source. Continuing to give uterotonics alone would have failed to repair the laceration.",findings:{"Heart rate":a(i.hrAdult,"This is marked tachycardia with ongoing blood loss and hypotension.",y),"Blood pressure":a(i.bpAdult,"This is severe hypotension in the hemorrhage context and requires simultaneous resuscitation and source control.",y),Temperature:a(i.temp,"This is hypothermia. Blood loss, exposure and unwarmed resuscitation can lower temperature and worsen coagulation.","Cold skin, shivering or reduced alertness may accompany hypothermia; active warming is part of hemorrhage care."),Hemoglobin:a(i.hemoglobin,"This is anemia, consistent with substantial blood loss, while the ongoing clinical state still drives urgency.","Anemia may produce pallor, dyspnea, dizziness or syncope; acute volume loss adds weak pulses and hypotension."),Fibrinogen:a(i.fibrinogen,"This is well below the hemorrhage replacement threshold, indicating inadequate fibrinogen for reliable clot formation in this context.","Diffuse oozing or persistent wound bleeding may accompany coagulopathy; the laceration still needs direct repair."),Platelets:a(i.platelets,"This is thrombocytopenia in active hemorrhage. Consumption and dilution are possibilities; it is not by itself proof of HELLP.",T)}},"abruption-concealed":{diagnosis:"Concealed placental abruption with maternal hemorrhagic shock and fetal compromise",handoff:"EMS finds sudden abdominal pain, a continuously firm tender uterus and reduced fetal movement. Only a little dark blood is seen externally. The obstetric diagnosis is suspected concealed abruption; the shock examination and fetal compromise are the reasons to act before a confirmatory scan.",course:"Maternal hemorrhage resuscitation and urgent obstetric delivery preparation proceed together, with blood-bank support and repeated coagulation studies. At emergency delivery in this synthetic course, a large retroplacental clot and placental separation confirm the abruption. The newborn requires resuscitation and neonatal admission, while the mother requires continued blood-product and coagulation support. Maternal circulation stabilizes after delivery and hemorrhage control. The outcome makes clear where the missing visible blood had been concealed.",findings:{"Heart rate":a(i.hrAdult,"This is tachycardia with pallor, diaphoresis and weak pulses, supporting a hemorrhagic shock pattern.",y),"Blood pressure":a(i.bpAdult,"The systolic pressure is close to the lower resting reference and the diastolic below it. With the examination this is inadequate reassurance; the diagnosis of shock does not require crossing a single pressure cutoff.",y),"Fetal heart rate":a(i.fetal,"This is persistent fetal bradycardia, concerning for fetal compromise in the setting of placental separation.","Reduced fetal movement and a sustained abnormal rate may accompany impaired placental oxygen delivery; interpretation requires the full tracing and urgent obstetric assessment."),Hemoglobin:a(i.hemoglobin,"This is reduced against the nonpregnant reference, but it does not quantify acute concealed hemorrhage. A near-baseline result would not exclude major bleeding.",y),Fibrinogen:a(i.fibrinogen,"This is markedly concerning in late pregnancy and suggests consumption in the abruption context. The postpartum replacement threshold is a comparison, not a normal antepartum target.","Consumptive coagulopathy may produce ongoing bleeding or oozing from access sites; repeated coagulation assessment is needed."),Platelets:a(i.platelets,"This is thrombocytopenia, consistent with possible consumption during severe abruption, though the whole coagulation picture is required.",T)}},"abruption-trauma":{diagnosis:"Trauma-associated placental abruption with evolving fetal compromise",handoff:"The patient was restrained in a motor vehicle collision and initially walked at the scene. During EMS assessment, uterine pain and frequent contractions develop. The referring monitor shows recurrent fetal decelerations. A low-speed mechanism does not establish that placental attachment remains intact.",course:"Maternal trauma assessment proceeds alongside continuous obstetric monitoring. An initial scan does not show a large retroplacental collection, which does not exclude abruption. In the receiving center, recurrent fetal abnormalities persist and urgent delivery is undertaken. A retroplacental clot confirms partial placental separation in this synthetic case. Maternal pressure stays preserved and no major nonobstetric injury is found; the newborn needs neonatal support. The lesson is a specific placental injury with an initially compensated mother.",findings:{"Heart rate":a(i.hrAdult,"This is mild tachycardia. Pain, anxiety and pregnancy may contribute, but bleeding and evolving maternal injury must still be assessed.",v),"Blood pressure":a(i.bpAdult,"This pressure is in the usual resting adult interval. It does not exclude placental injury or early concealed bleeding.",y),"Fetal heart rate":a(i.fetal,"A baseline near 170 is fetal tachycardia if sustained, and recurrent decelerations independently add concern. A single spot rate cannot characterize the full tracing.","Placental compromise may cause recurrent decelerations, altered variability and reduced movement; the recurrent decelerations are documented here."),Hemoglobin:a(i.hemoglobin,"This is slightly below the nonpregnant reference and can occur with pregnancy dilution. It is not a reliable early exclusion test for acute blood loss.","Major hemorrhage may first show tachycardia, weakness or reduced perfusion before a large measured hemoglobin fall."),Fibrinogen:a(i.fibrinogen,"This exceeds the postpartum 200 replacement threshold but may still be concerning relative to expected late-pregnancy elevation, especially if falling. It neither confirms nor excludes abruption.","A developing coagulopathy may later cause persistent bleeding or oozing; trend the value with the uterine and fetal findings.")}},"ppcm-cannot-lie-flat":{diagnosis:"Peripartum cardiomyopathy presenting with acute systolic heart failure and pulmonary edema",sources:[I.ef],imaging:{ids:["cxr-flash-edema-portable-2026"],narration:"The real comparison chest film comes from a different patient with flash pulmonary edema after a pacing problem, not a postpartum patient. Hazy bilateral perihilar and lower-zone opacities illustrate airspace fluid; a normally aerated lung is more lucent. The device and leads belong to that reference patient. This image teaches the edema pattern, not the cause of our patient\u2019s cardiomyopathy. Etiology comes from postpartum timing, echocardiography and exclusion of alternatives."},handoff:"EMS finds a mother sleeping upright because lying down produces breathlessness. She reports that ankle swelling and fatigue were initially called normal postpartum recovery, but breathlessness now interrupts conversation and routine infant care. The diagnosis is heart failure associated with peripartum cardiomyopathy after competing causes are evaluated.",course:"Oxygen, appropriately selected noninvasive respiratory support and intravenous diuresis improve congestion under cardiology and obstetric supervision. The ejection fraction of 28 percent represents substantial systolic dysfunction; a usual adult value is about 55 to 70 percent. This explains the orthopnea and pulmonary edema, while etiology still requires evaluation. The synthetic workup finds no pulmonary embolism, acute coronary cause or preexisting structural disease. A postpartum heart-failure plan accounts for lactation, medications and follow-up echocardiography. Breathing improves during admission, but ventricular recovery is not assumed from symptom relief.",findings:{"Heart rate":a(i.hrAdult,"This is tachycardia in a congested patient and may be compensating for reduced stroke volume.",v),"Blood pressure":a(i.bpAdult,"This is preserved pressure. Systolic heart failure and pulmonary edema can occur without hypotension.","Congestion commonly produces orthopnea, elevated neck veins, crackles and edema; all are documented here."),"Respiratory rate":a(i.rrAdult,"This is tachypnea. Pulmonary congestion increases respiratory work and impairs gas exchange.","Heart-failure respiratory distress may produce orthopnea, crackles and accessory-muscle use; orthopnea and crackles are present."),"SpO\u2082":a(i.sat,"This is hypoxemia on room air in the setting of pulmonary edema.",w),BNP:a(d("BNP interpretation depends on the assay and clinical setting. This BNP assay lists 0 to 100 picograms per milliliter as its reference; that is not a universal pregnancy reference or a stand-alone diagnosis.","bnp"),"This is markedly elevated and supports cardiac wall stress. It does not diagnose peripartum cardiomyopathy by itself.","Heart failure may cause orthopnea, neck-vein distension, edema and crackles; the echocardiogram and full evaluation connect the biomarker to this case."),Creatinine:a(i.creatinine,"This is within the general adult reference near its upper end. At three weeks postpartum, trend and prior renal function matter more than treating a pregnancy threshold as an automatic diagnosis.","Renal congestion or low perfusion can cause oliguria and rising creatinine during heart failure; monitor response to diuresis.")}},"ppcm-shock":{diagnosis:"Peripartum cardiomyopathy complicated by cardiogenic shock and pulmonary edema",imaging:{ids:["cxr-flash-edema-portable-2026"],narration:"The real comparison chest film comes from a different patient with flash pulmonary edema after a pacing problem, not a postpartum patient. Hazy bilateral perihilar and lower-zone opacities illustrate airspace fluid; a normally aerated lung is more lucent. The device and leads belong to that reference patient. This image teaches the edema pattern, not the cause of our patient\u2019s cardiomyopathy. Etiology comes from postpartum timing, echocardiography and exclusion of alternatives."},handoff:"The partner calls EMS because severe postpartum breathlessness is followed by confusion and very little urine. The patient is cool despite wet lungs and elevated neck veins. The small fluid intervention has not improved perfusion. This is a low-output congested shock presentation requiring cardiac as well as obstetric expertise.",course:"A shock team coordinates vasoactive and inotropic support, respiratory escalation and transfer to a center capable of mechanical circulatory support. Specialist echocardiography shows severe global left-ventricular dysfunction; evaluation does not identify acute infarction, pulmonary embolism or a prior cardiomyopathy. Those findings establish peripartum cardiomyopathy in this synthetic case. Circulation remains inadequate despite initial support, so temporary mechanical circulatory support is used in the receiving unit. Over subsequent days perfusion, urine output and lactate improve. Long-term cardiac recovery remains uncertain and requires serial imaging; stabilization is the reported outcome, not a promise of a normal heart.",findings:{"Heart rate":a(i.hrAdult,"This is marked tachycardia with weak pulses, consistent with a stressed low-output circulation.",v),"Blood pressure":a(i.bpAdult,"This is severe hypotension with congestion and poor perfusion, supporting cardiogenic shock rather than isolated postpartum fluid retention.","Low output may produce cool clammy skin, confusion, weak pulses and oliguria; all are present in this case."),"Respiratory rate":a(i.rrAdult,"This is marked tachypnea. Pulmonary edema and metabolic stress from shock can both increase the drive to breathe.","Crackles, orthopnea, recession or inability to speak comfortably can accompany pulmonary edema; respiratory fatigue requires escalation."),"SpO\u2082":a(i.sat,"This is persistent hypoxemia despite oxygen in a congested patient. Respiratory escalation must account for its effect on blood pressure.",w),Lactate:a(i.lactate,"This is hyperlactatemia in a clinically low-output state. It supports the perfusion assessment but is followed with examination and urine output.","Shock may cause confusion, cool skin and oliguria; these are documented rather than inferred from lactate alone."),Creatinine:a(i.creatinine,"This exceeds the general adult reference and suggests renal impairment in the shock context; baseline and serial results are needed to define acute injury.","Renal hypoperfusion and congestion can produce scant urine and fluid accumulation; scant urine is part of this presentation.")}}};var xe=d("After forty-eight to seventy-two hours, the Pediatric Endocrine Society identifies glucose below 60 milligrams per deciliter as hypoglycemia. Early transitional newborn thresholds are different.","newbornGlucose"),te=d("Glucose targets depend on postnatal age and risk. The Pediatric Endocrine Society suggests maintaining above 50 milligrams per deciliter during the first forty-eight hours in high-risk infants without a suspected congenital disorder; neonatal pathways can use different operational thresholds.","newbornGlucose"),ae={"duct-systemic-shock":{diagnosis:"Critical coarctation of the aorta with duct-dependent systemic circulation and shock",handoff:"The parents call EMS because feeding has deteriorated and the newborn has become gray with very few wet diapers. The infant went home without a known cardiac diagnosis. EMS reports cooler legs and weaker femoral than arm pulses. The initial working problem is neonatal shock with suspected duct-dependent systemic blood flow; the final anatomical diagnosis will come from echocardiography.",course:"Neonatal and cardiac teams direct prostaglandin to maintain ductal patency while preparing for apnea, supporting ventilation and treating possible sepsis in parallel. Expert echocardiography shows critical coarctation with a constricting ductus and impaired systemic output. As ductal flow improves, leg perfusion and urine output recover and lactate falls. Cultures remain negative in this synthetic course, and the infant proceeds to cardiac repair after stabilization. The final diagnosis is critical coarctation, not an unspecified circulation theory.",findings:{"Heart rate":a(i.newbornHR,"This is tachycardia beyond the term-newborn observation range and accompanies poor systemic perfusion.","Neonatal shock may cause poor feeding, mottling, cool limbs, weak pulses and lethargy; several are present."),"Right-arm pressure":a(i.newbornBP,"The right-arm systolic pressure is within the term reference. It does not establish that the lower body receives adequate blood flow.","Coarctation may produce stronger arm than femoral pulses and cooler legs, as found here."),"Leg pressure":a(i.newbornBP,"This leg systolic pressure is low and substantially below the arm value. Correct cuff size and repeated measurements are essential before interpreting the gradient.","Weak femoral pulses, cool legs and poor urine output strengthen the concern for impaired descending aortic flow."),"Respiratory rate":a(i.newbornRR,"This is tachypnea. Shock and acidosis can drive rapid breathing without a primary lung disorder.","Poor feeding, grunting or recession can accompany neonatal cardiac failure or sepsis; the complete examination is needed."),"Preductal SpO\u2082":a(d("A term infant beyond immediate transition usually has oxygen saturation in the mid to high nineties without cyanotic heart disease. Screening and disease-specific treatment targets are separate questions.","newborn"),"This right-hand saturation is not profoundly low, but oxygenated blood in the upper body does not prove adequate systemic flow to the kidneys and legs.","A duct-dependent systemic lesion can present with gray color, shock and weak femorals rather than striking central cyanosis."),"Venous pH":a(i.vpH,"This is substantial venous acidemia. With shock and elevated lactate, a metabolic component is likely; full chemistry and carbon dioxide define the complete disorder.","Acidotic shock may present with rapid breathing, poor responsiveness and poor feeding; those findings are documented."),Lactate:a(d("For a plasma lactic-acid assay, this laboratory lists 1.1 to 4.4 millimoles per liter from three to ten days of age. Neonatal ranges differ from adult whole-blood ranges.","neonatalLactate"),"This is elevated even against the age-specific reference and supports concern for poor systemic perfusion in context.","Poor perfusion may cause gray color, weak femoral pulses, cold limbs and oliguria; lactate alone cannot identify coarctation."),Glucose:a(xe,"This is low for an infant six days old and requires correction and repeat monitoring alongside shock care. It is not treated as normal early transition.","Hypoglycemia can cause poor feeding, jitteriness, lethargy, apnea or seizures; lethargy has multiple possible causes here.")}},"duct-cyanotic-newborn":{diagnosis:"Pulmonary atresia with intact ventricular septum and duct-dependent pulmonary blood flow",handoff:"The parent calls EMS because the infant\u2019s lips and tongue stay blue despite warming and supplemental oxygen. There is little wheeze or focal chest asymmetry. The initial working diagnosis is cyanotic congenital heart disease while lung disease, pulmonary hypertension and infection are evaluated. Echocardiography, not skin color alone, will identify the anatomy.",course:"Neonatal cardiology directs prostaglandin and a transport plan with ventilation support immediately available. Echocardiography identifies pulmonary atresia with an intact ventricular septum and duct-dependent pulmonary flow. Oxygen goals are then set for that lesion rather than forcing a generic healthy-newborn target. In this synthetic course, ductal support improves pulmonary flow and cyanosis, and the infant reaches a cardiac center for definitive intervention planning. The final diagnosis explains why oxygen alone did not correct the problem.",findings:{"Heart rate":a(i.newbornHR,"This rate is within the term-newborn reference. An acceptable heart rate does not exclude severe cyanotic heart disease.","Central cyanosis, poor feeding and low oxygen response can coexist with a rate in range."),"Respiratory rate":a(i.newbornRR,"The count is within the term reference. Modest visible respiratory effort with profound hypoxemia increases concern for a circulatory shunt or flow problem.","Cyanotic heart disease may cause blue tongue and lips with relatively little recession; lung disease remains in the differential."),"Preductal SpO\u2082":a(i.sat,"This is severe right-hand desaturation despite oxygen in a term infant well beyond the first minutes after birth. A later lesion-specific goal does not make the initial unexplained hypoxemia benign.","Central cyanosis and poor feeding are common associated signs and are present in this infant."),"Postductal SpO\u2082":a(i.sat,"This foot reading is also severely low. A small difference from the hand does not exclude structural heart disease.","Color change, lethargy and feeding intolerance can accompany reduced systemic oxygen delivery; the gradient alone does not establish anatomy."),"Arterial pH":a(i.npH,"This is arterial acidemia against the newborn reference, indicating physiological compromise in addition to cyanosis.","Poor oxygen delivery may cause lethargy, poor feeding and rapid breathing; acid-base components need the complete gas."),"PaO\u2082":a(i.npo2,"This is severe arterial hypoxemia despite oxygen. Limited pulmonary blood flow is one possible mechanism until the echo is obtained.","Central cyanosis can accompany such hypoxemia, but pulse oximetry and arterial measurement supply more reliable evidence than color alone."),Lactate:a(d("For plasma lactic acid, this laboratory lists 1.1 to 6.7 millimoles per liter from birth to three days and 1.1 to 4.4 from three to ten days. Exact age and assay matter at this boundary.","neonatalLactate"),"This result is within both cited neonatal age intervals. It is not labeled adult-style hyperlactatemia; a single in-range value does not cancel profound hypoxemia.","Poor tissue delivery may later produce oliguria, lethargy and a rising lactate; follow those trends while defining the lesion.")}},"rds-grunting-newborn":{diagnosis:"Surfactant-deficiency respiratory distress syndrome in a 30-week preterm newborn",imaging:{ids:["peds-irds-preterm-haggstrom"],narration:"This real comparison radiograph is from a different twenty-nine-week infant. The lungs have low volume with diffuse fine granular opacity and air bronchograms: dark air-filled bronchi stand out against poorly aerated lung. A normally aerated neonatal chest is more lucent, without this diffuse granular pattern. For listeners, connect the poorly expanded lungs to surfactant deficiency, low compliance, grunting and retractions. The comparison illustrates the fictional radiology report; it is not a scan of our synthetic newborn."},handoff:"The delivery team requests neonatal transport after persistent grunting and increasing support requirements follow a preterm birth. The infant continues to breathe spontaneously but has visible retractions. The synthetic radiology report supports surfactant-deficiency RDS, while early infection remains a competing cause assessed through the perinatal history and neonatal pathway.",course:"The neonatal team maintains warmth, checks the CPAP interface and pressure delivery, and titrates oxygen to the post-stabilization target. Persistent oxygen need and respiratory distress lead to surfactant treatment using the receiving unit\u2019s neonatal strategy. A real comparison film on the slide comes from a different infant: low lung volumes, fine granular opacity and air bronchograms illustrate poorly expanded surfactant-deficient lung units. In this synthetic course, effort and oxygen need decrease after treatment. Temperature of 36.7 is within the neonatal goal, unlike the initial 36.1. The infant remains in neonatal intensive care for ongoing prematurity and respiratory management.",findings:{"Heart rate":a(i.newbornHR,"This is within the broad term-newborn reference, used only as a nearby observation comparison for a preterm infant. It does not exclude significant lung disease.","RDS can cause grunting, retractions and increasing oxygen need even with an initially acceptable heart rate."),"Respiratory rate":a(i.newbornRR,"This is tachypnea with grunting and reduced air entry, consistent with increased work from low-compliance lungs.","Surfactant deficiency commonly produces recession, nasal flaring, expiratory grunting and cyanosis; grunting and recession are observed."),"SpO\u2082":a(i.pretermSat,"At twenty-five minutes, this is below the post-stabilization target. Check the probe, support delivery and trend rather than applying a first-minute transition target.","Inadequate oxygenation may cause cyanosis or bradycardia; rising effort and oxygen requirement can precede those late signs."),Temperature:a(i.newbornTemp,"This is below the neonatal temperature goal. Heat loss increases metabolic and oxygen demands in an already stressed preterm infant.","Cold stress may cause cool skin, hypoglycemia, increased respiratory distress or lethargy, sometimes without obvious shivering."),"Arterial pH":a(i.npH,"This is arterial acidemia against the newborn reference. Ventilatory impairment contributes, but the complete gas and perfusion assessment determine whether there is a mixed disorder.","Acidemia may accompany poor respiratory effort and cardiovascular instability; assess the infant, not only the gas."),"PaCO\u2082":a(i.pco2,"This is raised against the pediatric laboratory reference. It reflects reduced carbon dioxide clearance, while acceptable ventilator targets in preterm care are individualized.","Retractions, grunting and later fatigue may accompany inadequate ventilation; a gas alone does not mandate a single ventilator setting."),Glucose:a(te,"This exceeds the cited early high-risk maintenance target. It is not measured hypoglycemia, but preterm energy reserves are limited and cold stress increases demand.","Low glucose can cause jitteriness, apnea, poor feeding or lethargy; surveillance continues during stabilization.")}},"rds-sudden-desaturation":{diagnosis:"Displaced endotracheal tube causing acute ventilation failure in a preterm infant with RDS",handoff:"During movement from the warmer to the transport incubator, an infant intubated for surfactant-deficiency RDS suddenly loses chest excursion and the carbon dioxide waveform. The crew reports the tube marking has changed at the lip. This is an acute equipment and airway event superimposed on a known lung disease, not simply worsening RDS.",course:"The team calls for help, checks the circuit and tube, and finds that the endotracheal tube has displaced. Ineffective tube ventilation is stopped and effective mask ventilation is established immediately while an experienced neonatal airway clinician restores the airway. Chest movement, bilateral air entry and sustained exhaled carbon dioxide confirm ventilation. The heart rate returns to its prior baseline and saturation returns to the neonatal target, with a repeat gas obtained after stabilization. The tube is secured and the marking is rechecked during every subsequent move. This synthetic event resolves with restored ventilation rather than a blind increase in oxygen or ventilator pressure.",findings:{"Heart rate":a(i.newbornHR,"This is neonatal bradycardia during sudden ventilation loss. The immediate intervention is effective ventilation with reassessment under neonatal resuscitation guidance.","Hypoxic bradycardia can accompany poor tone, cyanosis and absent chest movement; the event timing links these findings."),"SpO\u2082":a(i.pretermSat,"This is severe desaturation, far below the post-stabilization preterm target. The abrupt change coincides with ineffective ventilation.","Cyanosis, limpness and bradycardia may accompany ventilation failure; a monitor lag must not delay checking chest movement."),"Exhaled CO\u2082":a(d("With effective ventilation through a correctly positioned tracheal tube and adequate pulmonary blood flow, a sustained exhaled carbon dioxide waveform is expected.","newborn"),"A lost waveform is an emergency clue to displacement, obstruction, disconnection or very low pulmonary blood flow. Here the tube marking and absent chest movement support displacement.","No chest rise, absent breath sounds or sudden bradycardia may accompany tube displacement; waveform loss alone does not distinguish every cause."),"Glucose before event":a(te,"The earlier value exceeded the early maintenance target. It does not establish the current glucose or explain the abrupt airway-linked event.","Hypoglycemia can cause apnea or reduced tone, but the lost waveform and changed tube marking require immediate airway correction."),"Repeat blood gas":a(d("No repeat value has yet been measured. A normal blood gas must never be assumed from a blank result.","arterial"),"Sampling follows restoration of effective ventilation; it must not become a reason to delay rescue.","The observed bradycardia, desaturation and absent chest movement are sufficient to act before the laboratory result.")}}};var h="Poor perfusion commonly causes cool skin, weak pulses, altered consciousness and oliguria; blood pressure and the bedside examination must be considered together.",u="Respiratory compromise may produce accessory-muscle use, inability to speak comfortably, restlessness or later fatigue; a saturation reading alone cannot assess ventilation.",ie={"ards-after-pneumonia":{diagnosis:"Severe ARDS due to pneumonia",imaging:{ids:["cxr-ards-2019"],narration:"The real comparison portable chest film comes from a separate patient with viral ARDS. Both lungs contain diffuse airspace opacities instead of the usual more lucent aerated fields. This illustrates the bilateral lung injury described in our synthetic report. The appearance is not specific: edema, infection and other processes can overlap, so timing, oxygenation and exclusion of a primarily hydrostatic cause remain essential."},handoff:"The intensive care team requests transfer after pneumonia progresses over two days to diffuse lung injury and severe oxygenation failure. The synthetic imaging report describes bilateral opacities, while cardiac assessment does not support hydrostatic edema as the primary explanation. This is a pneumonia-associated ARDS case, with severity grounded in the measured oxygenation ratio.",course:"The receiving unit continues lung-protective ventilation based on predicted rather than actual body weight, evaluates plateau and driving pressures, and uses prolonged prone positioning for severe ARDS when appropriate. Antimicrobial and source-directed care continue. Over the following days in this synthetic course, oxygen requirements decline and the patient eventually separates from invasive ventilation. No isolated improvement in saturation is used to justify injurious tidal volumes or to declare the lung injury resolved.",findings:{"Heart rate":a(i.hrAdult,"This is tachycardia in severe pneumonia and respiratory failure; fever, stress and circulatory factors can contribute.",h),"Blood pressure":a(i.bpAdult,"The pressure is currently maintained on support. A supported normal-looking value is not evidence of independence from resuscitation.",h),"SpO\u2082":a(i.sat,"This is hypoxemia despite substantial ventilator oxygen support, consistent with severe gas-exchange impairment.",u),"FiO\u2082":a(d("Room air has an inspired oxygen fraction of about 0.21; higher fractions are treatment, not a normal physiological measurement.","ards"),"A fraction of 0.80 means eighty percent inspired oxygen, demonstrating a high oxygen requirement.","Persistent low saturation on high inspired oxygen may accompany extensive shunt physiology; it does not identify ARDS without the clinical and imaging criteria."),PEEP:a(d("PEEP is a ventilator setting with no universal normal value. It must be selected with oxygenation, mechanics and hemodynamic tolerance.","ards"),"Ten centimeters of water is applied end-expiratory pressure; it helps limit alveolar collapse but does not guarantee safe pressures or adequate recruitment.","Excess pressure can accompany hypotension or overdistension; inadequate recruitment can accompany persistent hypoxemia."),"Arterial pH":a(i.apH,"This is acidemia. The raised carbon dioxide establishes a respiratory component, with full chemistry needed to assess additional metabolic causes.","Acidemia may accompany cardiovascular instability; in a sedated patient symptom reporting is unavailable and monitoring carries greater weight."),"PaCO\u2082":a(i.co2,"This is mild hypercapnia. A lung-protective strategy may accept some carbon dioxide elevation while balancing pH and contraindications.","Carbon dioxide retention can cause headache or drowsiness in an awake patient; sedation makes those signs unreliable here."),"PaO\u2082":a(i.po2,"This is arterial hypoxemia on eighty percent inspired oxygen. That support context makes the oxygenation failure substantial.",u),"PaO\u2082 / FiO\u2082":a(d("A healthy oxygenation ratio is generally above 400. In invasively ventilated ARDS with PEEP of at least five, a ratio of 100 or less is the severe category, provided the other diagnostic criteria are met.","ards"),"The rounded ratio of 73 meets the severe oxygenation category in this clinical context. It is not an arterial oxygen tension by itself.","Severe ARDS commonly accompanies bilateral opacities, poor compliance and high oxygen requirements; cardiac edema and other explanations still require evaluation.")}},"ards-peep-hypotension":{diagnosis:"ARDS with hemodynamic intolerance after a PEEP increase",imaging:{ids:["cxr-ards-2019"],narration:"A real comparison film from another patient shows diffuse bilateral airspace opacity associated with ARDS. Normal aerated lungs are more lucent. This image illustrates the underlying lung injury, but it cannot tell us how much PEEP our patient will tolerate or prove the cause of the sudden pressure drop. Those questions require the bedside intervention timeline and reassessment."},handoff:"The referring ICU raises PEEP during preparation for transfer because oxygenation remains poor. Saturation improves, but pressure falls immediately afterward. The timeline creates a specific question: did the intervention improve oxygenation at the expense of cardiac filling or right-ventricular performance?",course:"The team reassesses ventilator mechanics, circulation, sedation, tube position and possible pneumothorax. No pneumothorax or new tube problem is found in this synthetic course. Returning to a better tolerated pressure strategy improves blood pressure, and oxygenation is supported through an individualized ARDS plan including positioning and hemodynamic support. The team documents both oxygenation and perfusion responses before transfer. The event is intervention-associated hemodynamic compromise, not proof that all PEEP is harmful.",findings:{"SpO\u2082":a(i.sat,"This is now within the usual reference, improved from hypoxemia at 89 percent. The improvement cannot be evaluated independently of the abrupt loss of pressure.",u),"Blood pressure":a(i.bpAdult,"This is severe hypotension after the PEEP increase, a major deterioration from the earlier preserved pressure.",h),"Heart rate":a(i.hrAdult,"This is tachycardia in the setting of new hypotension, supporting a stressed circulation rather than uncomplicated respiratory improvement.",h),PEEP:a(d("PEEP is a treatment setting, not a lab value with a normal interval. Its effects depend on lung recruitability, right-heart function and circulating volume.","ards"),"The increase from ten to sixteen centimeters of water coincides with hypotension. Reduced venous return, increased right-heart load and overdistension are considerations, not assumptions.","Poor tolerance may show a pressure fall, tachycardia and reduced perfusion; a sudden unilateral chest finding would raise concern for pneumothorax."),"PaO\u2082":a(i.po2,"This remains below the cited room-air adult laboratory interval despite seventy percent inspired oxygen. Oxygen support must be stated before judging the improvement.",u),Lactate:a(i.lactate,"This is hyperlactatemia during circulatory compromise. Follow its trend with pressure, perfusion and the response to the revised ventilator plan.",h)}},"mi-inferior-rv":{diagnosis:"Inferior STEMI with right-ventricular infarction and hemodynamic compromise",handoff:"EMS finds chest pressure, nausea and diaphoresis with hypotension and a slow pulse. The synthetic ECG report describes inferior ST elevation with reciprocal changes and right-sided lead involvement. Right-ventricular infarction is named early because it changes how the team thinks about preload and hypotension; an initially negative biomarker does not erase the ECG emergency.",course:"The team activates the reperfusion pathway, gives indicated antiplatelet treatment after contraindication review and avoids therapies that would further lower pressure. Bradycardia and perfusion are treated under the acute coronary and resuscitation pathways, with carefully reassessed support rather than unbounded fluid. In this synthetic course, catheterization finds an occluded right coronary artery, treated with percutaneous intervention. Pressure and heart rate recover after reperfusion. The angiographic result closes the loop on the inferior and right-ventricular presentation.",findings:{"Heart rate":a(i.hrAdult,"This is bradycardia with hypotension. Inferior infarction can affect nodal conduction and increase vagal influence; inspect the rhythm rather than assuming a particular block.","Symptomatic bradycardia may cause dizziness, syncope, weak pulses and reduced consciousness; here hypotension establishes clinical concern."),"Blood pressure":a(i.bpAdult,"This is hypotension in a patient with evidence of right-ventricular infarction. Preload dependence and rhythm disturbances may contribute.",h),"SpO\u2082":a(i.sat,"This is within the usual oxygenation reference on room air. It does not exclude myocardial ischemia or shock.",u),"High-sensitivity troponin":a(i.troponin,"The early result is below the local cutoff. Myocardial injury biomarkers can lag symptom onset; reperfusion decisions in this clear STEMI presentation do not wait for a positive result.","Infarction may cause pressure-like chest pain, diaphoresis, nausea and hypotension while an early troponin is still below threshold."),Potassium:a(i.k,"This is within the reference. A major measured potassium disturbance is not the explanation for the slow pulse, though serial assessment remains appropriate.","Potassium abnormalities can cause weakness and conduction changes; an in-range result does not exclude ischemic conduction disease.")}},"mi-anterior-shock":{diagnosis:"Anterior STEMI complicated by cardiogenic shock and pulmonary edema",handoff:"EMS receives a call for chest pressure followed by profound breathlessness. The synthetic ECG shows anterior ST elevation, and the bedside examination adds crackles, weak pulses and low pressure. We are presenting an anterior infarction with pump failure rather than an isolated abnormal ECG.",course:"The team activates an immediate reperfusion and shock pathway while supporting oxygenation and perfusion. Antithrombotic and hemodynamic decisions account for bleeding risk and specialist guidance. Catheterization in this synthetic course identifies an acutely occluded proximal left anterior descending artery and achieves reperfusion. The patient requires intensive care for persistent ventricular dysfunction; pressure and urine output improve with ongoing support. Successful opening of the artery does not imply immediate recovery of pump function.",findings:{"Heart rate":a(i.hrAdult,"This is tachycardia with shock, consistent with compensation for impaired stroke volume.",h),"Blood pressure":a(i.bpAdult,"This is severe hypotension with pulmonary congestion, supporting cardiogenic shock in the infarction context.",h),"Respiratory rate":a(i.rrAdult,"This is tachypnea. Pulmonary edema and shock-related metabolic stress both increase respiratory demand.",u),"SpO\u2082":a(i.sat,"This is hypoxemia on room air, consistent with clinically important gas-exchange impairment from pulmonary edema.",u),Lactate:a(i.lactate,"This is substantial hyperlactatemia with low-output shock, supporting the urgency of circulation and reperfusion care.",h),Creatinine:a(i.adultCreatinine,"This is above the general adult reference. Baseline and urine output are needed to distinguish acute hypoperfusion injury from chronic impairment.","Renal hypoperfusion may cause oliguria and rising creatinine; laboratory elevation alone does not establish its exact duration."),Troponin:a(i.troponin,"This qualitative report establishes elevation above the local cutoff. The ischemic symptoms and ECG connect myocardial injury to acute infarction.","Myocardial injury can also occur in other illnesses, so chest pain, ECG evolution and coronary findings matter more than the biomarker alone.")}},"sepsis-older-hypothermic":{diagnosis:"Urinary-source sepsis with shock and acute kidney injury in an older adult",handoff:"Family calls EMS because a previously interactive older adult becomes confused after dysuria and reduced intake. The skin is cool rather than febrile. Urinary infection is a provisional source, and the combination of shock and organ dysfunction drives immediate care while cultures and alternative sources are assessed.",course:"The team obtains cultures without delaying broad-spectrum antimicrobials and gives reassessed crystalloid with early vasopressor support when indicated. Urine output and mental status improve only after sustained circulation support. In this synthetic receiving-unit course, matching Escherichia coli grows from blood and urine and therapy is narrowed to susceptibilities. Creatinine falls toward the documented baseline during recovery, supporting an acute kidney injury component. The absence of fever was a presentation feature, not an exclusion of infection.",findings:{"Heart rate":a(i.hrAdult,"This is tachycardia with hypotension and confusion, supporting a stressed circulation.",h),"Blood pressure":a(i.bpAdult,"This is hypotension in a patient with suspected infection and new organ dysfunction.",h),"Respiratory rate":a(i.rrAdult,"This is tachypnea, which may reflect infection and metabolic stress even without primary respiratory complaints.",u),Temperature:a(i.temp,"This is hypothermia rather than fever. Older adults with sepsis may present this way.","Infection in an older adult may present with confusion, reduced function or poor intake and little or no fever; hypothermia can accompany severe illness."),Lactate:a(i.lactate,"This is marked hyperlactatemia in a poorly perfused patient. It supports urgency but does not independently identify infection or the source.",h),Creatinine:a(i.adultCreatinine,"This is elevated and more than twice the documented baseline of 0.9, supporting acute kidney injury when the timing is confirmed.","Acute kidney injury may cause oliguria and fluid or electrolyte complications, but can be nonoliguric; measure output and repeat chemistry."),Urinalysis:a(d("A normal urine microscopy does not show pathological pyuria. Interpretation depends on collection method and the laboratory threshold.","lab"),"Pyuria means excess urinary white cells. With dysuria it supports a urinary source, but pyuria alone is not proof of urinary sepsis.","Urinary infection may cause dysuria, frequency or flank pain; older patients may instead present with systemic illness and confusion.")}},"sepsis-persistent-shock":{diagnosis:"Perforated bowel with intra-abdominal sepsis and persistent septic shock",handoff:"EMS brings a patient with worsening abdominal pain, diffuse tenderness and shock. The referring CT report describes free air and fluid consistent with bowel perforation. Antibiotics and circulation support have started, but the case cannot be resolved by improving the displayed pressure while the abdominal source remains uncontrolled.",course:"The receiving surgical and critical care teams coordinate urgent source control while maintaining antibiotics and hemodynamic support. Laparotomy in this synthetic course identifies a perforated sigmoid colon with peritoneal contamination, which is treated surgically. After source control and continued resuscitation, perfusion improves, vasopressor need declines and lactate begins to fall. The established diagnosis is perforation-associated septic shock; a mean pressure near target was only one intermediate observation.",findings:{"Heart rate":a(i.hrAdult,"This is tachycardia during persistent infection and shock, requiring reassessment of perfusion, pain and ongoing source stress.",h),"Mean pressure":a(d("For adults on vasopressors with septic shock, an initial mean arterial pressure target of 65 millimeters of mercury is recommended, individualized to the patient. This is a resuscitation target, not a normal reference interval.","sepsis"),"Sixty-eight meets the initial target only with vasopressor support. It does not establish recovery when lactate is rising and organ function remains impaired.",h),"Respiratory rate":a(i.rrAdult,"This is tachypnea in abdominal sepsis, potentially reflecting acidosis, pain and systemic inflammation.",u),Lactate:a(i.lactate,"This is marked hyperlactatemia and is rising from an already elevated value of 5.9. Reassess perfusion, clearance and source control rather than declaring success from the pressure.",h),"Arterial pH":a(i.apH,"This is acidemia. The shock and raised lactate support a metabolic contribution; carbon dioxide and chemistry are required to assess compensation and additional causes.","Metabolic acidosis commonly adds rapid breathing, fatigue or altered interaction; ventilatory support must preserve adequate compensation."),Creatinine:a(i.adultCreatinine,"This is elevated, indicating renal impairment until baseline and serial measurements clarify its timing.","Renal dysfunction may accompany reduced urine output and electrolyte disturbances; organ recovery is assessed separately from pressure response.")}},"pe-preserved-pressure":{diagnosis:"Acute pulmonary embolism with right-ventricular strain and preserved blood pressure",handoff:"Eight days after hip surgery, the patient develops sudden breathlessness and pleuritic discomfort. EMS finds hypoxemia and a rapid pulse but preserved pressure. The synthetic CT pulmonary angiography report confirms bilateral pulmonary emboli and right-heart strain; the case is a confirmed embolic disease process rather than unexplained dyspnea.",course:"After bleeding and surgical risks are reviewed, the team starts indicated anticoagulation and arranges monitored care with a pulmonary embolism response service. Right-ventricular strain and biomarker elevation raise risk even without hypotension, but do not automatically justify systemic thrombolysis. In this synthetic course, pressure remains stable, oxygen need declines and the patient transitions to a longer-term anticoagulation plan after specialist review. Escalation for deterioration remains explicit during the monitored period.",findings:{"Heart rate":a(i.hrAdult,"This is tachycardia in a confirmed pulmonary embolism, consistent with stress and increased right-heart workload.",h),"Blood pressure":a(i.bpAdult,"This is preserved pressure. It does not exclude important right-ventricular strain or the possibility of deterioration.",h),"Respiratory rate":a(i.rrAdult,"This is tachypnea accompanying acute pulmonary vascular obstruction.",u),"SpO\u2082":a(i.sat,"This is hypoxemia on room air, compatible with ventilation-perfusion mismatch from embolic obstruction.",u),Troponin:a(i.troponin,"This is elevated above the local cutoff. In this confirmed embolic case, right-ventricular myocardial injury is a plausible mechanism; it does not automatically diagnose coronary occlusion.","Right-heart strain may accompany tachycardia, syncope or hypotension; biomarkers contribute to risk assessment with imaging and examination."),Lactate:a(i.lactate,"This is mildly elevated. Preserved pressure does not guarantee normal tissue perfusion, but lactate alone does not establish obstructive shock.",h)}},"pe-circulatory-collapse":{diagnosis:"High-risk pulmonary embolism causing obstructive shock",handoff:"The patient collapses after sudden breathlessness and remains hypotensive and hypoxemic when EMS arrives. Bedside ultrasound shows a dilated right ventricle, but that alone is not specific for pulmonary embolism. The team uses the acute history and overall shock assessment while considering tamponade, infarction and other causes; definitive CT is unsafe during immediate collapse.",course:"A pulmonary embolism response team coordinates urgent reperfusion after a rapid contraindication review, with anticoagulation and circulatory and respiratory support selected for the clinical context. In this synthetic course, expert catheter-based treatment demonstrates and removes a large pulmonary arterial clot burden. Perfusion and pressure improve after reperfusion, confirming the obstructive disease process, and the patient remains in intensive care. The ultrasound was an urgent supportive clue; the later procedural finding establishes the anatomical diagnosis.",findings:{"Heart rate":a(i.hrAdult,"This is marked tachycardia during collapse and shock.",h),"Blood pressure":a(i.bpAdult,"This is profound hypotension with clinical hypoperfusion, meeting the hemodynamic concern for a high-risk embolic presentation in context.",h),"Respiratory rate":a(i.rrAdult,"This is marked tachypnea during acute pulmonary vascular and circulatory failure.",u),"SpO\u2082":a(i.sat,"This is severe hypoxemia despite oxygen. Ventilation and circulation must be assessed together, because positive pressure can worsen an already failing right heart.",u),Lactate:a(i.lactate,"This is marked hyperlactatemia, consistent with major circulatory stress and poor tissue delivery in this shock presentation.",h),"Arterial pH":a(i.apH,"This is acidemia. Elevated lactate supports a metabolic component, while the full gas is needed to identify respiratory compensation or mixed failure.","Acidosis in shock may accompany rapid breathing, confusion and weak pulses; these signs guide the response while reperfusion is organized.")}}};var ne={...Z,...ee,...ae,...ie};function se(s){return s.presentations.map(n=>{let o=Y[n.id];if(!o)throw new Error(`Missing authored conference script for ${n.id}`);let l=ne[n.id];if(!l)throw new Error(`Missing clinical review for ${n.id}`);let F=p=>p.map(f=>{let S=l.findings[f.label];if(!S)throw new Error(`Missing finding interpretation for ${n.id}: ${f.label}`);return{...f,teaching:S}}),A=F(n.vitals),C=F(n.labs),M=p=>p.map(f=>`${f.spoken} ${f.teaching.reference.text} ${f.teaching.interpretation} ${f.teaching.associations}`).join(" "),ye=[...new Map([...s.sources,...l.sources??[],...[...A,...C].map(p=>p.teaching.reference.source)].map(p=>[p.url,p])).values()],b=(p,f,S,ve,we)=>({id:p,kind:f,label:S,title:o[p].title,bullets:o[p].points.length?o[p].points:void 0,focus:o[p].focus,data:we,narration:`${ve} ${o[p].commentary}`}),be=[b("presentation","scene","01 / The handoff",`Case conference. ${l.diagnosis}. This is a fictional teaching case, with clinical review pending. ${n.patient} ${n.story} ${l.handoff}`),b("assessment","scene","02 / At the bedside",n.exam),b("vitals","vitals","03 / First observations",M(A),A),b("labs","labs","04 / The investigation",M(C),C),{...b("diagnostics","diagnostics","05 / Interpret the evidence",`${n.diagnostics} ${l.imaging?.narration??(s.referenceDisease?" An optional comparison image in the visual presentation comes from a different patient; it is not this fictional patient\u2019s study.":"")}`),comparisonIds:l.imaging?.ids},{...b("decision","question","06 / Your next decision",n.question),pauseAfterSeconds:4},b("reasoning","reasoning","07 / Conference discussion",`${n.reasoning} ${n.priorities.join(" ")}`),b("reassessment","course","08 / What happened next",`${n.reassessment} ${l.course}`),{...b("synopsis","synopsis","09 / Case synopsis",`Case synopsis. ${n.synopsis}`),title:l.diagnosis,narration:`Case synopsis. ${l.diagnosis}. ${n.synopsis} ${o.synopsis.commentary} Continue to the disease lesson for the underlying physiology and further study.`}];return{...n,diagnosis:l.diagnosis,vitals:A,labs:C,topicId:s.id,topic:s.title,population:s.population,diseaseIds:s.diseaseIds,lessonIds:s.lessonIds,exams:s.exams,sources:ye,referenceDisease:s.referenceDisease,synthetic:!0,reviewStatus:"Clinical review pending",slides:be}})}var it=s=>Math.max(1,Math.round(s.slides.map(n=>n.narration).join(" ").split(/\s+/).length/145+s.slides.reduce((n,o)=>n+(o.pauseAfterSeconds??0),0)/60));var P=["FP-C","CCP-C","CCRN Adult"],re=[{id:"adult-ards",title:"ARDS",population:"Adult",diseaseIds:["ards"],lessonIds:["fpc-mech-vent","fpc-resp-sys"],exams:[...P],referenceDisease:"ards",sources:[{title:"ATS \xB7 Adult ARDS clinical practice guideline (2024)",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC10870893/"}],presentations:[{id:"ards-after-pneumonia",title:"Oxygenation worsens after pneumonia",variant:"Severe hypoxemia on invasive ventilation",patient:"A 54-year-old patient is intubated on the second day of severe pneumonia.",story:"Bilateral opacities and escalating oxygen requirements develop within 48 hours. The referring team requests transfer for advanced respiratory support.",exam:"The patient is sedated and mechanically ventilated. Breath sounds are bilateral. There is no evidence that isolated cardiac failure or fluid overload fully explains the respiratory picture.",vitals:[t("Heart rate","116","/min","Heart rate is 116 per minute."),t("Blood pressure","108/64","mmHg on support","Blood pressure is 108 over 64 on current support."),t("SpO\u2082","89","%","Saturation is 89 percent."),t("FiO\u2082","0.80","","Inspired oxygen fraction is 0.80."),t("PEEP","10","cmH\u2082O","Positive end-expiratory pressure is 10 centimeters of water.")],labs:[t("Arterial pH","7.31","","Arterial pH is 7.31."),t("PaCO\u2082","48","mmHg","Arterial carbon dioxide is 48 millimeters of mercury."),t("PaO\u2082","58","mmHg","Arterial oxygen tension is 58 millimeters of mercury."),t("PaO\u2082 / FiO\u2082","73","mmHg, rounded","The oxygen tension divided by inspired oxygen fraction is about 73.")],diagnostics:"The timing, bilateral opacities and severe oxygenation impairment on positive pressure support a severe ARDS phenotype after exclusion of a primarily hydrostatic explanation. The optional radiograph is a comparator from another patient.",question:"Should you solve this hypoxemia simply by increasing tidal volume?",reasoning:"Gas exchange must be supported while limiting ventilator-induced injury. Predicted body weight, plateau pressure, synchrony and response to PEEP matter; the patient\u2019s actual weight does not define a lung-protective tidal volume.",priorities:["Confirm measured height, predicted-body-weight ventilation and pressure assessment under the ARDS protocol.","Reassess PEEP tolerance, hemodynamics and reversible causes of deterioration.","Coordinate severe-ARDS strategies, including proning or specialist referral when indicated and operationally feasible."],reassessment:"After review of ventilation and support, gas exchange is reassessed with a repeat blood gas and pressure measurements. The team does not assume that a higher saturation means the injured lung has recovered.",synopsis:"Severe ARDS required oxygenation support balanced against lung injury. A lung-protective strategy and repeated physiological assessment guided transfer planning."},{id:"ards-peep-hypotension",title:"Better saturation, worse blood pressure",variant:"Hemodynamic cost during PEEP adjustment",patient:"A 62-year-old patient with ARDS is being prepared for an intensive care transfer.",story:"Following an increase in PEEP from 10 to 16, saturation rises but blood pressure falls. The change occurs immediately, before any new medication is given.",exam:"The patient has cooler extremities and weaker pulses. Breath sounds remain bilateral. The team examines the tube, circuit, lungs and circulation rather than attributing every change to ARDS.",vitals:[t("SpO\u2082","95","%, previously 89","Saturation has improved from 89 to 95 percent."),t("Blood pressure","76/44","mmHg, previously 112/68","Blood pressure has fallen from 112 over 68 to 76 over 44."),t("Heart rate","128","/min","Heart rate is 128 per minute."),t("PEEP","16","cmH\u2082O","Current positive end-expiratory pressure is 16 centimeters of water.")],labs:[t("PaO\u2082","76","mmHg on FiO\u2082 0.70","Arterial oxygen tension is 76 on an inspired oxygen fraction of 0.70."),t("Lactate","3.8","mmol/L","Lactate is 3.8 millimoles per liter.")],diagnostics:"Bedside assessment considers reduced venous return, right-ventricular effects, overdistension, pneumothorax and other causes. An oxygenation response alone cannot establish net benefit.",question:"Is a higher saturation an adequate endpoint if tissue perfusion is deteriorating?",reasoning:"PEEP can improve recruitment while impairing circulation in a susceptible patient. The treatment response must include perfusion, pressure and gas exchange rather than saturation alone.",priorities:["Reassess the recent ventilator change and restore an individually tolerated strategy with the critical care team.","Evaluate alternative immediate causes of hypotension and verify pressure measurements.","Trend both gas exchange and perfusion when making subsequent adjustments."],reassessment:"The team revises the support plan and repeats perfusion and gas-exchange assessment. The final handoff records the PEEP change and its opposing oxygenation and blood-pressure effects.",synopsis:"An intervention improved one measurement while worsening another. ARDS ventilator decisions required attention to the circulation as well as oxygenation."}]},{id:"adult-acs",title:"Acute myocardial infarction",population:"Adult",diseaseIds:["stemi","cardiogenic-shock","rv-failure"],lessonIds:["fpc-acs","fpc-cardiogenic","fpc-12-lead"],exams:[...P],sources:[{title:"AHA / ACC \xB7 Acute coronary syndromes guideline (2025)",url:"https://professional.heart.org/en/science-news/2025-guideline-for-the-management-of-patients-with-acute-coronary-syndromes"}],presentations:[{id:"mi-inferior-rv",title:"Inferior ST elevation with clear lungs and low pressure",variant:"Right-ventricular involvement",patient:"A 58-year-old patient develops crushing chest pain and nausea.",story:"The first ECG shows an inferior injury pattern. Before any nitrate is given, blood pressure is already low. The transfer request is for urgent coronary intervention.",exam:"The patient is pale and diaphoretic with elevated neck veins and clear lung fields. The team considers right-ventricular involvement and conduction complications.",vitals:[t("Heart rate","52","/min","Heart rate is 52 per minute."),t("Blood pressure","84/56","mmHg","Blood pressure is 84 over 56."),t("SpO\u2082","96","% on room air","Saturation is 96 percent on room air.")],labs:[t("High-sensitivity troponin","Initially below local cutoff","","The initial high-sensitivity troponin is below the laboratory\u2019s decision cutoff; this early sample does not exclude an acute occlusion."),t("Potassium","4.1","mmol/L","Potassium is 4.1 millimoles per liter.")],diagnostics:"The synthetic ECG report describes ST elevation in leads two, three and a V F, reciprocal change in one and a V L, and ST elevation in right-sided lead V four R. These findings support inferior infarction with right-ventricular involvement in context.",question:"Should a negative early troponin delay the reperfusion pathway? What does the hypotension mean for vasodilator decisions?",reasoning:"A time-critical ECG pattern must be acted on in its clinical context. Right-ventricular involvement and hypotension require careful attention to preload, rhythm and medication effects.",priorities:["Activate the appropriate acute coronary occlusion and reperfusion pathway.","Avoid treatments that worsen existing hypotension; reassess perfusion and volume responsiveness individually.","Monitor for bradyarrhythmia and conduction block and prepare indicated support."],reassessment:"The receiving catheterization team is notified of the ECG pattern, right-sided findings and unstable pressure. Serial ECGs and perfusion checks continue during stabilization.",synopsis:"An inferior infarction with possible right-ventricular involvement presented through hypotension and bradycardia. The early troponin did not overrule the clinical ECG emergency."},{id:"mi-anterior-shock",title:"Chest pain followed by pulmonary edema",variant:"Anterior infarction with cardiogenic shock",patient:"A 67-year-old patient has 90 minutes of chest pain followed by severe breathlessness.",story:"The ECG shows a large anterior injury pattern. Confusion and a falling blood pressure develop while transfer is arranged.",exam:"The patient is cool, clammy and tachypneic with bilateral crackles and weak pulses. A new murmur or other mechanical complication is actively assessed.",vitals:[t("Heart rate","124","/min","Heart rate is 124 per minute."),t("Blood pressure","78/50","mmHg","Blood pressure is 78 over 50."),t("Respiratory rate","32","/min","Respiratory rate is 32 per minute."),t("SpO\u2082","86","% on room air","Saturation is 86 percent on room air.")],labs:[t("Lactate","5.4","mmol/L","Lactate is 5.4 millimoles per liter."),t("Creatinine","1.7","mg/dL","Creatinine is 1.7 milligrams per deciliter."),t("Troponin","Above local cutoff","","High-sensitivity troponin is above the local decision cutoff.")],diagnostics:"The synthetic ECG report shows anterior ST elevation. Bedside echocardiography demonstrates severe left-ventricular systolic dysfunction; specialist assessment also evaluates mechanical complications.",question:"Does pulmonary edema exclude a simultaneous low-output circulation problem?",reasoning:"Congestion and poor forward flow can coexist. Acute infarction with shock requires immediate reperfusion planning while supporting oxygenation and circulation.",priorities:["Activate urgent coronary and cardiogenic-shock care with the receiving team.","Support oxygenation and perfusion with attention to the hemodynamic effects of respiratory interventions.","Evaluate mechanical complications and arrange advanced support capability when indicated."],reassessment:"The receiving team prepares emergency intervention. The handoff includes the ECG timeline, pressure trend, respiratory support and signs suggesting or arguing against a mechanical complication.",synopsis:"Anterior infarction produced both pulmonary congestion and systemic hypoperfusion. The resuscitation plan and destination had to address both while pursuing reperfusion."}]},{id:"adult-sepsis",title:"Adult septic shock",population:"Adult",diseaseIds:["septic-shock"],lessonIds:["fpc-sepsis","fpc-hemo-instab"],exams:[...P],sources:[{title:"SCCM \xB7 Adult Surviving Sepsis Campaign (2026)",url:"https://www.sccm.org/clinical-resources/guidelines/guidelines/surviving-sepsis-campaign-international-guidelines-for-management-of-sepsis-and-septic-shock-2026"}],presentations:[{id:"sepsis-older-hypothermic",title:"Confusion without fever",variant:"An older adult with hypothermia and poor perfusion",patient:"A 79-year-old patient has dysuria followed by new confusion.",story:"The family reports reduced intake and urine output. The patient is cold rather than febrile. The initial handoff describes \u201Cweakness,\u201D but the examination suggests a systemic illness.",exam:"There is altered attention, mottling and delayed refill. The team evaluates infection and other causes of shock and delirium.",vitals:[t("Heart rate","114","/min","Heart rate is 114 per minute."),t("Blood pressure","82/46","mmHg","Blood pressure is 82 over 46."),t("Respiratory rate","28","/min","Respiratory rate is 28 per minute."),t("Temperature","35.3","\xB0C","Temperature is 35.3 degrees Celsius.")],labs:[t("Lactate","5.1","mmol/L","Lactate is 5.1 millimoles per liter."),t("Creatinine","2.2","mg/dL, baseline 0.9","Creatinine is 2.2 milligrams per deciliter, compared with a baseline of 0.9."),t("Urinalysis","Pyuria","","Urinalysis shows pyuria, interpreted with symptoms and the broader assessment.")],diagnostics:"Suspected infection, organ dysfunction and poor perfusion prompt immediate sepsis management. The team avoids declaring a definitive urinary source from urinalysis alone.",question:"Does the absence of fever make sepsis unlikely enough to delay treatment?",reasoning:"Older adults may present with confusion or hypothermia. The source remains a working diagnosis while resuscitation and evaluation proceed.",priorities:["Deliver timely antimicrobials and obtain appropriate cultures without avoidable treatment delay.","Resuscitate and assess fluid responsiveness and tolerance; begin indicated vasoactive support under protocol.","Evaluate source control needs and alternative causes of shock."],reassessment:"After initial treatment, the team repeats perfusion assessment and reviews the pressure and urine trend. An improving number does not remove the need for source evaluation.",synopsis:"Sepsis appeared as confusion and hypothermia rather than fever. Prompt recognition depended on the systemic and perfusion findings."},{id:"sepsis-persistent-shock",title:"The pressure improves but the patient remains mottled",variant:"Persistent perfusion impairment and source-control concern",patient:"A 46-year-old patient is being transferred with severe abdominal infection.",story:"Antibiotics and initial resuscitation have begun. A vasopressor restores the displayed mean pressure, yet the patient remains poorly perfused with worsening abdominal findings.",exam:"The abdomen is distended and tender. Extremities are mottled, urine output remains low, and the team reassesses for persistent shock and an uncontrolled source.",vitals:[t("Heart rate","132","/min","Heart rate is 132 per minute."),t("Mean pressure","68","mmHg on vasopressor","Mean arterial pressure is 68 on a vasopressor."),t("Respiratory rate","30","/min","Respiratory rate is 30 per minute.")],labs:[t("Lactate","6.8","mmol/L, previously 5.9","Lactate is 6.8, increased from 5.9 millimoles per liter."),t("Arterial pH","7.25","","Arterial pH is 7.25."),t("Creatinine","2.0","mg/dL","Creatinine is 2.0 milligrams per deciliter.")],diagnostics:"The synthetic abdominal CT report describes free air and fluid with suspected bowel perforation. Surgical evaluation and source control are central; pressure restoration alone does not resolve the infection.",question:"Has resuscitation succeeded because mean pressure is now above 65?",reasoning:"A pressure value is one component of perfusion assessment. Persistent mottling, oliguria and concerning trends require reassessment of circulation, the infection source and complications.",priorities:["Escalate urgent surgical source-control planning with the receiving center.","Reassess cardiac function, perfusion and fluid tolerance rather than chasing one measurement.","Verify antimicrobial and vasoactive delivery and communicate deterioration clearly."],reassessment:"The surgical team prepares definitive intervention while the transport team maintains support. The handoff emphasizes persistent perfusion abnormalities despite improved displayed pressure.",synopsis:"A better mean pressure did not end the resuscitation. The unresolved source and continuing poor perfusion drove the next decisions."}]},{id:"adult-pe",title:"Pulmonary embolism",population:"Adult",diseaseIds:["pulmonary-embolism","obstructive-shock","rv-failure"],lessonIds:["fpc-resp-sys","fpc-hemo-instab","fpc-cardiac-dx"],exams:[...P],sources:[{title:"AHA / ACC multisociety \xB7 Acute pulmonary embolism guideline (2026)",url:"https://professional.heart.org/en/science-news/2026-guideline-for-the-evaluation-and-management-of-acute-pulmonary-embolism-in-adults"}],presentations:[{id:"pe-preserved-pressure",title:"Breathlessness after surgery",variant:"Preserved pressure with right-heart strain",patient:"A 61-year-old patient is eight days after hip surgery.",story:"Sudden dyspnea and pleuritic discomfort develop at home. The patient is tachycardic and hypoxemic but not hypotensive.",exam:"Breath sounds are clear and one calf is swollen. The team evaluates pulmonary embolism while considering other postoperative complications.",vitals:[t("Heart rate","120","/min","Heart rate is 120 per minute."),t("Blood pressure","118/74","mmHg","Blood pressure is 118 over 74."),t("Respiratory rate","30","/min","Respiratory rate is 30 per minute."),t("SpO\u2082","88","% on room air","Saturation is 88 percent on room air.")],labs:[t("Troponin","Above local cutoff","","High-sensitivity troponin is above the local decision cutoff."),t("Lactate","2.7","mmol/L","Lactate is 2.7 millimoles per liter.")],diagnostics:"A synthetic CT pulmonary angiography report confirms bilateral emboli and an enlarged right ventricle. Troponin and right-heart findings contribute to risk assessment but do not alone dictate reperfusion therapy.",question:"Does preserved blood pressure make this a routine low-risk transfer?",reasoning:"A patient may maintain pressure despite significant right-ventricular strain. Risk assessment includes clinical status, trajectory, imaging and biomarkers; recent surgery also changes bleeding considerations.",priorities:["Support oxygenation and coordinate anticoagulation and monitoring with the treating team.","Discuss risk and destination with the pulmonary embolism response or critical care team.","Prepare for deterioration and document recent surgery and bleeding risk."],reassessment:"Pressure remains stable during observation, but the team maintains monitoring and a deterioration plan. Treatment is individualized rather than decided by clot appearance alone.",synopsis:"Preserved pressure did not erase right-heart risk. The transfer plan accounted for trajectory, strain and postoperative bleeding considerations."},{id:"pe-circulatory-collapse",title:"Syncope followed by shock",variant:"High-risk embolism with circulatory failure",patient:"A 57-year-old patient develops sudden dyspnea and collapses briefly.",story:"On recovery the patient remains confused and hypotensive. There is no reported major trauma or external bleeding.",exam:"There are weak pulses, cool extremities and elevated neck veins. The lungs are relatively clear. The team considers obstructive, cardiac and other shock causes.",vitals:[t("Heart rate","138","/min","Heart rate is 138 per minute."),t("Blood pressure","70/42","mmHg","Blood pressure is 70 over 42."),t("Respiratory rate","36","/min","Respiratory rate is 36 per minute."),t("SpO\u2082","84","% on oxygen","Saturation is 84 percent on supplemental oxygen.")],labs:[t("Lactate","7.2","mmol/L","Lactate is 7.2 millimoles per liter."),t("Arterial pH","7.27","","Arterial pH is 7.27.")],diagnostics:"Bedside echocardiography shows a dilated, poorly functioning right ventricle. This supports a shock assessment but is not specific for acute pulmonary embolism. The instability may limit safe transport to CT before initial resuscitation.",question:"What is the risk of taking a profoundly unstable patient away for confirmatory imaging?",reasoning:"Shock requires immediate support and an urgent diagnostic and reperfusion strategy. Airway induction and positive pressure can further destabilize right-ventricular failure.",priorities:["Activate critical care and the pulmonary embolism response team for an urgent individualized plan.","Support circulation and oxygenation, anticipating the hemodynamic risk of airway interventions.","Coordinate bedside diagnostics and reperfusion decisions with explicit assessment of contraindications and alternative causes."],reassessment:"The receiving team selects a definitive pathway based on the evolving evidence and risk. The handoff distinguishes confirmed observations from the working diagnosis.",synopsis:"The suspected embolism presented as circulatory collapse. Stabilization, bedside assessment and specialist coordination had to precede any unsafe diagnostic transport."}]}];var R={title:"AHA / AAP \xB7 Pediatric Advanced Life Support (2025)",url:"https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/pediatric-advanced-life-support"},H=(s,n)=>({title:`Royal Children\u2019s Hospital \xB7 ${n}`,url:`https://www.rch.org.au/clinicalguide/guideline_index/${s}/`}),x=["FP-C","CCP-C","CCRN Pediatric"],oe=[{id:"child-asthma",title:"Pediatric status asthmaticus",population:"Pediatric",diseaseIds:["pediatric-asthma","pediatric-respiratory-failure","pediatric-ventilation"],lessonIds:["fpc-peds-airway-disease","fpc-peds-vent","fpc-peds-monitor"],exams:[...x],sources:[H("Acute_asthma","Acute asthma"),R],referenceDisease:"pediatric-asthma",presentations:[{id:"asthma-speaking-in-words",title:"The child who can only say one word",variant:"Severe obstruction with preserved alertness",patient:"An 8-year-old child, measured weight 26 kilograms, has asthma and a previous intensive care admission.",story:"A viral illness preceded rapidly worsening dyspnea. Home albuterol brought little relief. The child arrives sitting forward, speaking one word per breath. A caregiver reports no choking episode or allergen exposure.",exam:"The child is frightened and alert, with intercostal recession, prolonged expiration and diffuse wheeze. Air entry is reduced at both bases. The trachea is central and pulses are strong.",vitals:[t("Heart rate","148","/min","Heart rate is 148 per minute."),t("Blood pressure","110/68","mmHg","Blood pressure is 110 over 68."),t("Respiratory rate","38","/min","Respiratory rate is 38 per minute."),t("SpO\u2082","90","% on room air","Oxygen saturation is 90 percent on room air."),t("Temperature","37.6","\xB0C","Temperature is 37.6 degrees Celsius.")],labs:[t("Venous pH","7.34","","Venous blood pH is 7.34."),t("Venous PCO\u2082","43","mmHg","Venous carbon dioxide is 43 millimeters of mercury; this is not an arterial oxygen measurement."),t("Potassium","3.4","mmol/L","Potassium is 3.4 millimoles per liter.")],diagnostics:"The clinical pattern favors an acute severe asthma exacerbation. A chest radiograph is not routinely required for a typical presentation. Imaging becomes relevant if asymmetry, fever with focal findings, or a complication changes the differential.",question:"Does loud wheeze tell you how close the child is to respiratory failure? What would you trend during the first treatment cycle?",reasoning:"Wheeze requires airflow. Severity depends on work of breathing, air entry, mental status and response to treatment. An apparently reassuring carbon dioxide value does not overrule a tiring child.",priorities:["Give oxygen and repeated inhaled bronchodilator therapy with an effective interface; add indicated adjuncts under the pediatric protocol.","Reassess air entry, speech, effort and alertness after each treatment; check drug delivery before calling treatment ineffective.","Prepare escalation and pediatric critical care consultation while preserving spontaneous ventilation when feasible."],reassessment:"After initial treatment the child speaks short sentences, respiratory rate falls to 30, and saturation reaches 95 percent on supplemental oxygen. Continued monitoring and reassessment guide the transfer; a single improvement does not establish sustained stability.",synopsis:"A child with severe asthma remained alert but had marked obstruction. The useful trend was better air movement, speech and effort. Wheeze volume alone was an unreliable severity measure."},{id:"asthma-silent-chest",title:"When the wheeze disappears",variant:"Fatigue and impending ventilatory failure",patient:"A 12-year-old child, measured weight 42 kilograms, is being transferred for a severe asthma attack.",story:"Repeated bronchodilators have been delivered. During preparation for transport the child becomes quiet and stops holding the nebulizer. Staff initially describe the quieter breathing as improvement.",exam:"Air entry is now minimal, the chest is nearly silent, and respiratory effort is shallow. The child responds slowly to voice and cannot complete a sentence. There is no unilateral loss of breath sounds.",vitals:[t("Heart rate","154","/min","Heart rate is 154 per minute."),t("Blood pressure","94/58","mmHg","Blood pressure is 94 over 58."),t("Respiratory rate","18","/min, shallow","Respiratory rate has fallen from 42 to 18, with shallow breaths."),t("SpO\u2082","88","% on oxygen","Oxygen saturation is 88 percent despite supplemental oxygen.")],labs:[t("Arterial pH","7.19","","Arterial pH is 7.19."),t("PaCO\u2082","68","mmHg","Arterial carbon dioxide is 68 millimeters of mercury."),t("PaO\u2082","57","mmHg","Arterial oxygen tension is 57 millimeters of mercury on the current support.")],diagnostics:"The blood gas and examination indicate failing ventilation. The priority is bedside resuscitation, rather than delaying support for a radiograph. After stabilization, imaging can assess suspected complications.",question:"Is the fall in respiratory rate a favorable response? What risks must be anticipated if assisted ventilation becomes necessary?",reasoning:"Reduced respiratory effort with altered alertness and rising carbon dioxide indicates fatigue. Positive pressure can worsen dynamic hyperinflation and reduce venous return in severe obstruction.",priorities:["Escalate airway and ventilatory support immediately with the most experienced available team.","Continue disease-directed therapy and plan adequate expiratory time if positive-pressure ventilation is used.","Track blood pressure and ventilation; investigate sudden deterioration for air trapping, tube problems and pneumothorax."],reassessment:"After controlled airway management, the receiving team uses an obstruction-focused ventilation strategy and follows pressure, expiratory flow, gas exchange and perfusion. A gas is repeated after stabilization rather than assuming the initial settings are adequate.",synopsis:"The disappearance of wheeze accompanied exhaustion, not recovery. A quiet chest, reduced effort and declining consciousness required immediate escalation with attention to air trapping and hemodynamics."}]},{id:"child-dka",title:"Pediatric DKA",population:"Pediatric",diseaseIds:["pediatric-dka"],lessonIds:["fpc-peds-dka","fpc-peds-labs","fpc-peds-fluids"],exams:[...x],sources:[{title:"ISPAD \xB7 DKA and HHS consensus chapter",url:"https://www.ispad.org/resource/chapter-11-diabetic-ketoacidosis.html"},H("Diabetic_Ketoacidosis","Diabetic ketoacidosis")],presentations:[{id:"dka-first-diagnosis",title:"Vomiting, thirst and deep breathing",variant:"New-onset diabetes with ketoacidosis",patient:"A 10-year-old child, measured weight 30 kilograms, has no known diabetes.",story:"The family describes two weeks of thirst, frequent urination and weight loss, followed by vomiting and abdominal pain. The child is transferred after initial assessment at a community hospital.",exam:"The child is alert but tired, with dry mucosa and deep, regular breathing. Capillary refill is three seconds. There are no focal neurological findings, headache or signs of pulmonary edema.",vitals:[t("Heart rate","128","/min","Heart rate is 128 per minute."),t("Blood pressure","104/64","mmHg","Blood pressure is 104 over 64."),t("Respiratory rate","32","/min, deep","Respiratory rate is 32 with deep breaths."),t("SpO\u2082","98","% on room air","Oxygen saturation is 98 percent on room air.")],labs:[t("Glucose","480","mg/dL","Glucose is 480 milligrams per deciliter."),t("Venous pH","7.12","","Venous pH is 7.12."),t("Bicarbonate","8","mmol/L","Bicarbonate is 8 millimoles per liter."),t("\u03B2-hydroxybutyrate","5.8","mmol/L","Beta hydroxybutyrate is 5.8 millimoles per liter."),t("Potassium","4.8","mmol/L","Potassium is 4.8 millimoles per liter.")],diagnostics:"Hyperglycemia, ketonemia and metabolic acidosis support DKA. Deep breathing is compensatory. Routine cranial imaging is not indicated solely because DKA is present.",question:"Does a normal serum potassium exclude total-body depletion? What should accompany the handoff before starting a long transfer?",reasoning:"Serum potassium may appear normal despite depletion. Fluid, insulin, electrolyte and dextrose decisions depend on repeated assessment and a pediatric DKA pathway, including neurological monitoring.",priorities:["Verify measured weight, fluid history, urine output, electrolyte results and timing of insulin.","Use the pediatric DKA protocol for fluids and insulin; avoid an insulin bolus.","Arrange serial glucose, electrolytes and neurological examinations and prepare for deterioration."],reassessment:"Two hours later glucose is 330, potassium is 3.7 and the child remains alert. The team adjusts dextrose and electrolytes under its pathway while continuing treatment of ketosis. Glucose improvement alone does not mean DKA has resolved.",synopsis:"A new diagnosis of diabetes presented through vomiting and compensatory breathing. The transport task was a monitored metabolic correction, with explicit attention to potassium and neurological status."},{id:"dka-new-headache",title:"A new headache during DKA treatment",variant:"Suspected cerebral injury",patient:"A 7-year-old child, measured weight 22 kilograms, is three hours into treatment for severe DKA.",story:"The original presentation included marked dehydration and acidosis. During transfer preparation the child develops headache, vomiting and irritability, then becomes drowsy. Glucose has been falling, which initially distracts the team from the neurological change.",exam:"The child opens eyes to voice, has a new decline in interaction and a heart rate that is falling despite continued illness. Pupils are equal. No sedative has been given.",vitals:[t("Heart rate","82","/min, previously 132","Heart rate is 82, down from 132."),t("Blood pressure","128/82","mmHg","Blood pressure is now 128 over 82."),t("Respiratory rate","28","/min","Respiratory rate is 28 per minute."),t("SpO\u2082","99","% on room air","Oxygen saturation is 99 percent on room air.")],labs:[t("Glucose","290","mg/dL","Glucose is 290 milligrams per deciliter."),t("Venous pH","7.18","","Venous pH is 7.18."),t("Sodium","140","mmol/L","Measured sodium is 140 millimoles per liter."),t("Potassium","3.6","mmol/L","Potassium is 3.6 millimoles per liter.")],diagnostics:"Suspected DKA-associated cerebral injury is a clinical emergency. Equal pupils and a reasonable glucose do not exclude it. Treatment should not wait for confirmatory cranial imaging.",question:"Which change matters more here: the falling glucose or the new neurological deterioration?",reasoning:"The new headache, vomiting, change in behavior and relative slowing of heart rate raise concern for cerebral injury. Hypoglycemia and other causes still require immediate assessment, but do not delay syndrome-directed treatment.",priorities:["Call pediatric critical care and begin the protocol for suspected cerebral injury, including indicated hyperosmolar therapy.","Reassess airway protection, perfusion and glucose immediately; avoid unnecessary interruptions in care for imaging.","If intubation is unavoidable, use expert planning to preserve appropriate compensation and avoid an abrupt rise in carbon dioxide."],reassessment:"The team treats suspected cerebral injury and transfers with frequent documented neurological checks. A later scan is used to evaluate complications and alternatives after initial resuscitation; it is not the prerequisite for treatment.",synopsis:"Metabolic improvement did not ensure neurological safety. A new headache and reduced interaction during pediatric DKA required immediate assessment and treatment for possible cerebral injury."}]},{id:"child-sepsis",title:"Pediatric septic shock",population:"Pediatric",diseaseIds:["pediatric-sepsis","pediatric-shock"],lessonIds:["fpc-peds-infectious","fpc-peds-dx","fpc-peds-monitor"],exams:[...x],sources:[{title:"SCCM \xB7 Pediatric Surviving Sepsis Campaign (2026)",url:"https://sccm.org/survivingsepsiscampaign/guidelines-and-resources/surviving-sepsis-campaign-pediatric-guidelines"},R],presentations:[{id:"sepsis-normal-pressure",title:"The blood pressure is still normal",variant:"Compensated shock",patient:"A 4-year-old child, measured weight 17 kilograms, has fever and poor intake.",story:"The caregiver reports rapidly reduced interaction and no urine for eight hours. A clinic recorded a normal blood pressure and sent the child for further assessment. There is no known heart disease.",exam:"The child is lethargic but rousable, with cool mottled extremities, weak peripheral pulses and capillary refill of five seconds. Breathing is rapid without focal wheeze.",vitals:[t("Heart rate","166","/min","Heart rate is 166 per minute."),t("Blood pressure","96/58","mmHg","Blood pressure is 96 over 58."),t("Respiratory rate","40","/min","Respiratory rate is 40 per minute."),t("Temperature","39.4","\xB0C","Temperature is 39.4 degrees Celsius."),t("SpO\u2082","95","% on room air","Oxygen saturation is 95 percent on room air.")],labs:[t("Lactate","4.7","mmol/L","Venous lactate is 4.7 millimoles per liter."),t("Glucose","72","mg/dL","Glucose is 72 milligrams per deciliter."),t("Venous pH","7.28","","Venous pH is 7.28.")],diagnostics:"Suspected infection with poor perfusion raises concern for septic shock despite preserved blood pressure. Cultures and source evaluation should be coordinated without delaying time-critical treatment.",question:"Would you wait for hypotension before recognizing shock?",reasoning:"Children can maintain blood pressure through compensatory vasoconstriction. Perfusion, interaction and urine output reveal deterioration earlier. Lactate supports the assessment but cannot establish or exclude shock on its own.",priorities:["Activate pediatric sepsis care and give timely antimicrobials under the local pathway.","Use measured, reassessed fluid therapy appropriate to the setting and physiology, watching for overload.","Prepare vasoactive support when indicated and escalate early to pediatric critical care."],reassessment:"After an initial measured fluid intervention, pulses and capillary refill improve only partly. The team reassesses lungs and cardiac function before further fluid, and prepares vasoactive support rather than repeating boluses automatically.",synopsis:"Normal pressure concealed a child with clinically poor perfusion. Recognition rested on the whole examination, followed by repeated assessment of treatment response."},{id:"sepsis-fluid-intolerance",title:"Shock with new crackles",variant:"Persistent shock with fluid intolerance",patient:"A 9-year-old child, measured weight 29 kilograms, has suspected bacterial infection.",story:"The referring team has given initial fluids and antimicrobials. The child remains poorly perfused and now needs more oxygen. The transport team must decide whether additional fluid is likely to help.",exam:"The child is confused, with weak pulses, prolonged refill and new bilateral crackles. The liver edge is more prominent than in the earlier examination.",vitals:[t("Heart rate","158","/min","Heart rate is 158 per minute."),t("Blood pressure","78/42","mmHg","Blood pressure is 78 over 42."),t("Respiratory rate","36","/min","Respiratory rate is 36 per minute."),t("SpO\u2082","90","% on oxygen","Oxygen saturation is 90 percent on supplemental oxygen.")],labs:[t("Lactate","6.2","mmol/L","Lactate is 6.2 millimoles per liter."),t("Venous pH","7.23","","Venous pH is 7.23."),t("Glucose","108","mg/dL","Glucose is 108 milligrams per deciliter.")],diagnostics:"Bedside ultrasound shows reduced global ventricular function and bilateral lung B-lines. These findings inform tolerance of further fluid but do not independently prove the infection source.",question:"Does ongoing hypotension justify unlimited fluid? Which new findings change your next intervention?",reasoning:"Persistent shock can coexist with myocardial dysfunction and fluid accumulation. The next step must reflect both perfusion and fluid tolerance; cold or warm extremities alone should not dictate a vasoactive drug.",priorities:["Escalate vasoactive and respiratory support under pediatric critical care guidance.","Pause automatic fluid repetition and reassess perfusion, cardiac function and lung findings.","Recheck the infection source, antimicrobial delivery and access while preparing a high-acuity handoff."],reassessment:"With vasoactive support and respiratory assistance, perfusion begins to improve. The handoff includes total fluid volume, response to each intervention, ultrasound limitations and the evolving oxygen requirement.",synopsis:"The child needed ongoing resuscitation, but new pulmonary and cardiac findings changed its form. Fluid tolerance and perfusion must be assessed together."}]},{id:"infant-bronchiolitis",title:"Bronchiolitis",population:"Pediatric",diseaseIds:["bronchiolitis","pediatric-respiratory-failure"],lessonIds:["fpc-peds-airway-disease","fpc-peds-vent"],exams:[...x],sources:[H("Bronchiolitis","Bronchiolitis"),R],presentations:[{id:"bronchiolitis-feeding",title:"Too breathless to feed",variant:"Work of breathing and hydration",patient:"A 5-month-old infant, measured weight 6.4 kilograms, was born at term.",story:"After three days of coryza, the infant has increasing cough, reduced feeds and fewer wet diapers. There has been no witnessed apnea.",exam:"The infant is alert with subcostal recession, diffuse crackles and wheeze, and copious nasal secretions. Feeding attempts increase distress.",vitals:[t("Heart rate","164","/min","Heart rate is 164 per minute."),t("Respiratory rate","66","/min","Respiratory rate is 66 per minute."),t("SpO\u2082","88","% on room air","Oxygen saturation is persistently 88 percent on room air."),t("Temperature","37.9","\xB0C","Temperature is 37.9 degrees Celsius.")],labs:[t("Glucose","86","mg/dL","A bedside glucose is 86 milligrams per deciliter."),t("Other labs","Not routinely indicated","","Routine blood tests have not been obtained because they would not currently change management.")],diagnostics:"This is a clinical presentation of bronchiolitis. Routine chest radiographs and viral testing are not necessary for every typical case; testing depends on the clinical question and setting.",question:"What does the inability to feed add to the respiratory assessment?",reasoning:"Respiratory distress can compromise both ventilation and hydration. Supportive care and reassessment are central; wheeze in an infant does not automatically imply asthma.",priorities:["Support oxygenation and clear obstructing nasal secretions when needed.","Plan hydration that the infant can tolerate safely.","Escalate respiratory support for persistent distress, hypoxemia, apnea or fatigue under the local pediatric pathway."],reassessment:"With support, saturation reaches 94 percent, but respiratory rate remains high. The team continues to assess effort and hydration rather than declaring success from saturation alone.",synopsis:"The infant needed assessment of breathing and feeding together. A better saturation did not erase the ongoing work of breathing or hydration problem."},{id:"bronchiolitis-apnea",title:"The infant who stops breathing",variant:"Apnea in a young former preterm infant",patient:"A 6-week-old infant, measured weight 3.6 kilograms, was born at 34 weeks gestation.",story:"The caregiver reports nasal congestion and two episodes of pallor with absent breathing. Another episode occurs during assessment.",exam:"Between episodes there is only mild recession. During the observed apnea the infant becomes limp and the heart rate falls. Mild visible effort between episodes is misleading.",vitals:[t("Heart rate during apnea","76","/min","Heart rate falls to 76 during apnea."),t("SpO\u2082 during apnea","72","%","Oxygen saturation falls to 72 percent during the episode."),t("Temperature","36.5","\xB0C","Temperature is 36.5 degrees Celsius.")],labs:[t("Glucose","68","mg/dL","Glucose is 68 milligrams per deciliter."),t("Venous pH","7.27","","After stabilization, venous pH is 7.27."),t("Venous PCO\u2082","59","mmHg","Venous carbon dioxide is 59 millimeters of mercury.")],diagnostics:"Apnea requires stabilization and evaluation for causes beyond bronchiolitis, including infection and metabolic or neurological disease. A viral prodrome does not close the differential.",question:"Can you judge safety from the infant\u2019s appearance between events?",reasoning:"Young age and prematurity increase concern when apnea is present. Intermittent loss of ventilation may be more urgent than the work of breathing observed between episodes.",priorities:["Provide immediate airway positioning and effective ventilation when breathing is inadequate.","Use continuous cardiorespiratory monitoring and prepare a reliable escalation plan.","Discuss neonatal or pediatric critical care destination and evaluation for alternative causes."],reassessment:"Assisted ventilation restores the heart rate and saturation. Recurrent episodes make unmonitored transfer unsafe. The team documents event timing, interventions and recovery.",synopsis:"Apnea dominated the risk despite limited distress between episodes. The infant required an active ventilation plan and broader diagnostic assessment."}]},{id:"child-croup",title:"Croup",population:"Pediatric",diseaseIds:["croup","pediatric-airway"],lessonIds:["fpc-peds-airway-disease","fpc-peds-dx"],exams:[...x],sources:[H("Croup_Laryngotracheobronchitis","Croup"),R],referenceDisease:"croup",presentations:[{id:"croup-at-rest",title:"A barking cough in the night",variant:"Stridor at rest",patient:"A 2-year-old child, measured weight 12 kilograms, has a viral prodrome.",story:"The child wakes with a barking cough and noisy inspiration. Stridor persists while calm on a caregiver\u2019s lap.",exam:"The child is alert, with inspiratory stridor and moderate sternal recession. There is no drooling, tripod posture or reported choking. The voice is hoarse.",vitals:[t("Heart rate","142","/min","Heart rate is 142 per minute."),t("Respiratory rate","34","/min","Respiratory rate is 34 per minute."),t("SpO\u2082","96","% on room air","Oxygen saturation is 96 percent on room air."),t("Temperature","38.1","\xB0C","Temperature is 38.1 degrees Celsius.")],labs:[t("Blood tests","Not indicated initially","","No routine laboratory tests are needed for this typical clinical presentation.")],diagnostics:"The pattern is consistent with croup. The optional neck image is a separate reference example; a typical child does not need an X-ray to establish the diagnosis.",question:"Does a normal oxygen saturation mean the upper-airway obstruction is mild?",reasoning:"Upper-airway narrowing may be important before oxygen saturation falls. Stridor at rest, recession, behavior and air entry guide severity assessment.",priorities:["Keep the child calm and minimize distressing interventions.","Use corticosteroid and nebulized epinephrine when indicated by the clinical pathway.","Observe for recurrence and escalate if response is inadequate or the presentation is atypical."],reassessment:"Stridor resolves at rest after therapy. The team observes for recurrence according to the local pathway and communicates the medication and observation timeline.",synopsis:"The child had clinically meaningful upper-airway obstruction despite normal saturation. Calm assessment and treatment response guided care."},{id:"croup-exhaustion",title:"The quieter child with stridor",variant:"Exhaustion and an atypical differential",patient:"A 3-year-old child, measured weight 14 kilograms, has worsening noisy breathing.",story:"The initial barking cough is followed by increasing distress. During assessment the child becomes drowsy and the stridor becomes softer.",exam:"There is severe recession, poor air movement and reduced interaction. The team considers croup alongside bacterial tracheitis, epiglottitis and foreign-body obstruction.",vitals:[t("Heart rate","168","/min","Heart rate is 168 per minute."),t("Respiratory rate","22","/min, reduced effort","Respiratory rate has fallen to 22 with reduced effort."),t("SpO\u2082","86","% on oxygen","Oxygen saturation is 86 percent on supplemental oxygen.")],labs:[t("Blood tests","Deferred during resuscitation","","Laboratory sampling is deferred because it must not delay airway support.")],diagnostics:"A critically narrowed airway must be supported before diagnostic imaging. Avoid upsetting the child with unnecessary throat examination or positioning.",question:"What does softer stridor mean when air entry and consciousness are also worsening?",reasoning:"Reduced noise may reflect reduced airflow and exhaustion. An atypical or poorly responsive course broadens the differential and calls for expert airway support.",priorities:["Summon pediatric airway expertise immediately and prepare a coordinated rescue plan.","Support oxygenation and ventilation while minimizing agitation.","Treat the likely cause under protocol without sending an unstable child away for imaging."],reassessment:"An experienced team manages the airway in a controlled resuscitation setting. The handoff describes the trajectory of noise, effort and consciousness rather than just the last saturation.",synopsis:"Less airway noise was a warning because airflow and alertness were also falling. Severity followed physiology, not sound volume."}]}];var ke={title:"AHA / AAP \xB7 Pediatric Advanced Life Support (2025)",url:"https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/pediatric-advanced-life-support"},le={title:"AHA / AAP \xB7 Neonatal Resuscitation (2025)",url:"https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/neonatal-resuscitation"},ce=["FP-C","CCP-C","CCRN Neonatal"],de=[{id:"newborn-duct",title:"Duct-dependent circulation",population:"Neonatal",diseaseIds:["duct-dependent-circulation","transitional-circulation","congenital-heart","right-left-shunt"],lessonIds:["fpc-neonatal"],exams:[...ce],sources:[ke,le],presentations:[{id:"duct-systemic-shock",title:"The newborn who deteriorates at home",variant:"Suspected duct-dependent systemic blood flow",patient:"A 6-day-old term newborn weighs 3.2 kilograms.",story:"Feeding and urine output have declined over a day. The infant now looks gray and breathes rapidly. No congenital heart diagnosis was made before discharge.",exam:"The infant is poorly responsive, with weak femoral pulses, cool legs and a prolonged refill time. Upper-extremity pulses are easier to feel. Sepsis remains an urgent competing diagnosis.",vitals:[t("Heart rate","188","/min","Heart rate is 188 per minute."),t("Right-arm pressure","68/42","mmHg","Right-arm blood pressure is 68 over 42."),t("Leg pressure","44/26","mmHg","Leg blood pressure is 44 over 26; measurement quality is being checked."),t("Respiratory rate","72","/min","Respiratory rate is 72 per minute."),t("Preductal SpO\u2082","94","%","Right-hand oxygen saturation is 94 percent.")],labs:[t("Venous pH","7.14","","Venous pH is 7.14."),t("Lactate","7.1","mmol/L","Lactate is 7.1 millimoles per liter."),t("Glucose","58","mg/dL","Glucose is 58 milligrams per deciliter.")],diagnostics:"The combination of age, poor systemic perfusion and pulse differences raises concern for critical congenital heart disease as the duct closes. Definitive anatomy requires expert echocardiography. Saturation alone cannot exclude poor systemic blood flow.",question:"Would a saturation in the nineties reassure you about systemic perfusion?",reasoning:"A duct-dependent systemic lesion can present as shock rather than profound cyanosis. Sepsis and other causes must be addressed in parallel until the cause is established.",priorities:["Consult neonatal and cardiac specialists urgently; arrange definitive echocardiography and a capable destination.","Discuss prostaglandin therapy for suspected duct dependence under protocol, anticipating apnea and an airway support requirement.","Support perfusion, temperature and glucose while evaluating infection and other causes of neonatal shock."],reassessment:"The cardiac team directs stabilization and transfer. The handoff includes limb pressures, pulse findings, perfusion trends and any response to therapy. The anatomical diagnosis is not assumed from the examination alone.",synopsis:"The newborn\u2019s chief problem was systemic perfusion. Critical heart disease remained possible despite a relatively preserved right-hand saturation."},{id:"duct-cyanotic-newborn",title:"Blue despite oxygen",variant:"Suspected duct-dependent pulmonary flow or mixing lesion",patient:"A 3-day-old term newborn weighs 3.5 kilograms.",story:"The infant has persistent central cyanosis and feeds poorly. Supplemental oxygen produces little change in saturation.",exam:"The infant is cyanotic with modest respiratory effort. Breath sounds are equal. The presentation prompts consideration of congenital heart disease, pulmonary hypertension, lung disease and infection.",vitals:[t("Heart rate","164","/min","Heart rate is 164 per minute."),t("Respiratory rate","54","/min","Respiratory rate is 54 per minute."),t("Preductal SpO\u2082","76","% on oxygen","Right-hand oxygen saturation is 76 percent on supplemental oxygen."),t("Postductal SpO\u2082","74","% on oxygen","Foot oxygen saturation is 74 percent on supplemental oxygen.")],labs:[t("Arterial pH","7.29","","Arterial pH is 7.29."),t("PaO\u2082","38","mmHg","Arterial oxygen tension is 38 millimeters of mercury on the current oxygen support."),t("Lactate","3.5","mmol/L","Lactate is 3.5 millimoles per liter.")],diagnostics:"Echocardiography is needed urgently to distinguish structural disease and pulmonary hypertension. A small preductal\u2013postductal difference does not rule out a cardiac lesion.",question:"Should you keep increasing oxygen while postponing a cardiac evaluation?",reasoning:"Severe hypoxemia with limited response to oxygen requires a broader circulation-focused assessment. The required balance of pulmonary and systemic blood flow depends on the anatomy.",priorities:["Support ventilation and oxygenation while obtaining neonatal cardiac consultation.","Discuss prostaglandin and transport planning under the specialist pathway; prepare for apnea if it is used.","Use specialist-directed oxygen and ventilation goals rather than imposing one saturation target on every congenital lesion."],reassessment:"Expert echocardiography establishes the lesion and the stabilization goals. The transport team verifies that infusion, airway and oxygen supplies can sustain the planned journey.",synopsis:"Persistent cyanosis required assessment of circulation as well as lungs. Definitive anatomy, rather than a generic oxygen target, guided subsequent care."}]},{id:"preterm-respiratory",title:"Preterm respiratory distress",population:"Neonatal",diseaseIds:["neonatal-rds","neonatal-ventilation"],lessonIds:["fpc-neonatal","fpc-multiple-birth"],exams:[...ce],sources:[le],referenceDisease:"neonatal-rds",presentations:[{id:"rds-grunting-newborn",title:"Grunting after a preterm delivery",variant:"Early respiratory distress with spontaneous breathing",patient:"A newborn delivered at 30 weeks gestation weighs 1.4 kilograms.",story:"Within minutes of birth there is persistent grunting and increasing oxygen need. The infant continues to breathe spontaneously. The team is preparing neonatal transport.",exam:"The infant has retractions and reduced air entry with equal chest movement. Temperature control and minimizing heat loss are active priorities.",vitals:[t("Heart rate","162","/min","Heart rate is 162 per minute."),t("Respiratory rate","74","/min","Respiratory rate is 74 per minute."),t("SpO\u2082","89","% at 25 minutes, on support","At 25 minutes of age, saturation is 89 percent on respiratory support."),t("Temperature","36.1","\xB0C","Temperature is 36.1 degrees Celsius.")],labs:[t("Arterial pH","7.25","","Arterial pH is 7.25."),t("PaCO\u2082","55","mmHg","Arterial carbon dioxide is 55 millimeters of mercury."),t("Glucose","61","mg/dL","Glucose is 61 milligrams per deciliter.")],diagnostics:"A synthetic radiology report describes low lung volumes, diffuse granular opacities and air bronchograms, consistent with surfactant-deficiency RDS in context. Infection and other causes of respiratory distress still require assessment.",question:"What would make you escalate beyond noninvasive support?",reasoning:"Spontaneous breathing permits noninvasive support in selected preterm infants, but increasing oxygen need, apnea, poor ventilation or exhaustion require escalation. Oxygen targets depend on postnatal age and the neonatal pathway.",priorities:["Maintain warmth and use neonatal respiratory support appropriate to the infant\u2019s effort and gas exchange.","Obtain neonatal specialist guidance on surfactant and airway escalation.","Check glucose, interface fit, pressure delivery and supplies before departure."],reassessment:"After respiratory and thermal support, effort improves and temperature reaches 36.7 degrees. The team continues to assess oxygen requirement and gases rather than assuming the early response will persist.",synopsis:"A preterm infant\u2019s respiratory distress was managed alongside thermal and metabolic needs. The treatment pathway followed response and specialist neonatal goals."},{id:"rds-sudden-desaturation",title:"Sudden desaturation in the transport incubator",variant:"A superimposed airway equipment problem",patient:"A 29-week newborn, weight 1.2 kilograms, is intubated for respiratory distress.",story:"During movement into the transport incubator, saturation abruptly falls and the ventilator alarms. The infant had been stable on the same settings immediately before movement.",exam:"Chest movement is now reduced, the capnography trace disappears and the heart rate falls. The team checks the infant, tube and circuit together.",vitals:[t("Heart rate","88","/min","Heart rate has fallen to 88 per minute."),t("SpO\u2082","68","%","Oxygen saturation is 68 percent."),t("Exhaled CO\u2082","No waveform","","No exhaled carbon dioxide waveform is currently detected.")],labs:[t("Glucose before event","79","mg/dL","Glucose before the event was 79 milligrams per deciliter."),t("Repeat blood gas","Not yet obtained","","No new blood gas is available; immediate ventilation takes priority over sampling.")],diagnostics:"Abrupt deterioration during movement raises concern for displacement, obstruction, equipment failure or pneumothorax. Absence of a capnography signal requires assessment in context, including circulation and small tidal volumes.",question:"Should you first increase ventilator settings, or establish whether ventilation is reaching the infant?",reasoning:"A sudden change needs a structured patient-to-device assessment. Previously appropriate settings cannot compensate for a displaced tube or disconnected circuit.",priorities:["Establish effective ventilation immediately using the neonatal rescue approach.","Check tube position and patency, circuit connections and oxygen delivery; assess for pneumothorax if indicated.","Escalate airway management with neonatal expertise and reconfirm ventilation after every movement."],reassessment:"The team identifies a displaced tube and restores effective ventilation with the neonatal airway plan. Heart rate rises and a consistent carbon dioxide waveform returns. Tube position and securement are rechecked before transport resumes.",synopsis:"The acute event was a ventilation failure superimposed on RDS. Immediate patient and equipment assessment mattered more than a reflex increase in ventilator settings."}]}];var he={title:"ACOG \xB7 Preeclampsia and hypertension in pregnancy",url:"https://www.acog.org/womens-health/faqs/preeclampsia-and-high-blood-pressure-during-pregnancy"},pe={title:"ACOG \xB7 Gestational hypertension and preeclampsia (Practice Bulletin 222)",url:"https://www.acog.org/clinical/clinical-guidance/practice-bulletin/articles/2020/06/gestational-hypertension-and-preeclampsia"},ue={title:"ACOG \xB7 Emergent therapy for severe hypertension (Committee Opinion 767)",url:"https://pubmed.ncbi.nlm.nih.gov/30575639/"},Ae={title:"WHO / FIGO / ICM \xB7 Postpartum haemorrhage consolidated guidance",url:"https://www.ncbi.nlm.nih.gov/books/NBK619233/"},Ce={title:"RCOG \xB7 Antepartum haemorrhage",url:"https://www.rcog.org.uk/guidance/browse-all-guidance/green-top-guidelines/antepartum-haemorrhage-green-top-guideline-no-63/"},k=["FP-C","CCP-C","CCRN Adult"],me=[{id:"maternal-hypertension",title:"Preeclampsia and eclampsia",population:"Obstetric",diseaseIds:["preeclampsia","eclampsia"],lessonIds:["fpc-preeclampsia","fpc-ob-dx","fpc-ob-pharm"],exams:[...k],sources:[pe,he,ue],presentations:[{id:"preeclampsia-visual-symptoms",title:"Headache and flashing lights at 33 weeks",variant:"Severe hypertension with neurological symptoms",patient:"A 28-year-old patient is pregnant at 33 weeks and 2 days, with a singleton pregnancy.",story:"Persistent headache, flashing lights and right upper quadrant discomfort develop over several hours. There is no seizure, vaginal bleeding or known chronic hypertension.",exam:"The patient is alert with brisk reflexes and mild dependent edema. The lungs are clear. Severe blood pressure readings persist when repeated with an appropriate cuff.",vitals:[t("Heart rate","104","/min","Maternal heart rate is 104 per minute."),t("Blood pressure","174/114","mmHg, repeated","Blood pressure is 174 over 114 and remains severe on repeat assessment."),t("SpO\u2082","97","% on room air","Maternal saturation is 97 percent on room air."),t("Fetal heart rate","150","/min","Fetal heart rate is 150 per minute at this assessment.")],labs:[t("Platelets","118","\xD710\u2079/L","Platelet count is 118 billion per liter."),t("AST","85","U/L","A S T is 85 units per liter."),t("Creatinine","1.2","mg/dL","Creatinine is 1.2 milligrams per deciliter.")],diagnostics:"The findings support preeclampsia with severe features. Proteinuria testing contributes to evaluation but is not required to recognize severe disease when other qualifying features are present.",question:"Does magnesium replace an antihypertensive? Can a currently normal fetal rate justify delaying maternal stabilization?",reasoning:"Seizure prevention and treatment of severe blood pressure serve different purposes. Maternal stabilization protects both patients, and the fetus requires ongoing assessment rather than a single reassuring number.",priorities:["Begin urgent obstetric escalation and treat persistent severe hypertension under the obstetric protocol.","Give indicated magnesium for seizure prophylaxis and monitor breathing, reflexes, renal function and infusion delivery.","Coordinate maternal and fetal monitoring and the specialist plan for delivery after stabilization."],reassessment:"Blood pressure improves under treatment and headache lessens, but the patient still requires specialist obstetric management. The handoff includes repeat pressures, symptoms, laboratory trends and exact medication times.",synopsis:"Severe maternal hypertension with neurological symptoms required urgent care. Blood pressure control and seizure prophylaxis were complementary interventions, not interchangeable ones."},{id:"eclampsia-postpartum",title:"A seizure five days after delivery",variant:"Delayed postpartum eclampsia",patient:"A 32-year-old patient is five days postpartum after an apparently uncomplicated delivery.",story:"A severe headache and visual disturbance are followed by a generalized seizure. The family did not realize a pregnancy-related emergency could occur after discharge.",exam:"After the seizure the patient is confused, with spontaneous breathing and no obvious trauma. The team evaluates glucose and considers intracranial hemorrhage, thrombosis and other seizure causes alongside eclampsia.",vitals:[t("Heart rate","118","/min","Heart rate is 118 per minute."),t("Blood pressure","182/116","mmHg","Blood pressure is 182 over 116."),t("Respiratory rate","24","/min","Respiratory rate is 24 per minute."),t("SpO\u2082","93","% on room air","Saturation is 93 percent on room air.")],labs:[t("Glucose","106","mg/dL","Glucose is 106 milligrams per deciliter."),t("Platelets","156","\xD710\u2079/L","Platelet count is 156 billion per liter."),t("Creatinine","1.0","mg/dL","Creatinine is 1.0 milligrams per deciliter.")],diagnostics:"Postpartum timing does not exclude eclampsia. Atypical features, focal deficits or persistent altered mental status increase the need for urgent neurological evaluation and imaging after stabilization.",question:"Does a completed delivery remove eclampsia from the differential?",reasoning:"Eclampsia can occur postpartum and without prior recognition of preeclampsia. Simultaneous evaluation of alternative seizure causes prevents premature closure.",priorities:["Protect airway and ventilation, prevent injury and treat suspected eclampsia with magnesium under protocol.","Treat persistent severe hypertension and arrange immediate obstetric consultation.","Reassess neurological recovery and pursue urgent imaging or additional diagnostics when indicated."],reassessment:"The seizure stops and the team continues close respiratory and neurological monitoring. The handoff explicitly states postpartum day five, because pregnancy history remains relevant after delivery.",synopsis:"A recent delivery remained a critical part of the seizure history. Recognition of postpartum eclampsia supported immediate treatment while alternative neurological emergencies were evaluated."}]},{id:"maternal-hellp",title:"HELLP syndrome",population:"Obstetric",diseaseIds:["hellp","preeclampsia"],lessonIds:["fpc-maternal","fpc-ob-labs","fpc-preeclampsia"],exams:[...k],sources:[pe,he,ue],presentations:[{id:"hellp-epigastric-pain",title:"\u201CIt feels like bad indigestion\u201D",variant:"Epigastric pain and evolving laboratory injury",patient:"A 30-year-old patient is pregnant at 35 weeks and 1 day.",story:"Nausea and upper abdominal pain worsen through the afternoon. The patient initially attributes the symptoms to reflux. There is no external bleeding.",exam:"Right upper quadrant tenderness and malaise are present. The patient is alert. The team is concerned about a systemic pregnancy complication rather than treating the pain as isolated indigestion.",vitals:[t("Heart rate","112","/min","Heart rate is 112 per minute."),t("Blood pressure","162/108","mmHg","Blood pressure is 162 over 108."),t("SpO\u2082","97","%","Saturation is 97 percent."),t("Fetal heart rate","155","/min","Fetal heart rate is 155 per minute.")],labs:[t("Platelets","62","\xD710\u2079/L","Platelet count is 62 billion per liter."),t("AST","280","U/L","A S T is 280 units per liter."),t("LDH","920","U/L","L D H is 920 units per liter."),t("Smear","Schistocytes","","The laboratory reports schistocytes on the blood smear.")],diagnostics:"Hemolysis, elevated liver enzymes and low platelets support HELLP syndrome in context. Severe or escalating abdominal pain also raises concern for hepatic complications requiring urgent specialist assessment.",question:"Which laboratory pattern connects the abdominal pain to a time-critical obstetric disorder?",reasoning:"The platelet count and evidence of liver injury and hemolysis change the meaning of an apparently gastrointestinal complaint. Obstetric evaluation must accompany resuscitation.",priorities:["Escalate immediately to obstetric and critical care teams and coordinate definitive care.","Monitor for bleeding, neurological change and worsening abdominal pain; repeat laboratories as directed.","Treat associated severe hypertension and provide indicated seizure prophylaxis under the obstetric pathway."],reassessment:"The receiving team arranges urgent obstetric management. Serial symptoms and laboratory values are communicated, with preparation for hemorrhage and blood products if required.",synopsis:"Abdominal pain became a systemic emergency when interpreted with thrombocytopenia, hemolysis and liver injury. HELLP required prompt specialist management."},{id:"hellp-without-severe-bp",title:"The laboratory results are worse than the pressure",variant:"HELLP with nonsevere blood pressure",patient:"A 26-year-old patient is 18 hours postpartum.",story:"Persistent upper abdominal pain, nausea and profound malaise continue after delivery. The blood pressure has not reached the severe range, and the initial concern is postoperative discomfort.",exam:"The patient is pale with right upper quadrant tenderness and new petechiae around venipuncture sites. Mental status and breathing are currently normal.",vitals:[t("Heart rate","108","/min","Heart rate is 108 per minute."),t("Blood pressure","142/90","mmHg","Blood pressure is 142 over 90."),t("SpO\u2082","98","%","Saturation is 98 percent.")],labs:[t("Platelets","48","\xD710\u2079/L","Platelet count is 48 billion per liter."),t("AST","340","U/L","A S T is 340 units per liter."),t("LDH","1080","U/L","L D H is 1080 units per liter."),t("Haptoglobin","Low","","Haptoglobin is low, supporting hemolysis in this context.")],diagnostics:"HELLP can present postpartum and without severe hypertension. Other thrombotic microangiopathies and liver disorders must also be considered by the specialist team.",question:"Can a blood pressure of 142 over 90 exclude a serious pregnancy-related microangiopathy?",reasoning:"The absence of severe hypertension does not negate major platelet, liver and hemolysis abnormalities. Delivery also does not guarantee immediate resolution.",priorities:["Obtain urgent obstetric and critical care review and trend the laboratory abnormalities.","Assess for active bleeding and evolving hepatic or neurological complications.","Plan monitored transfer and specialist management rather than waiting for severe hypertension to develop."],reassessment:"The platelet count is repeated and the clinical course is monitored closely. The handoff emphasizes the postpartum timing and the trajectory of symptoms and laboratories.",synopsis:"Nonsevere blood pressure was a misleading reassurance. The laboratory and symptom pattern still required urgent assessment for HELLP and its mimics."}]},{id:"postpartum-bleeding",title:"Postpartum hemorrhage",population:"Obstetric",diseaseIds:["postpartum-hemorrhage","uterine-atony","obstetric-hemorrhage"],lessonIds:["fpc-delivery-complications","fpc-maternal","fpc-ob-labs"],exams:[...k],sources:[Ae],presentations:[{id:"pph-boggy-uterus",title:"The bleeding continues after birth",variant:"Uterine atony",patient:"A 29-year-old patient is 20 minutes postpartum after vaginal delivery at term.",story:"Measured blood loss is approximately 1,200 milliliters and rising. The placenta has been delivered. The patient feels faint and nauseated.",exam:"The uterus is boggy and enlarged, with ongoing brisk bleeding. The patient is pale with cool extremities. The team evaluates tone, trauma, tissue and coagulation causes together.",vitals:[t("Heart rate","132","/min","Heart rate is 132 per minute."),t("Blood pressure","88/52","mmHg","Blood pressure is 88 over 52."),t("Respiratory rate","28","/min","Respiratory rate is 28 per minute."),t("SpO\u2082","97","%","Saturation is 97 percent.")],labs:[t("Hemoglobin","10.4","g/dL, early sample","Early hemoglobin is 10.4 grams per deciliter; this does not exclude major acute blood loss."),t("Fibrinogen","190","mg/dL","Fibrinogen is 190 milligrams per deciliter."),t("Lactate","4.9","mmol/L","Lactate is 4.9 millimoles per liter.")],diagnostics:"The bedside finding of a boggy uterus supports atony, while continued assessment looks for additional causes. Imaging must not delay hemorrhage control and resuscitation.",question:"Would you wait for hemoglobin to fall before activating a hemorrhage response?",reasoning:"Acute bleeding can initially leave a deceptively preserved hemoglobin. The observed blood loss and shock require action, and a relatively low fibrinogen is concerning in obstetric hemorrhage.",priorities:["Activate the obstetric hemorrhage pathway, including source control, uterine measures and indicated uterotonics.","Coordinate blood products and timely tranexamic acid when indicated, with warming and monitoring under protocol.","Quantify ongoing loss and escalate promptly for mechanical or surgical control if bleeding continues."],reassessment:"Bleeding slows after treatment but the team continues quantification and perfusion monitoring. Total blood loss, uterotonic times, blood products and coagulation results accompany the handoff.",synopsis:"Atony caused major hemorrhage with shock. The response followed physiology and ongoing loss rather than waiting for a late hemoglobin change."},{id:"pph-firm-uterus",title:"Heavy bleeding with a firm uterus",variant:"Trauma or retained tissue requires reassessment",patient:"A 34-year-old patient is 45 minutes postpartum after an instrument-assisted birth.",story:"The patient has ongoing bleeding despite uterine measures. The uterus is now firm, and the estimated loss exceeds 1,500 milliliters.",exam:"The patient is pale and anxious. The referring team reports concern for a genital tract laceration and an incomplete placental examination.",vitals:[t("Heart rate","140","/min","Heart rate is 140 per minute."),t("Blood pressure","82/46","mmHg","Blood pressure is 82 over 46."),t("Temperature","35.8","\xB0C","Temperature is 35.8 degrees Celsius.")],labs:[t("Hemoglobin","8.1","g/dL","Hemoglobin is 8.1 grams per deciliter."),t("Fibrinogen","145","mg/dL","Fibrinogen is 145 milligrams per deciliter."),t("Platelets","94","\xD710\u2079/L","Platelet count is 94 billion per liter.")],diagnostics:"A firm uterus with persistent bleeding prompts urgent evaluation for trauma, retained tissue and coagulopathy. Successful treatment of one cause does not exclude another.",question:"What does persistent hemorrhage after the uterus firms up change in the plan?",reasoning:"Repeating the same atony intervention without reassessing the source can delay definitive control. Multiple causes of postpartum hemorrhage may coexist.",priorities:["Continue hemorrhage resuscitation and obtain immediate obstetric evaluation for source control.","Communicate the firm uterus, delivery instrumentation and uncertainty about placental completeness.","Maintain warming, blood product coordination and serial coagulation assessment under the hemorrhage pathway."],reassessment:"The obstetric team proceeds to definitive assessment and repair while resuscitation continues. The transfer timeline includes all interventions and ongoing bleeding rather than a single estimated total.",synopsis:"A firm uterus did not mean the hemorrhage was controlled. Persistent bleeding required a renewed search for trauma, tissue and coagulation problems."}]},{id:"abruption",title:"Placental abruption",population:"Obstetric",diseaseIds:["placental-abruption","obstetric-hemorrhage"],lessonIds:["fpc-delivery-complications","fpc-ob-dx","fpc-ob-monitor"],exams:[...k],sources:[Ce],presentations:[{id:"abruption-concealed",title:"Severe pain with very little visible blood",variant:"Concealed bleeding and fetal compromise",patient:"A 31-year-old patient is pregnant at 34 weeks and 4 days.",story:"Sudden abdominal pain is followed by reduced fetal movement. Only a small amount of dark vaginal blood is visible.",exam:"The uterus is tender and persistently firm. The patient is pale and diaphoretic with weak peripheral pulses.",vitals:[t("Heart rate","126","/min","Maternal heart rate is 126 per minute."),t("Blood pressure","92/58","mmHg","Maternal pressure is 92 over 58."),t("Fetal heart rate","95","/min, persistent","Fetal heart rate remains near 95 per minute.")],labs:[t("Hemoglobin","10.8","g/dL","Hemoglobin is 10.8 grams per deciliter."),t("Fibrinogen","165","mg/dL","Fibrinogen is 165 milligrams per deciliter."),t("Platelets","110","\xD710\u2079/L","Platelet count is 110 billion per liter.")],diagnostics:"The clinical pattern raises urgent concern for abruption. Blood can be concealed behind the placenta. A reassuring ultrasound does not reliably exclude the diagnosis.",question:"Can the small visible blood loss explain away the signs of shock?",reasoning:"External bleeding can underestimate total hemorrhage. Maternal resuscitation and urgent obstetric action are needed when pain, uterine findings and fetal compromise suggest abruption.",priorities:["Activate urgent obstetric and hemorrhage support and coordinate the fastest appropriate definitive care.","Resuscitate the mother with positioning, access and indicated blood products under protocol.","Continue maternal and fetal assessment without delaying action for a scan."],reassessment:"The receiving obstetric team prepares immediate intervention while the transport team supports maternal circulation. Concealed blood loss and evolving coagulation abnormalities remain central handoff concerns.",synopsis:"Abruption can hide major bleeding. Uterine pain and firmness, maternal shock and fetal compromise outweighed the small amount of visible blood."},{id:"abruption-trauma",title:"Abdominal pain after a low-speed crash",variant:"Trauma-associated abruption",patient:"A 25-year-old patient is pregnant at 30 weeks and 5 days.",story:"After a restrained motor-vehicle collision, the patient develops abdominal pain and frequent contractions. There is no visible vaginal bleeding.",exam:"The patient is alert with uterine tenderness and a superficial seat-belt mark. There are no obvious long-bone injuries.",vitals:[t("Heart rate","112","/min","Maternal heart rate is 112 per minute."),t("Blood pressure","116/72","mmHg","Maternal blood pressure is 116 over 72."),t("Fetal heart rate","170","/min with recurrent decelerations","Fetal heart rate is 170 with recurrent decelerations on the referring monitor.")],labs:[t("Hemoglobin","11.2","g/dL","Hemoglobin is 11.2 grams per deciliter."),t("Fibrinogen","250","mg/dL","Fibrinogen is 250 milligrams per deciliter and will be interpreted with its trend and clinical context.")],diagnostics:"Trauma evaluation includes maternal injuries and pregnancy complications. Abruption remains possible despite normal maternal pressure and no external bleeding. Fetal monitoring contributes information but cannot replace maternal assessment.",question:"Does the apparently minor crash mechanism establish a low-risk pregnancy assessment?",reasoning:"A modest mechanism does not exclude important placental injury. Pain, contractions and fetal changes require urgent obstetric evaluation alongside trauma care.",priorities:["Follow maternal trauma priorities and assess for occult injury.","Obtain obstetric consultation and appropriate ongoing fetal monitoring.","Trend pain, uterine activity, perfusion and bleeding and prepare for deterioration during transfer."],reassessment:"The patient is transferred to a center capable of trauma and obstetric intervention. The handoff includes crash details, symptoms, monitoring findings and the absence of external bleeding without treating that absence as reassurance.",synopsis:"The pregnancy assessment followed symptoms and monitoring rather than the apparent crash severity. Concealed placental injury remained a time-critical concern."}]},{id:"peripartum-heart",title:"Peripartum cardiomyopathy",population:"Obstetric",diseaseIds:["peripartum-cardiomyopathy"],lessonIds:["fpc-maternal","fpc-heart-failure","fpc-cardiogenic"],exams:[...k],sources:[{title:"American Heart Association \xB7 Peripartum cardiomyopathy",url:"https://www.heart.org/en/health-topics/cardiomyopathy/what-is-cardiomyopathy-in-adults/peripartum-cardiomyopathy-ppcm"}],referenceDisease:"acute-heart-failure",presentations:[{id:"ppcm-cannot-lie-flat",title:"\u201CI cannot breathe lying down\u201D",variant:"Postpartum pulmonary congestion",patient:"A 33-year-old patient is three weeks postpartum with no known cardiac disease.",story:"Progressive dyspnea and leg swelling have been attributed to recovery and sleep loss. The patient now sleeps sitting upright and has a cough.",exam:"There are bilateral crackles, elevated neck veins and peripheral edema. The patient is tachypneic but alert.",vitals:[t("Heart rate","122","/min","Heart rate is 122 per minute."),t("Blood pressure","118/76","mmHg","Blood pressure is 118 over 76."),t("Respiratory rate","30","/min","Respiratory rate is 30 per minute."),t("SpO\u2082","89","% on room air","Saturation is 89 percent on room air.")],labs:[t("BNP","1480","pg/mL","B N P is 1,480 picograms per milliliter."),t("Creatinine","1.1","mg/dL","Creatinine is 1.1 milligrams per deciliter.")],diagnostics:"A synthetic echocardiography report describes global left-ventricular systolic dysfunction with ejection fraction 28 percent. Chest imaging shows pulmonary congestion. Peripartum cardiomyopathy is considered after evaluation for other causes; BNP alone does not establish the diagnosis.",question:"Which findings distinguish this from expected postpartum fatigue or isolated dependent edema?",reasoning:"Orthopnea, hypoxemia, pulmonary findings and systolic dysfunction indicate pathological heart failure. Pulmonary embolism and other causes of postpartum dyspnea must also be evaluated.",priorities:["Support oxygenation and consider noninvasive respiratory support when appropriate.","Coordinate cardiology and obstetric care and treat congestion under a pregnancy-aware heart-failure pathway.","Monitor perfusion and rhythm and avoid reflexive large fluid administration."],reassessment:"With respiratory and congestion-directed treatment, breathing improves. Cardiac follow-up and a longer-term plan are arranged; early symptom relief does not establish recovery of ventricular function.",synopsis:"Postpartum dyspnea was a heart-failure presentation. Orthopnea and objective cardiac dysfunction required a cardiac evaluation rather than attribution to normal recovery."},{id:"ppcm-shock",title:"Cold extremities after delivery",variant:"Low-output failure and cardiogenic shock",patient:"A 36-year-old patient is ten days postpartum.",story:"Rapidly worsening dyspnea is accompanied by confusion and scant urine. The patient has received a small fluid intervention with no improvement.",exam:"The patient is cool and clammy with weak pulses, crackles and elevated neck veins. The team recognizes simultaneous congestion and poor perfusion.",vitals:[t("Heart rate","138","/min","Heart rate is 138 per minute."),t("Blood pressure","78/48","mmHg","Blood pressure is 78 over 48."),t("Respiratory rate","34","/min","Respiratory rate is 34 per minute."),t("SpO\u2082","88","% on oxygen","Saturation is 88 percent on supplemental oxygen.")],labs:[t("Lactate","5.8","mmol/L","Lactate is 5.8 millimoles per liter."),t("Creatinine","1.8","mg/dL","Creatinine is 1.8 milligrams per deciliter.")],diagnostics:"Bedside echocardiography shows severe global left-ventricular dysfunction. The differential includes peripartum cardiomyopathy and other causes of acute heart failure or shock. A single echocardiographic finding does not replace etiological evaluation.",question:"Would more fluid necessarily improve the pressure in a patient who is both congested and poorly perfused?",reasoning:"Cardiogenic shock requires support of forward flow while respecting pulmonary congestion. Respiratory interventions can also alter hemodynamics, so escalation needs careful planning.",priorities:["Activate cardiogenic-shock and obstetric consultation with a destination capable of advanced circulatory support.","Support oxygenation and perfusion under specialist guidance; reassess tolerance of each intervention.","Communicate the postpartum timing and evaluate alternative causes including ischemia and embolic disease."],reassessment:"The receiving team prepares intensive care and possible mechanical support while transfer stabilization continues. The handoff includes urine output, oxygen requirement and response to each intervention.",synopsis:"The postpartum patient had a low-output shock presentation with pulmonary congestion. Support and destination planning had to address the failing circulation and the lungs together."}]}];var Se=[...oe,...me,...de,...re],N=Se.flatMap(se),bt=Object.fromEntries(N.map(s=>[s.id,s])),ge=s=>N.filter(n=>n.diseaseIds.includes(s)),fe=s=>N.filter(n=>n.lessonIds.includes(s));var m=G(V(),1);function xt({lessonId:s,diseaseId:n}){let o=s?fe(s):ge(n??"");return(0,m.jsxs)("section",{className:"case-primer","aria-label":"Start with a case conference",children:[(0,m.jsx)("span",{className:"eyebrow",children:"Patient first"}),(0,m.jsx)("h3",{children:"Start with a case conference"}),(0,m.jsx)("p",{children:o.length?`${o.length} synthetic case drafts \xB7 narrated slides or audio listening`:"A complete conference for this topic is in preparation."}),o.length?(0,m.jsx)("ul",{children:o.map(l=>(0,m.jsx)("li",{children:(0,m.jsxs)("button",{onClick:()=>E(l.id,{lesson:s,disease:n}),children:[(0,m.jsx)("b",{children:l.title}),(0,m.jsx)("small",{children:l.variant})]})},l.id))}):(0,m.jsx)("button",{className:"act",onClick:()=>E(null,{lesson:s,disease:n}),children:"View case coverage & available cases"})]})}export{it as a,N as b,bt as c,ge as d,fe as e,xt as f};
